def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Helper to obtain field names and values
    def _get_fields_and_values(obj):
        if hasattr(obj, "_keys") and hasattr(obj, "_values"):
            return list(obj._keys), list(obj._values)
        # Try to get mapping if the object is dict‑like
        try:
            mapping = dict(obj)
            return list(mapping.keys()), list(mapping.values())
        except Exception:
            pass
        # Fall back to object attributes
        attrs = {
            k: v for k, v in vars(obj).items()
            if not k.startswith("_") and not callable(v)
        }
        return list(attrs.keys()), list(attrs.values())

    all_keys, all_values = _get_fields_and_values(self)

    # If no keys requested, return the full dictionary
    if not keys:
        return dict(zip(all_keys, all_values))

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Index lookup
            if key < 0 or key >= len(all_keys):
                raise IndexError(f"Index {key} out of bounds for record of size {len(all_keys)}")
            field_name = all_keys[key]
            result[field_name] = all_values[key]
        else:
            # Key name lookup
            if key in all_keys:
                idx = all_keys.index(key)
                result[key] = all_values[idx]
            else:
                result[key] = None
    return result

