            try:
                return dict(tuple(key_order[i], getattr(self, key_order[i], None)) for i in range(len(key_order)))
            except Exception:
                # Order of operations: build dict from list of pairs
                return dict(key_order)

    result = {}
    for k in keys:
        # Determine the actual key name
        if isinstance(k, int):
            if k < 0 or k >= len(key_order):
                raise IndexError(
                    f"Index {k} out of bounds for record with {len(key_order)} fields"
                )
            key_name = key_order[k]
        else:
            key_name = k

        # Retrieve the value or use None if the key is missing
        try:
            value = self[key_name]
        except Exception:
            # For mappings that might not support direct indexing or key not present
            try:
                value = getattr(self, key_name, None)
            except Exception:
                value = None
        result[key_name] = value
    return result

