    message = {
        "mode": mode,
        "bookmarks": bookmark_list,
        "metadata": metadata,
        "timeout": timeout,
        "database": db,
        "impersonated_user": imp_user,
        "dehydration_hooks": dehydration_hooks,
        "hydration_hooks": hydration_hooks
    }

    # Append the message to the output queue
    try:
