    except NameError:
        # Fallback minimal response if Response is unavailable
        class _DummyResponse:
            def __init__(self, msg, **h):
                self.message = msg
                self.handlers = h
        return _DummyResponse(message, **handlers)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    mode_val = mode if mode is not None else "WRITE"
    try:
        if mode_val not in ("READ", "WRITE"):
            raise ValueError(f"mode must be 'READ' or 'WRITE', got {mode!r}")
    except Exception as exc:
        raise ValueError(f"Invalid mode: {exc}") from exc

    # Validate bookmarks
    if bookmarks is not None:
        try:
            iter(bookmarks)
            bookmarks_list = list(bookmarks)
        except TypeError as exc:
            raise ValueError("bookmarks must be an iterable") from exc
    else:
        bookmarks_list = None

    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise ValueError("metadata must be a dict")

    # Validate timeout
    if timeout is not None and not isinstance(timeout, (int, float)):
        raise ValueError("timeout must be a number")

    # Validate db
    if db is not None and not isinstance(db, str):
        raise ValueError("db must be a string")

    # Validate imp_user
    if imp_user is not None and not isinstance(imp_user, str):
        raise ValueError("imp_user must be a string")

    # Validate hooks
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise ValueError("dehydration_hooks must be a dict")

    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise ValueError("hydration_hooks must be a dict")

    params = {"mode": mode_val}
    if bookmarks_list is not None:
        params["bookmarks"] = bookmarks_list
    if metadata is not None:
        params["metadata"] = metadata
    if timeout is not None:
        params["timeout"] = timeout
    if db is not None:
        params["db"] = db
    if imp_user is not None:
        params["imp_user"] = imp_user
    if dehydration_hooks is not None:
        params["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks is not None:
        params["hydration_hooks"] = hydration_hooks

    # Append to output queue
    try:
        if not hasattr(self, "_output_queue"):
            self._output_queue = []
        self._output_queue.append(("BEGIN", params))
    except Exception as exc:
        raise RuntimeError(f"Failed to append BEGIN message: {exc}") from exc

    # Return Response object
    try:
        return Response(self, **handlers)
    except Exception:
        # Fallback to a simple object if Response is not available
        class _DummyResponse:
            def __init__(self, message, handlers):
                self.message = message
                self.handlers = handlers
            def __repr__(self):
                return f"<DummyResponse message={self.message!r} handlers={self.handlers!r}>"
        return _DummyResponse(("BEGIN", params), handlers)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
           db=None, imp_user=None, dehydration_hooks=None,
           hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        hydration function). Hydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is not None:
        if not isinstance(mode, str):
            raise ValueError(f"mode must be a string or None, got {type(mode).__name__}")
        mode_upper = mode.upper()
        if mode_upper not in ("READ", "WRITE"):
            raise ValueError(f"mode must be 'READ' or 'WRITE', got '{mode}'")
        mode = mode_upper

    # Validate bookmarks
    if bookmarks is not None:
        try:
            bookmarks = [str(b) for b in bookmarks]
        except Exception as e:
            raise ValueError("bookmarks must be an iterable of convertible to str") from e

    # Validate metadata
    if metadata is not None:
        if not isinstance(metadata, dict):
            raise ValueError(f"metadata must be a dict, got {type(metadata).__name__}")

    # Validate timeout
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise ValueError(f"timeout must be a number, got {type(timeout).__name__}")

    # Validate db
    if db is not None and not isinstance(db, str):
        raise ValueError(f"db must be a string, got {type(db).__name__}")

    # Validate imp_user
    if imp_user is not None and not isinstance(imp_user, str):
        raise ValueError(f"imp_user must be a string, got {type(imp_user).__name__}")

    # Validate dehydration_hooks
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise ValueError("dehydration_hooks must be a dict")
        for key, func in dehydration_hooks.items():
            if not isinstance(key, type):
                raise ValueError(f"dehydration_hooks keys must be types, got {key!r}")
            if not callable(func):
                raise ValueError(f"dehydration hook for {key!r} is not callable")

    # Validate hydration_hooks
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise ValueError("hydration_hooks must be a dict")
        for key, func in hydration_hooks.items():
            if not isinstance(key, type):
                raise ValueError(f"hydration_hooks keys must be types, got {key!r}")
            if not callable(func):
                raise ValueError(f"hydration hook for {key!r} is not callable")

    # Build message payload
    payload = {}
    if mode is not None:
        payload['mode'] = mode
    if bookmarks is not None:
        payload['bookmarks'] = bookmarks
    if metadata is not None:
        payload['metadata'] = metadata
    if timeout is not None:
        payload['timeout'] = timeout
    if db is not None:
        payload['database'] = db
    if imp_user is not None:
        payload['impersonatedUser'] = imp_user
    if dehydration_hooks is not None:
        payload['dehydrationHooks'] = dehydration_hooks
    if hydration_hooks is not None:
        payload['hydrationHooks'] = hydration_hooks

    # Append to output queue
    try:
        # The actual queue attribute might differ; adjust accordingly.
        self._outbound_queue.append(('BEGIN', payload))
    except AttributeError as e:
        raise AttributeError("The connection object does not have an outbound queue to append to.") from e
    except Exception as e:
        raise RuntimeError("Failed to enqueue BEGIN message.") from e

    # Return a Response object that will handle incoming messages
    try:
        return Response(**handlers)
    except Exception as e:
        raise RuntimeError("Failed to create Response object.") from e

def round_half_to_even(n):
    """
    Rounds the given number to the nearest integer using the banker's rounding
    scheme (round half to even).

    The function accepts numeric inputs (int or float). If the input is
    non-numeric, a TypeError is raised.

    :param n: numeric value to round
    :return: integer result of the rounding
    """
    # Quick check for int or float types
    if isinstance(n, (int, float)):
        return int(round(n))
    # Attempt to convert to float for other numeric-like objects
    try:
        return int(round(float(n)))
    except Exception:
        raise TypeError(f"round_half_to_even expects a numeric input; got {type(n).__name__}")

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Basic validation of inputs
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple of field names")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Prepare class attributes. Each field is defaulted to None.
    attrs = {f: None for f in fields if isinstance(f, str)}
    # Store the SRID mapping as a protected attribute
    attrs["_srid_map"] = srid_map

    # Try to find a Point base class in the global namespace; fall back to object.
    PointBase = globals().get("Point", object)

    # The constructor just assigns keyword values to the fields.
    def __init__(self, *args, **kwargs):
        # Ignore positional args since we have no knowledge of the base __init__ signature.
        for key in fields:
            if key in kwargs:
                setattr(self, key, kwargs[key])

    attrs["__init__"] = __init__

    # Dynamically create the new class.
    new_cls = type(name, (PointBase,), attrs)
    return new_cls

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Local import to avoid global namespace pollution
    try:
        from shapely.geometry import Point as BasePoint
    except Exception as e:
        raise ImportError("shapely.geometry.Point is required for point_type") from e

    # Validate input types
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple of field names")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary mapping field names to SRIDs")

    # Ensure field names are strings and srid_map has matching keys
    field_set = set()
    for f in fields:
        if not isinstance(f, str):
            raise TypeError(f"field name {f!r} is not a string")
        field_set.add(f)

    if set(srid_map.keys()) != field_set:
        missing = field_set - set(srid_map.keys())
        extra = set(srid_map.keys()) - field_set
        messages = []
        if missing:
            messages.append(f"Missing SRID entries for fields: {', '.join(missing)}")
        if extra:
            messages.append(f"Unknown fields in SRID map: {', '.join(extra)}")
        raise ValueError("; ".join(messages))

    # Define the custom __init__
    def __init__(self, x, y, **kwargs):
        # Initialize the base Point
        BasePoint.__init__(self, x, y)
        # Assign any additional fields
        for field in fields:
            setattr(self, field, kwargs.get(field))
        # Store SRID map for potential future use
        self._srid_map = {field: srid_map[field] for field in fields}

    # Prepare class attributes
    class_dict = {
        "__init__": __init__,
        "__doc__": f"{name} (dynamic Point subclass) with fields: {', '.join(fields)}",
        "_fields": tuple(fields),
        "_srid_map": srid_map,
    }

    # Dynamically create and return the new subclass
    return type(name, (BasePoint,), class_dict)

def deprecated(message):
    """Decorator that warns when a function or method is used.\n\n    :param message: The deprecation message that will be displayed.\n    :type message: str\n    :raises TypeError: If the provided message is not a string.\n    :return: A decorator that wraps the original function.\n    """
    if not isinstance(message, str):
        raise TypeError("deprecation message must be a string")
    def decorator(func):
        warning_module = __import__("warnings")
        wraps_module = __import__("functools")
        @wraps_module.wraps(func)
        def wrapper(*args, **kwargs):
            warning_module.warn(message, category=warning_module.DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        import warnings
        from functools import wraps
        @wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

