    return decorator

def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    if code is None:
        return ""
    if not isinstance(code, str):
        raise TypeError("code must be a string")
    # R options that control console behaviour, error display, etc.
    r_options = [
        "options(restoreConsole = FALSE)",
        "options(show.error.messages = FALSE)",
        "options(max.print = 10000)",
    ]
    # Strip trailing whitespace to avoid double newlines
    code_stripped = code.rstrip()
    if code_stripped:
        return "\n".join(r_options + [code_stripped])
    else:
        return "\n".join(r_options)

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    try:
        from collections.abc import Sequence as _Sequence
        if seq is None:
            raise TypeError("seq cannot be None")
        if not isinstance(seq, _Sequence):
            raise TypeError(f"Expected a sequence, got {type(seq).__name__}")
        for i, item in enumerate(seq):
            if not isinstance(item, str):
                raise TypeError(f"Element at index {i} is not a string")
        import random
        rng = random.Random(0)
        out = list(seq)
        rng.shuffle(out)
        return out
    except Exception as exc:
        raise RuntimeError(f"_shuffled failed: {exc}") from exc

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("parse_version expects a string argument")
    s = s.strip()
    if not s:
        return ()
    nums = []
    for part in s.split('.'):
        num_str = ''
        for char in part:
            if char.isdigit():
                num_str += char
            else:
                break
        if num_str:
            try:
                nums.append(int(num_str))
            except ValueError:
                # Should not happen since we only accumulate digits
                continue
    return tuple(nums)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Splits the string into sequences of digits and returns a tuple of integers.
    Non-digit characters act as separators. Empty or non-string input raises an exception.
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")

    nums = []
    current = ''
    for ch in s:
        if ch.isdigit():
            current += ch
        else:
            if current:
                try:
                    nums.append(int(current))
                except Exception as exc:
                    raise ValueError(f"Failed to convert '{current}' to int") from exc
                current = ''
    if current:
        try:
            nums.append(int(current))
        except Exception as exc:
            raise ValueError(f"Failed to convert '{current}' to int") from exc
    return tuple(nums)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    # The intent is to extract numeric components from the string and
    # return them as a tuple of ints.  If the input does not contain
    # any numeric data or if any error occurs, an empty tuple is returned
    # so that callers can handle the failure gracefully.
    try:
        import re
        # Find all sequences of digits in the string
        matches = re.findall(r"\d+", s)
        # Convert each sequence to an int
        return tuple(int(x) for x in matches)
    except Exception:
        # In the face of unexpected input or runtime errors,
        # return an empty tuple rather than raising an exception.
        return ()

def parse_version(s: str) -> tuple[int, ...]:
