def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        if maxsize <= 0:
            return func
        cache = collections.OrderedDict()
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Build key
            if typed:
                key = args + tuple(type(arg) for arg in args)
            else:
                key = args
            if kwargs:
                # Sort keyword args to ensure key order
                items = tuple(sorted(kwargs.items()))
                if typed:
                    # include types of keyword values
                    kwkey = items + tuple((k, type(v)) for k, v in items)
                else:
                    kwkey = items
                key = key + kwkey
            now = timer()
            if key in cache:
                value, expire_time = cache.pop(key)
                if expire_time > now:
                    # Reinsert to mark as recently used
                    cache[key] = (value, expire_time)
                    return value
                # expired; remove and fall through to recompute
            # Compute fresh value
            value = func(*args, **kwargs)
            expire_time = now + ttl
            if len(cache) >= maxsize:
                cache.popitem(last=False)  # remove LRU
            cache[key] = (value, expire_time)
            return value
        def cache_clear():
            cache.clear()
        wrapper.cache_clear = cache_clear
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorating_function(user_function):
        if maxsize <= 0:
            # Cache disabled
            def wrapper(*args, **kw):
                return user_function(*args, **kw)
            return wrapper

        cache = {}
        _recency = []   # list of keys in order least recent -> most recent

        def _make_key(args, kw, typed):
            key = args
            if kw:
                kw_items = tuple(sorted(kw.items()))   # deterministic order
