                # Shorten file path
                parts = f.filename.split(os.sep)
                if len(parts) > max_path_level:
                    short_path = os.sep.join(parts[-max_path_level:])
                else:
                    short_path = f.filename

                trace_lines.append(
                    f'  File "{short_path}", line {f.lineno}, in {f.name}'
                )
                if f.line is not None:
                    trace_lines.append(f"    {f.line.strip()}")

            return exc_msg + "\n" + "\n".join(trace_lines)
        except Exception:
            return str(e)

