def _reset_logging(cls):
    """
    Reset logging configuration by clearing all existing handlers and reinitializing
    the root logger with default settings.
    """
    try:
        import logging
        root_logger = logging.getLogger()
        # Remove and close all existing handlers from the root logger
        while root_logger.handlers:
            handler = root_logger.handlers.pop()
            try:
                handler.close()
            except Exception:
                # Ignore errors while closing handlers
                pass
        # Reconfigure logging with default settings
        logging.basicConfig()
    except Exception as exc:
        # If logging is already broken, log the error to stderr
        try:
            logging.getLogger().error("Failed to reset logging: %s", exc)
        except Exception:
            pass
        raise RuntimeError("Unable to reset logging") from exc

