def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Validate input
    if not isinstance(orderings, (list, tuple)):
        raise TypeError("orderings must be a list or tuple of iterables")

    # Record first appearance index for each element
    first_appear = {}
    idx = 0
    for ordering in orderings:
        try:
            it = iter(ordering)
        except TypeError:
            raise TypeError("Each ordering must be iterable")
        for item in it:
            if item not in first_appear:
                first_appear[item] = idx
                idx += 1

    # Build graph adjacency list and indegree counts
    adj = {}
    indegree = {}
    for ordering in orderings:
        # check for duplicate elements within the same ordering
        seen_in_order = set()
        for item in ordering:
            if item in seen_in_order:
                raise ValueError(f"Duplicate element {item!r} in a single ordering")
            seen_in_order.add(item)
            if item not in adj:
                adj[item] = set()
            if item not in indegree:
                indegree[item] = 0
        # add edges between consecutive elements
        for u, v in zip(ordering, ordering[1:]):
            if v not in adj[u]:
                adj[u].add(v)
                indegree[v] = indegree.get(v, 0) + 1

    # Ensure all nodes have indegree entry
    for node in adj:
        indegree.setdefault(node, 0)

    # Use a priority queue (min-heap) based on first appearance
    import heapq
    zero_queue = []
    for node, deg in indegree.items():
        if deg == 0:
            heapq.heappush(zero_queue, (first_appear.get(node, float('inf')), node))

    result = []
    while zero_queue:
        _, node = heapq.heappop(zero_queue)
        result.append(node)
        for neigh in adj.get(node, ()):
            indegree[neigh] -= 1
            if indegree[neigh] == 0:
                heapq.heappush(zero_queue, (first_appear.get(neigh, float('inf')), neigh))

    if len(result) != len(adj):
        raise ValueError("Orderings contain a cycle or conflicting constraints")

    return result

