    # Additionally include attributes from instance __dict__ not present in class dict
    # This covers dynamically added attributes or those defined as instance variables.
    try:
        instance_attrs = getattr(self, "__dict__", {})
        for name, val in instance_attrs.items():
            if not all and name.startswith("_"):
