def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if sequence is None:
        return [] if output is None else output

    # Ensure we only work with a list for the output
    if output is None:
        output = []
    elif not isinstance(output, list):
        raise TypeError("output must be a list or None")

    try:
        iterator = iter(sequence)
    except TypeError:
        # sequence is not iterable, treat it as a single argument
        output.append(sequence)
        return output

    for item in iterator:
        # Expand any tuple or list items (but keep other iterables such as
        # sets or generators as individual items).
        if isinstance(item, (tuple, list)):
            for subitem in item:
                output.append(subitem)
        else:
            output.append(item)

    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # Determine the container to use for the result
    if output is None:
        output = []

    # Helper recursive function to flatten nested iterables
    def _flatten(item, acc):
        if isinstance(item, str):
            # Treat strings as indiv interfaces / specs
            acc.append(item)
        elif isinstance(item, (list, tuple, set)):
            # Recursively flatten nested iterables
            for sub in item:
                _flatten(sub, acc)
        else:
            # Base case: any other object is an indiv spec
            acc.append(item)

    try:
        # The sequence itself must be iterable (except None)
        if sequence is None:
            return output
        iterator = iter(sequence)  # Raise TypeError if not iterable
    except TypeError as exc:
        raise TypeError("The provided sequence must be iterable") from exc

    flattened = []
    _flatten(sequence, flattened)

    # Append the flattened items to the output container
    try:
        output.extend(flattened)
    except AttributeError as exc:
        # If output does not support extend, fall back to appending one by one
        for item in flattened:
            try:
                output.append(item)
            except AttributeError:
                raise TypeError("Output object must support extend or append operations") from exc

    return output

