        init_val = getattr(self, "initial_value", None)
        if init_val is not None:
            # Preserve existing bin structure if present
            existing_bins = getattr(self, "bins", None)
            if existing_bins is not None and isinstance(existing_bins, (list, tuple)):
                num_bins = len(existing_bins)
                self.bins = [init_val] * num_bins if num_bins > 0 else []
            else:
                # No existing bins; create a single-bin histogram
                self.bins = [init_val]
        else:
            make_bins_fn = getattr(self, "make_bins", None)
            if callable(make_bins_fn):
                self.bins = make_bins_fn()
            else:
                # Fallback to an empty bins list
                self.bins = []
    except Exception as exc:
        # In case reinitialization fails we provide a clear error
        raise RuntimeError("Failed to reinitialize histogram bins") from exc

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset the current context to an empty dictionary
        self.context = {} if hasattr(self, "context") else {}

        # Reinitialize bins
        if hasattr(self, "bins") and hasattr(self, "initial_value"):
            # If bins were provided, set each bin to the initial value
            for key in self.bins:
                self.bins[key] = self.initial_value
        elif hasattr(self, "make_bins") and callable(self.make_bins):
            # If make_bins is defined, use it to regenerate bins
            self.bins = self.make_bins()
        else:
            # Fall back: clear bins if present
            if hasattr(self, "bins"):
                self.bins = {}
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram: {exc}") from exc

def reset(self):
