    # Reset context
    try:
        self.context = {}
    except Exception as exc:
        raise RuntimeError("Unable to reset context to an empty dict") from exc

    # Reinitialize bins
    try:
        # If an explicit initial value is defined, use it
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # If it is a mapping, copy to avoid accidental shared references
            if isinstance(self.initial_value, dict):
                self.bins = self.initial_value.copy()
            else:
