def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    Parameters
    ----------
    separator : str, optional
        Delimiter for values. Defaults to comma.
    header : str, optional
        First line of the output. If supplied, a newline is appended
        after it automatically.

    Returns
    -------
    str
        CSV representation of the graph.

    Notes
    -----
    The graph is expected to contain points in one of three clear
    formats: a ``points`` dictionary mapping coordinates to values,
    a dictionary via ``items()``, or an iterable yielding
    ``(coordinate, value)`` tuples.  If none of these are found a
    ``ValueError`` is raised.  Coordinated and values are coerced to
    strings using ``repr``-like conversion; iterables are flattened
    one level each.  The method is tolerant of missing or invalid
    data, skipping over items that cannot be unpacked.
    """
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")

    lines = []
    if header is not None:
        lines.append(str(header))

    # Resolve source of graph data
    try:
        data_iter = self.points.items()
    except AttributeError:
        try:
            data_iter = self.items()
        except AttributeError:
            if hasattr(self, "__iter__"):
                data_iter = iter(self)
            else:
                raise ValueError("Graph has no recognizable data source")

    for item in data_iter:
        # item should be a (coord, value) pair
        if isinstance(item, tuple) and len(item) == 2:
            coord, value = item
        else:
            # item not a pair; skip this entry
            continue

        # Handle coordinate, which may be a scalar or iterable
        if isinstance(coord, (str, bytes)):
            coord_parts = [coord]
        else:
            try:
                coord_parts = list(coord)
            except TypeError:
                coord_parts = [coord]
        coord_strs = [str(c) for c in coord_parts]

        # Handle value, also iterable or scalar
        if isinstance(value, (str, bytes)):
            value_parts = [value]
        else:
            try:
                value_parts = list(value)
            except TypeError:
                value_parts = [value]
        value_strs = [str(v) for v in value_parts]

        lines.append(separator.join(coord_strs + value_strs))

    return "\n".join(lines)

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Basic validation -------------------------------------------------------
    if not isinstance(separator, str):
        raise TypeError(f"separator must be a string, got {type(separator)!r}")
    # header may be any string-like; if provided, ensure it is converted to str
    if header is not None and not isinstance(header, str):
        header = str(header)

    # Prepare output lines -----------------------------------------------
    lines = []

    if header is not None:
        lines.append(header)

    for point in self:
        # Attempt to unpack point into coordinate(s) and value(s)
        try:
            coord, *vals = point
        except Exception as exc:
            raise ValueError(f"Unable to unpack point {point!r}") from exc

        # Convert coordinates ---------------------------------------------------------------------------------
        if isinstance(coord, (list, tuple)):
            coord_parts = [str(c) for c in coord]
        else:
            coord_parts = [str(coord)]

        # Convert value parts ----------------------------------------------------------------------------------
        if vals:
            val_parts = []
            for v in vals:
                # If the value component is an iterable (but not a string/bytes)
                if isinstance(v, (list, tuple)):
                    val_parts.extend(str(x) for x in v)
                else:
                    val_parts.append(str(v))
        else:
            val_parts = []

        line = separator.join(coord_parts + val_parts)
        lines.append(line)

    # Join with newline and ensure trailing newline is not added unnecessarily
    return "\n".join(lines)

def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional, for each point first its
    coordinate is converted to string (separated by *separator*), then
    each part of its value.

    Handles ``self.points`` being a dict, a list/tuple of points, or any
    iterable where each element is either a two‑tuple ``(coords, value)``
    or a single value treated as a coordinate with an empty value.

    Returns a string containing the CSV representation.
    """
    # Ensure separator is a string
    try:
        sep = str(separator)
    except Exception as exc:
        raise TypeError("separator must be convertible to string") from exc

    lines = []
    if header is not None:
        lines.append(str(header))

    # Retrieve points in a uniform way
    points = getattr(self, "points", None)
    if points is None:
        raise AttributeError("Graph object has no attribute 'points'")
    # Handle dict case
    if isinstance(points, dict):
        iter_points = points.items()
    else:
        try:
            iter_points = iter(points)
        except TypeError as exc:
            raise TypeError("Graph.points must be an iterable or a dict") from exc

    for item in iter_points:
        try:
            # dict items: (coords, value)
            if isinstance(item, tuple) and len(item) == 2 and isinstance(points, dict):
                coords, value = item
            # tuple/list of two elements: (coords, value)
            elif isinstance(item, (tuple, list)) and len(item) == 2:
                coords, value = item[0], item[1]
            # single element: treat as coordinate with empty value
            else:
                coords, value = item, None
        except Exception as exc:
            raise ValueError(f"Invalid point format: {item}") from exc

        # Convert coordinates
        if isinstance(coords, (list, tuple)):
            coord_str = sep.join(str(c) for c in coords)
        else:
            coord_str = str(coords)

        # Convert value
        if value is None:
            val_str = ""
        elif isinstance(value, (list, tuple)):
            val_str = sep.join(str(v) for v in value)
        else:
            val_str = str(value)

        # Combine parts
        if val_str:
            line = f"{coord_str}{sep}{val_str}"
        else:
            line = coord_str
        lines.append(line)

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        # Validate inputs
        if not isinstance(coord_name, str):
            raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

        # Ensure the error data structure exists
        if not hasattr(self, "_err") or self._err is None:
            raise AttributeError("The instance has no error data (_err attribute).")

        # Attempt to get the error array for the specified coordinate
        try:
            err_data = self._err[coord_name] if isinstance(self._err, dict) else getattr(self, f"_err_{coord_name}", None)
        except (KeyError, AttributeError):
            err_data = None

        if err_data is None:
            raise ValueError(f"No error data found for coordinate '{coord_name}'.")

        # If err_data is not a NumPy array, try to convert it
        try:
            import numpy as np
        except Exception as exc:
            raise ImportError("NumPy must be available for error index computation.") from exc

        try:
            err_array = np.asarray(err_data)
        except Exception:
            raise TypeError(f"Error data for coordinate '{coord_name}' cannot be converted to a NumPy array.")

        # Determine indices where the error is non‑zero (or non‑nan if boolean array is provided)
        if err_array.dtype == bool:
            idx = np.where(err_array)[0]
        else:
            # Treat zeros and NaNs as 'no error'
            idx = np.where((err_array != 0) & ~np.isnan(err_array))[0]

        # Ensure the indices are of integer type and sorted
        return np.sort(idx.astype(np.int64)) if idx.size else np.array([], dtype=np.int64)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    try:
        err_map = getattr(self, "_err_indices")
    except AttributeError as exc:
        raise AttributeError("Instance lacks '_err_indices' mapping") from exc
    if coord_name not in err_map:
        raise KeyError(f"No error indices found for coordinate '{coord_name}'")
    indices = err_map[coord_name]
    # Ensure the result is a sequence of indices
    if isinstance(indices, (list, tuple, set)):
        return list(indices)
    else:
        # Fallback: try to convert to a list
        try:
            return list(indices)
        except Exception as exc:
            raise TypeError(
                f"Error indices for coordinate '{coord_name}' are not iterable"
            ) from exc

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    try:
        bins_arr = np.asarray(bins, dtype=float)
        edges_arr = np.asarray(edges, dtype=float)
    except Exception as exc:
        raise ValueError(f"bins and edges must be array-like and numeric: {exc}") from exc

    if bins_arr.ndim != 1:
        raise ValueError(f"bins must be 1‑D array; got {bins_arr.ndim}‑D")
    if edges_arr.ndim != 1:
        raise ValueError(f"edges must be 1‑D array; got {edges_arr.ndim}‑D")

    if len(edges_arr) != len(bins_arr) + 1:
        raise ValueError(
            f"edges length ({len(edges_arr)}) must be bins length + 1 ({len(bins_arr)+1})"
        )

    # Ensure edges are monotonically increasing
    diffs = np.diff(edges_arr)
    if not np.all(diffs > 0):
        raise ValueError("edges must be monotonically increasing with positive widths")

    widths = diffs
    return float(np.sum(bins_arr * widths))

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Check if the object itself is a FillRequest
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest class is not defined, cannot check directly
        pass

    # Avoid treating a Source sequence as a valid FillRequest sequence
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source class is not defined, skip this check
        pass

    # Attempt to iterate over seq and look for any FillRequest elements
    try:
        for item in seq:
            try:
                if isinstance(item, FillRequest):
                    return True
            except NameError:
                # If FillRequest is undefined, break out
                break
    except TypeError:
        # seq is not iterable
        return False
    except Exception:
        # Catch all unexpected errors to avoid failing silently
        return False

    return False

