def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """

    def _deep_copy_dict(src):
        """Create a deep copy of a dictionary."""
        result = {}
        for k, v in src.items():
            if isinstance(v, dict):
                result[k] = _deep_copy_dict(v)
            else:
                result[k] = v
        return result

    def _diff(sub1, sub2, lvl):
        result = {}
        for key, val1 in sub1.items():
            if key not in sub2:
                # Key missing in d2: copy entire value
                if isinstance(val1, dict):
                    result[key] = _deep_copy_dict(val1)
                else:
                    result[key] = val1
            else:
                val2 = sub2[key]
                if val1 == val2:
                    continue  # identical, no difference
                # Values differ
                if isinstance(val1, dict) and isinstance(val2, dict):
                    if lvl == -1 or lvl > 1:
                        # Recursively compute difference
                        next_lvl = -1 if lvl == -1 else lvl - 1
                        sub_diff = _diff(val1, val2, next_lvl)
                        if sub_diff:
                            result[key] = sub_diff
                    else:  # lvl == 1 or 0
                        # Do not recurse; include whole value from d1
                        result[key] = _deep_copy_dict(val1)
                else:
                    # At least one value is not a dict: include val1
                    result[key] = val1
        return result

    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")
    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")

    def _diff(dict1, dict2, rem_depth):
        result = {}
        for key, val in dict1.items():
            if key not in dict2:
                # Key only in d1: copy as is (reference is fine)
                result[key] = val
                continue

            val2 = dict2[key]

            # If both are dicts we may need to recurse
            if isinstance(val, dict) and isinstance(val2, dict):
                # If we are allowed to recurse (depth not reached)
                if rem_depth != 0:
                    next_depth = rem_depth - 1 if rem_depth > 0 else rem_depth
                    sub = _diff(val, val2, next_depth)
                    if sub:  # only include if difference exists
                        result[key] = sub
                else:
                    # At depth limit: consider dicts unequal if any difference
                    if val != val2:
                        result[key] = val
                continue

            # For non-dict values (or mixed types)
            if val != val2:
                result[key] = val
        return result

    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    """

    # Basic type checks
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")

    def _diff(a, b, lvl):
        # lvl == 0 means no further recursion; return empty diff
        if lvl == 0:
            return {}

        result = {}
        for key, val in a.items():
            if key not in b:
                # key absent in d2, copy the value from d1
                result[key] = val
            else:
                other_val = b[key]
                # If both values are dicts and we still have recursion depth,
                # recurse; otherwise compare directly
                if isinstance(val, dict) and isinstance(other_val, dict):
                    # Determine next recursion depth
                    next_lvl = -1 if lvl == -1 else lvl - 1
                    sub_diff = _diff(val, other_val, next_lvl)
                    if sub_diff:
                        result[key] = sub_diff
                else:
                    # For non-dicts or when recursion depth is exhausted,
                    # include only if values differ
                    if val != other_val:
                        result[key] = val
        return result

    # Determine the starting recursion depth
    start_lvl = level if level != -1 else -1
    return _diff(d1, d2, start_lvl)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate inputs
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dictionary")
    if not isinstance(d2, dict):
        raise TypeError("d2 must be a dictionary")

    def _diff(sub1, sub2, depth):
        result = {}
        for key, val1 in sub1.items():
            if key not in sub2:
                # Include entire value (reference is acceptable)
                result[key] = val1
                continue

            val2 = sub2[key]

            # If both are dicts and we can recurse
            if isinstance(val1, dict) and isinstance(val2, dict):
                # Determine if recursion should happen
                if depth == 0:
                    # No recursion allowed: treat as differing values
                    result[key] = val1
                else:
                    # Recurse if depth > 0 or infinite
                    sub_depth = depth - 1 if depth > 0 else -1
                    sub_diff = _diff(val1, val2, sub_depth)
                    if sub_diff:  # Only include if non-empty
                        result[key] = sub_diff
            else:
                # Values not both dicts: compare equality
                if val1 != val2:
                    result[key] = val1
        return result

    # Adjust depth handling
    if level < 0:
        depth = -1  # Infinite recursion allowed
    else:
        depth = level  # Use as max depth

    try:
        return _diff(d1, d2, depth)
    except Exception as exc:
        # In case of any error, return empty dict
        return {}

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate inputs
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("difference expects two dictionaries as arguments")

    def _diff(d1_local, d2_local, lvl):
        """Recursive helper to compute the difference."""
        result = {}
        for key, val in d1_local.items():
            if key not in d2_local:
                # Key only in d1; copy it
                if isinstance(val, dict):
                    result[key] = val.copy()
                else:
                    result[key] = val
                continue

            val2 = d2_local[key]
            if val == val2:
                # Same value; nothing to add
                continue

            # Different values
            if isinstance(val, dict) and isinstance(val2, dict) and (lvl > 0 or lvl < 0):
                # Recurse into nested dictionaries if depth allows
                next_lvl = None if lvl < 0 else lvl - 1
                sub_diff = _diff(val, val2, next_lvl if next_lvl is not None else lvl)
                if sub_diff:
                    result[key] = sub_diff
                # If sub_diff is empty, we skip the key
                continue

            # Non-dict values or depth limit reached: include value from d1
            if isinstance(val, dict):
                result[key] = val.copy()
            else:
                result[key] = val
        return result

    # Start recursion with the requested depth
    return _diff(d1, d2, level) if level >= 0 else _diff(d1, d2, -1)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Import numpy lazily to avoid required dependency at class import time
    try:
        import numpy as np
    except Exception as exc:
        raise RuntimeError("numpy is required for histogram operations") from exc

    # Validate and coerce coord to a 1‑D numeric array
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise ValueError(f"coord must be convertible to a numeric array, got {coord!r}") from exc

    if coord_arr.ndim != 1:
        raise ValueError(f"coord must be one‑dimensional, got array with shape {coord_arr.shape}")

    # Ensure the histogram has the necessary storage attributes
    if not hasattr(self, "edges") or not hasattr(self, "bins"):
        raise AttributeError("Histogram object must have 'edges' and 'bins' attributes")

    edges = self.edges
    if len(coord_arr) != len(edges):
        raise ValueError(f"coord dimension {len(coord_arr)} does not match histogram dimensionality {len(edges)}")

    # Validate weight (force scalar numeric)
    try:
        weight_val = float(weight)
    except Exception as exc:
        raise ValueError(f"weight must be a scalar numeric value, got {weight!r}") from exc

    # Find bin indices for each coordinate dimension
    bin_indices = []
    for dim, edge in enumerate(edges):
        # The interval for each bin is [edge[i], edge[i+1])
        # Use np.searchsorted with side='right' and subtract one to get the index
        idx = np.searchsorted(edge, coord_arr[dim], side="right") - 1
        # Out‑of‑range handling: ignore if outside histogram boundaries
        if idx < 0 or idx >= len(edge) - 1:
            return  # ignore outside boundaries
        bin_indices.append(idx)

    # Use tuple indexing for potentially multidimensional bins array
    try:
        self.bins[tuple(bin_indices)] += weight_val
    except Exception as exc:
        raise RuntimeError("Failed to update histogram bins; ensure 'bins' is a mutable array") from exc

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Basic validation of inputs
    try:
        weight = float(weight)
    except Exception as exc:
        raise TypeError("weight must be a numeric value") from exc

    # Ensure histogram structure exists
    if not hasattr(self, "bin_edges") or not hasattr(self, "data"):
        raise AttributeError("Histogram object must have 'bin_edges' and 'data' attributes")

    edges = self.bin_edges
    # Support both list/tuple of arrays or a single 2D array for bin edges
    if isinstance(edges, (list, tuple)):
        axis_edges = edges
    else:
        try:
            axis_edges = list(edges)
        except Exception:
            raise TypeError("bin_edges should be a sequence of arrays or a 2D array")

    if len(axis_edges) == 0:
        raise ValueError("Histogram has no axes defined")

    # Coordinate must be iterable and match number of axes
    if not hasattr(coord, "__iter__"):
        raise TypeError("coord must be an iterable of coordinates")
    coord_lst = list(coord)
    if len(coord_lst) != len(axis_edges):
        raise ValueError("Incorrect number of coordinate components")

    # Find bin indices for each coordinate
    bin_indices = []
    for i, (c, edge_arr) in enumerate(zip(coord_lst, axis_edges)):
        # Ensure coordinate is numeric
        try:
            val = float(c)
        except Exception:
            raise TypeError(f"Coordinate component {i} must be numeric") from None

        # Use searchsorted to find the bin
        try:
            idx = np.searchsorted(edge_arr, val, side='right') - 1
        except Exception:
            raise ValueError(f"Edge array for axis {i} must be sortable")

        # Check bounds
        if idx < 0 or idx >= len(edge_arr) - 1:
            # Outside histogram limits: ignore
            return
        bin_indices.append(idx)

    # Convert indices list to a tuple for numpy indexing
    idx_tuple = tuple(bin_indices)

    # Update histogram value
    # Use np.add.at to handle potential overlapping indices safely
    try:
        np.add.at(self.data, idx_tuple, weight)
    except Exception as exc:
        raise RuntimeError("Failed to update histogram bin") from exc

    return

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Basic checks and conversion
    try:
        values = list(coord)
    except Exception:
        raise TypeError("coord must be an iterable of numerical values")

    try:
        w = float(weight)
    except Exception:
        raise TypeError("weight must be a number")

    edges_attr = getattr(self, "edges", None)
    hist_attr = getattr(self, "hist", None)
    if edges_attr is None or hist_attr is None:
        raise AttributeError("Histogram object must have 'edges' and 'hist' attributes")

    num_dims = len(edges_attr)
    if len(values) != num_dims:
        raise ValueError(f"Expected {num_dims} coordinate values, got {len(values)}")

    # Find bin indices for each dimension
    bin_indices = []
    for dim, val in enumerate(values):
        edges = edges_attr[dim]
        # Simple binary search to find right bin
        lo, hi = 0, len(edges) - 1
        while lo < hi - 1:  # hi is exclusive upper edge
            mid = (lo + hi) // 2
            if val < edges[mid]:
                hi = mid
            else:
                lo = mid
        bin_idx = lo
        # Check bounds: bins are defined by [edges[i], edges[i+1])
        if bin_idx < 0 or bin_idx >= len(edges) - 1:
            # Coordinate out of range – ignore
            return
        bin_indices.append(bin_idx)

    # Increment histogram count
    try:
        hist_attr[tuple(bin_indices)] += w
    except Exception as exc:
        raise RuntimeError(f"Failed to update histogram counts: {exc}")

def fill(self, coord, weight=1):
        """
        Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Attempt to perform the fill; ignore any errors caused by bad input.
        try:
            # Retrieve histogram configuration.  We expect `self.edges` to be a
            # 1‑D iterable of bin edges and `self.counts` to be an array/list
            # holding the counts for each bin.  If either attribute is missing,
            # we raise an informative error.
            edges = getattr(self, "edges", None)
            counts = getattr(self, "counts", None)
            if edges is None or counts is None:
                raise AttributeError(
                    "Histogram object must have 'edges' and 'counts' attributes."
                )
            if not isinstance(edges, (list, tuple)):
                raise TypeError("'edges' must be a list or tuple of bin edges.")
            if len(edges) < 2:
                # An empty histogram has no bins to fill
                return

            # Helper function to handle a single coordinate value
            def _fill_single(c):
                # Ensure the weight is numeric; otherwise ignore this entry
                try:
                    w = float(weight)
                except Exception:
                    return
                # Skip non‑numeric coordinates
                try:
                    numeric_c = float(c)
                except Exception:
                    return

                # Find the appropriate bin index.
                # Histograms are defined as [edges[i], edges[i+1]) for all bins
                # except the last one, which is [edges[-2], edges[-1]] inclusive.
                idx = None
                # Quick binary search using bisect if available
                lo, hi = 0, len(edges) - 1
                while lo < hi:
                    mid = (lo + hi) // 2
                    if numeric_c < edges[mid]:
                        hi = mid
                    else:
                        lo = mid + 1
                idx = lo - 1
                if idx < 0 or idx >= len(counts):
                    # Coordinate lies outside histogram range
                    return
                # For coordinates exactly equal to the upper edge, place them
                # in the last bin
                if numeric_c == edges[-1]:
                    idx = len(counts) - 1
                # Update the bin count
                try:
                    counts[idx] += w
                except Exception:
                    # In case counts is immutable or non‑numeric
                    return

            # If coord is iterable (but not a string), treat each element as
            # a separate coordinate; otherwise handle it as a single value.
            try:
                iterator = iter(coord)
                if isinstance(coord, (str, bytes)):
                    iterator = None
            except TypeError:
                iterator = None

            if iterator is not None:
                for c in iterator:
                    _fill_single(c)
            else:
                _fill_single(coord)

        except Exception:
            # Any unexpected exception (e.g., incompatible types) is swallowed
            pass

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    import re

    # Define allowed patterns for keys and values.
    # These are common Kubernetes/OpenTelemetry/Prometheus label naming conventions.
    key_pattern = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_\-]{0,63}$')
    value_pattern = re.compile(r'^[a-zA-Z0-9_\-]{0,63}$')

    errors = []

    for key, value in labels.items():
        # ---- Validate key ----
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            try:
                key_str = key.decode() if isinstance(key, bytes) else key
            except Exception:
                errors.append({str(key): 'expected string or bytes-like object'})
                key_str = str(key)
            if not key_pattern.match(key_str):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex '{key_pattern.pattern}'"})

        # ---- Validate value ----
        # Handle list/tuple values (e.g. array of strings)
        if isinstance(value, (list, tuple)):
            for item in value:
                if not isinstance(item, (str, bytes)):
                    errors.append({str(item): 'expected string or bytes-like object'})
                else:
                    try:
                        item_str = item.decode() if isinstance(item, bytes) else item
                    except Exception:
                        errors.append({str(item): 'expected string or bytes-like object'})
                        item_str = str(item)
                    if not value_pattern.match(item_str):
                        errors.append({item_str: f"Label value '{item_str}' does not match the regex '{value_pattern.pattern}'"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                try:
                    value_str = value.decode() if isinstance(value, bytes) else value
                except Exception:
                    errors.append({str(value): 'expected string or bytes-like object'})
                    value_str = str(value)
                if not value_pattern.match(value_str):
                    errors.append({value_str: f"Label value '{value_str}' does not match the regex '{value_pattern.pattern}'"})

    if errors:
        # Assuming ValidationError is defined elsewhere in the caller's context.
        raise ValidationError(messages=errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
