            - value: the error message.
    """
    import re

    # Ensure we have a dictionary
    if not isinstance(labels, dict):
        raise ValidationError([{"labels": "Expected a dictionary for labels"}])

    # Base regex for keys and values (example pattern, adjust as needed)
    pattern = r"^[A-Za-z0-9._-]+$"
    key_re = re.compile(pattern)
    value_re = re.compile(pattern)

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({repr(key): "expected string or bytes-like object"})
            # Skip further key checks for this key
            continue

        # Validate key regex
        try:
            key_str = key.decode() if isinstance(key, bytes) else key
        except Exception:
            key_str = str(key)
        if not key_re.match(key_str):
