                {
                    key_str: f"Label key '{key_str}' does not match the regex '{pattern}'"
                }
            )

        # Helper to process a single value or an iterable of values
        def _check_value(val):
            if not isinstance(val, (str, bytes)):
                errors.append({repr(val): "expected string or bytes-like object"})
                return
            try:
                val_str = val.decode() if isinstance(val, bytes) else val
            except Exception:
                val_str = str(val)
            if not value_re.match(val_str):
                errors.append(
                    {val_str: f"Label value '{val_str}' does not match the regex '{pattern}'"}
                )

        # Validate value(s)
        if isinstance(value, (list, tuple, set)):
