            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    # Regular expressions for keys and values should be defined elsewhere
    # in the module. We simply assume they exist.
    # For safety, we fallback to a permissive regex if they are missing.
    key_regex = getattr(_validate_labels, "LABEL_KEY_REGEX", None)
    value_regex = getattr(_validate_labels, "LABEL_VALUE_REGEX", None)
    if key_regex is None:
        import re
        key_regex = re.compile(r".*")  # accepts anything by default
    if value_regex is None:
        import re
        value_regex = re.compile(r".*")  # accepts anything by default

    for key, value in labels.items():
        # Validate key
