def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a partial observer_schema dictionary from a Kubernetes resource dictionary.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer_schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema, with non-list and non-dict values replaced by None.
    """
    if not isinstance(manifest_dict, dict):
        # If the provided value is not a dict, there's nothing to process.
        return None

    def _process_list(lst):
        """Helper that processes a list similarly to the main function."""
        if not isinstance(lst, list):
            return None
        processed = []
        for item in lst:
            if isinstance(item, dict):
                processed.append(generate_default_observer_schema_dict(item, first_level=False))
            elif isinstance(item, list):
                processed.append(_process_list(item))
            else:
                processed.append(None)
        return processed

    result = {}
    for key, value in manifest_dict.items():
        # Preserve top-level identifying fields if requested.
        if first_level and key in {"apiVersion", "kind", "metadata"}:
            result[key] = value
            continue

        if isinstance(value, dict):
            # Recurse into nested dictionaries.
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Process lists specially.
            result[key] = _process_list(value)
        else:
            # Replace primitive values with None.
            result[key] = None

    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Recursively build a default observer schema part from a Kubernetes manifest dict.

    Replaces all non-dict and non-list values with ``None``. At the top level
    (``first_level=True``) the values of identifying fields are preserved
    from the ``manifest_dict``:

    * ``apiVersion`` and ``kind`` (direct string fields)
    * ``metadata`` sub-fields ``name``, ``namespace`` and ``generateName``

    Lists are processed by the complementary :func:`generate_default_observer_schema_list`
    function which must be defined elsewhere.

    Parameters
    ----------
    manifest_dict : dict
        Partial Kubernetes resource dictionary to be processed.
    first_level : bool, optional
        If ``True`` the dictionary represents the whole observer schema for a
        Kubernetes resource; only identifying field values are preserved.
        Default ``False``.

    Returns
    -------
    dict
        New dictionary representing the default observer schema fragment.

    Raises
    ------
    TypeError
        If ``manifest_dict`` is not a dictionary.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError(f"manifest_dict must be a dict, got {type(manifest_dict).__name__}")

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Assumes a helper function exists to process lists
            try:
                result[key] = generate_default_observer_schema_list(value)
            except NameError:
                # Fallback: produce list of None placeholders
                result[key] = [None if not isinstance(v, (dict, list)) else
                               (generate_default_observer_schema_dict(v) if isinstance(v, dict)
                                else generate_default_observer_schema_list(v))
                               for v in value]
        else:
            # Primitive value
            if first_level and key in ('apiVersion', 'kind'):
                result[key] = value
            elif first_level and key == 'metadata' and isinstance(value, dict):
                # Preserve only identifying subfields from metadata
                meta_copy = {}
                for subfield in ('name', 'namespace', 'generateName'):
                    if subfield in value:
                        meta_copy[subfield] = value[subfield]
                result[key] = meta_copy if meta_copy else None
            else:
                result[key] = None
    return result

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_list_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``; each key maps to
            a mapping describing the field.  The mapping may contain:
            * ``type``: ``dict``, ``list``, or omitted for a scalar value.
            * ``schema``: nested observer schema for sub‑objects.
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If an observed field is not present in ``response``.
    """
    # Guard against ``response`` not being a mapping
    if not isinstance(response, dict):
        raise KeyError("Response must be a mapping")

    for field, field_schema in observer_schema.items():
        # Validate that the field exists in the response
        if field not in response:
            raise KeyError(
                f"Observed field '{field}' missing from Kubernetes response"
            )

        # Grab the schema details; allow schema to be ``None`` or a dict
        schema_type = None
        schema_nested = None
        if isinstance(field_schema, dict):
            schema_type = field_schema.get("type")
            schema_nested = field_schema.get("schema")

        # If the field is missing in the applied manifest, initialise it
        if field not in last_applied_manifest:
            if schema_type == "dict" and isinstance(
                response[field], dict
            ):
                # Initialise nested dict and recurse
                last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema_nested or {}, response[field]
                )
            elif schema_type == "list" and isinstance(
                response[field], list
            ):
                # Initialise list; elements may be scalars or dicts
                last_applied_manifest[field] = []
                child_schema = schema_nested
                for item in response[field]:
                    if isinstance(item, dict) and child_schema:
                        new_item = {}
                        update_last_applied_manifest_dict_from_resp(
                            new_item, child_schema, item
                        )
                        last_applied_manifest[field].append(new_item)
                    else:
                        last_applied_manifest[field].append(item)
            else:
                # Scalar or unsupported nested structure: copy value
                last_applied_manifest[field] = response[field]
        else:
            # Field already present: we may need to merge nested sub‑fields
            existing_value = last_applied_manifest[field]
            resp_value = response[field]
            if isinstance(existing_value, dict) and isinstance(resp_value, dict):
                # Recursively merge missing nested dict fields
                update_last_applied_manifest_dict_from_resp(
                    existing_value, schema_nested or {}, resp_value
                )
            elif (
                isinstance(existing_value, list)
                and isinstance(resp_value, list)
                and schema_type == "list"
                and schema_nested
            ):
                # Merge list of dicts: iterate over common indices
                child_schema = schema_nested
                for i, (elem_last, elem_resp) in enumerate(
                    zip(existing_value, resp_value)
                ):
                    if isinstance(elem_resp, dict):
                        update_last_applied_manifest_dict_from_resp(
                            elem_last, child_schema, elem_resp
                        )

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate the application object and manifest
    if not hasattr(app, "spec"):
        raise ValueError("Application object has no 'spec' attribute")
    if not hasattr(app.spec, "manifest"):
        raise ValueError("Application spec has no 'manifest' attribute")

    manifest = app.spec.manifest
    if not isinstance(manifest, dict):
        raise TypeError("Application spec.manifest must be a dict")

    # Existing observer schemas, if any
    observer_schema = getattr(app.spec, "observer_schema", {})
    if observer_schema is None:
        observer_schema = {}
    if not isinstance(observer_schema, dict):
        raise TypeError("Application spec.observer_schema must be a dict")

    # Define a minimal default schema. Adjust this definition to match the real schema definition if known.
    default_schema = {"observed": True}

    # Generate defaults for each resource without a custom schema
    for resource_name in manifest.keys():
        if resource_name not in observer_schema:
            observer_schema[resource_name] = default_schema

    # Assign the updated schema back to the application spec
    app.spec.observer_schema = observer_schema

    return observer_schema

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app: The application for which to generate a default observer schema.
             Expected to have a ``spec`` attribute with a ``manifest`` list of
             Kubernetes resources. Each resource should be a mapping with at
             least ``kind`` and ``metadata`` keys.

    Returns:
        A dictionary mapping a unique resource identifier (``{kind}:{namespace}:{name}``)
        to a default observer schema dictionary. If no resources are present or the
        input is invalid, an empty dictionary is returned.
    """
    # Helper to safely build identifier
    def _resource_key(kind, namespace, name):
        return f"{kind}:{namespace or 'default'}:{name}"

    # Validate input
    if not app:
        return {}
    spec = getattr(app, "spec", None)
    if not spec:
        return {}
    manifest = getattr(spec, "manifest", [])
    if not isinstance(manifest, list):
        return {}

    default_schemas = {}

    for resource in manifest:
        try:
            kind = resource.get("kind")
            if not kind:
                # Skip resources lacking a kind
                continue
            metadata = resource.get("metadata", {})
            name = metadata.get("name")
            if not name:
                # Skip resources lacking a name
                continue
            namespace = metadata.get("namespace")
            key = _resource_key(kind, namespace, name)

            # If user has provided a custom observer schema, skip generating default
            # Assume custom schemas are stored in ``spec.observers`` mapping keys to schemas
            observers = getattr(spec, "observers", {})
            if key in observers and observers[key]:
                continue

            # Build a minimal default observer schema
            default_schema = {
                "apiVersion": f"{getattr(app, 'k8s_group', 'example.com')}/v1",
                "kind": f"{kind}Observer",
                "metadata": {"name": name, "namespace": namespace},
                "spec": {
                    "resource": {
                        "kind": kind,
                        "namespace": namespace,
                        "name": name,
                    },
                    "template": {},
                },
                "status": {"observed": False, "message": "Default observer"},
            }

            default_schemas[key] = default_schema
        except Exception:
            # Skip this resource if any unexpected error occurs while adding
            continue

    return default_schemas

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    Parameters
    ----------
    sql
        The SQL query (string or bytes).

    params
        The set of in-style parameters. Either a mapping (for named
        parameters) or a sequence (for ordinal parameters).

    Returns
    -------
    tuple
        A tuple of ``(formatted_sql, converted_params)`` where
        ``formatted_sql`` is the query with out‑style placeholders and
        ``converted_params`` is the parameters in the form required by
        the out‑style (either a list/tuple or a mapping).

    Raises
    ------
    TypeError
        If ``sql`` is not a string or bytes, or ``params`` is not the
        expected type for the current ``in_style``.
    KeyError
        If a named placeholder in ``sql`` does not have a matching key
        in ``params``.
    """
    # Validate the SQL type --------------------------------------------------
    if not isinstance(sql, (str, bytes)):
        raise TypeError(f"sql must be str or bytes, got {type(sql).__name__}")

    # Determine input and output styles --------------------------------------
    # Default to "named" -> "positional" if attributes not present
    in_style = getattr(self, "in_style", "named")
    out_style = getattr(self, "out_style", "?")  # Default out_style uses '?'

    # Ensure params type matches in_style --------------------------------------
    if in_style in ("named", "qmark", "named") and isinstance(params, Mapping):
        # Named in_style requires a mapping
        pass
    elif in_style in ("numeric", "qmark") and isinstance(params, Sequence) and not isinstance(params, Mapping):
        # Numeric in_style requires a sequence
        pass
    else:
        raise TypeError(
            f"params type {type(params).__name__} does not match expected type "
            f"for in_style '{in_style}'"
        )

    # Conversion function -----------------------------------------------------
    converted_params: List[Any] = []

    # If SQL is bytes, patterns must be bytes
    if isinstance(sql, bytes):
        pattern = (
            rb":(\w+)"          # Named placeholder for :name
            if in_style in ("named",)
            else rb"%(\d+|s)"    # Numbered placeholder for %1, %(1)s, etc.
        )
        # Define replacement function
        def repl(match):
            if in_style in ("named",):
                name = match.group(1).decode()
                if name not in params:
                    raise KeyError(f"Parameter '{name}' not found in params")
                converted_params.append(params[name])
                return out_style.encode() if isinstance(out_style, bytes) else out_style
            else:
                # Numeric style: value order preserved
                idx = int(match.group(1)) if match.group(1).isdigit() else None
                if idx is not None:
                    try:
                        value = params[idx]
                    except IndexError:
                        raise KeyError(f"Parameter index {idx} out of range")
                else:
                    # If pattern uses '%s', use next value
                    try:
                        value = converted_params.pop(0)
                    except IndexError:
                        value = None
                converted_params.append(value)
                return out_style.encode() if isinstance(out_style, bytes) else out_style

    else:
        # sql is str
        pattern = (
            r":(\w+)"          # Named placeholder for :name
            if in_style in ("named",)
            else r"%(\d+|s)"    # Numbered placeholder for %1, %(1)s, etc.
        )

        def repl(match):
            if in_style in ("named",):
                name = match.group(1)
                if name not in params:
                    raise KeyError(f"Parameter '{name}' not found in params")
                converted_params.append(params[name])
                return out_style
            else:
                idx = int(match.group(1)) if match.group(1).isdigit() else None
                if idx is not None:
                    try:
                        value = params[idx]
                    except IndexError as exc:
                        raise KeyError(f"Parameter index {idx} out of range") from exc
                else:
                    try:
                        value = converted_params.pop(0)
                    except IndexError:
                        value = None
                converted_params.append(value)
                return out_style

    # Perform the replacement -----------------------------------------------
    try:
        formatted_sql = re.sub(pattern, repl, sql)
    except re.error as exc:
        raise ValueError(f"Regex error while formatting SQL: {exc}") from exc

    # Prepare converted_params output
    if isinstance(params, Mapping):
        # For out_style positional, return as list
        result_params: Sequence[Any] = converted_params if out_style != ":{}" else params
    else:
        # For sequence input, preserve original type
        if isinstance(params, tuple):
            result_params = tuple(converted_params)
        else:
            result_params = converted_params

    return formatted_sql, result_params

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    # Ensure we have the necessary style information
    try:
        in_style = self.SQLParams.in_style
        out_style = self.SQLParams.out_style
    except AttributeError:
        raise AttributeError(
            "Instance must have .SQLParams with in_style and out_style attributes."
        )

    # Determine if we are dealing with named or ordinal placeholders
    if isinstance(in_style, str) and in_style.startswith("%("):
        named = True
        placeholder_re = re.compile(r"%\(([^)]+)\)[a-z]+")
    else:
        named = False
        placeholder_re = re.compile(r"%[a-z]+")

    # Decode sql if it is bytes for regex operations
    input_is_bytes = isinstance(sql, bytes)
    sql_str = sql.decode() if input_is_bytes else sql

    try:
        placeholders = placeholder_re.findall(sql_str)
        # Construct the new SQL by replacing all in-style placeholders with out_style
        new_sql_str = placeholder_re.sub(out_style, sql_str)
    except Exception as exc:
        raise ValueError(f"Failed to transform SQL: {exc}") from exc

    # Encode back to bytes if needed
    new_sql: AnyStr = new_sql_str.encode() if input_is_bytes else new_sql_str

    out_params_list: List[Sequence[Any]] = []

    # Iterate over the provided parameter sets
    try:
        for params in many_params:
            if named:
                if not isinstance(params, dict):
                    raise TypeError(
                        "Named parameters require a mapping (e.g., dict) for each set."
                    )
                try:
                    out_params = [params[name] for name in placeholders]
                except KeyError as err:
                    raise ValueError(
                        f"Missing named parameter '{err.args[0]}' in params."
                    ) from err
                if len(out_params) != len(placeholders):
                    raise ValueError(
                        "Parameter count does not match number of placeholders."
                    )
                out_params_list.append(out_params)

            else:
                if isinstance(params, dict):
                    raise TypeError(
                        "Ordinal parameters cannot be provided as a mapping."
                    )
                # Accept any iterable that is not a string/bytes (including generators)
                try:
                    out_params = list(params)
                except TypeError as exc:
                    raise TypeError("Parameters must be an iterable sequence.") from exc
                if len(out_params) != len(placeholders):
                    raise ValueError(
                        "Number of parameters does not match the number of placeholders."
                    )
                out_params_list.append(out_params)
    except TypeError as exc:
        raise TypeError(f"many_params must be an iterable of parameter sets: {exc}") from exc

    return new_sql, out_params_list

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        p = Path(path)
    except Exception:
        # Invalid path input
        return False

    # Path must exist
    if not p.exists():
        return False

    # We only support directories as potential roots
    if p.is_file():
        return False

    # Determine candidate root: current path or its parent
    candidates = [p, p.parent]
    root = None
    for cand in candidates:
        if (cand / "manifest.v1.json").is_file() and (cand / "objects").is_dir():
            root = cand
            break

    if not root:
        return False

    try:
        # Basic root checks
        if not (root / "manifest.v1.json").is_file():
            return False
        objects_dir = root / "objects"
        if not objects_dir.is_dir():
            return False

        # Iterate over object directories
        for obj in objects_dir.iterdir():
            if not obj.is_dir():
                continue  # Skip non-directories, not an error

            # Each object must have a manifest
            if not (obj / "manifest.v1.json").is_file():
                return False

            versions_dir = obj / "versions"
            if not versions_dir.is_dir():
                return False

            # Ensure at least one version exists
            if not any(v.is_dir() for v in versions_dir.iterdir()):
                return False

            # Check minimal structure within each version
            for ver in versions_dir.iterdir():
                if not ver.is_dir():
                    continue  # Skip: not an error

                # Optional: check for a manifest file per version
                # (not mandatory for this simple validation)
                if not (ver / "manifest").is_file():
                    pass  # warning: not required for validation

                # Optional: blobs and ui directories may exist
                # They are not required for basic validity
                # but if present, ensure they are directories
                if (ver / "blobs").exists() and not (ver / "blobs").is_dir():
                    return False
                if (ver / "ui").exists() and not (ver / "ui").is_dir():
                    return False

        # All checks passed
        return True

    except Exception:
        # Any unexpected error results in invalid
        return False

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Ensure path object supports basic filesystem operations
        if not hasattr(path, "exists"):
            return False

        # Root must exist
        if not path.exists():
            return False

        # Helper to construct subpaths
        def subpath(name):
            try:
                return getattr(path, "joinpath", lambda n: path / n)(name)
            except Exception:
                return None

        # Check for .ocfl_version file
        version_path = subpath(".ocfl_version")
        if not version_path or not version_path.is_file():
            return False
        try:
            version_content = version_path.read_text().strip()
            if not version_content:
                return False
        except Exception:
            return False

        # Check for .ocfl_root directory
        root_path = subpath(".ocfl_root")
        if not root_path or not root_path.is_dir():
            return False

        # Basic consistency: root must contain at least one object
        try:
            # Look for at least one object directory in .ocfl_root/objects
            objects = root_path.joinpath("objects") if hasattr(root_path, "joinpath") else None
            if objects and objects.is_dir():
                # Ensure there's at least one subdirectory
                found = False
                for entry in objects.iterdir():
                    if entry.is_dir():
                        found = True
                        break
                if not found:
                    return False
            else:
                # If no objects directory, consider invalid
                return False
        except Exception:
            return False

        # If all checks pass, consider the OCFL object valid
        return True
    except Exception:
        return False

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        import os
        from pathlib import Path

        # Resolve the target: either a filesystem path or a pyfs root instance
        if isinstance(path, str):
            # Treat it as a filesystem path
            abs_path = os.path.realpath(path)
            if not os.path.isdir(abs_path):
                return False
            target = abs_path
        else:
            # Assume it is a pyfs root object
            target = path

        # If the object has a dedicated internal validation method, use it
        if hasattr(self, "_validate_object"):
            return self._validate_object(target)

        # Fallback: try generic loading and validation
        if hasattr(self, "load"):
            obj = self.load(target)
            if hasattr(obj, "validate"):
                return obj.validate()
        # If none of the expected methods exist, consider it invalid
        return False

    except Exception:
        # Any exception during validation is treated as a failure
        return False

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        try:
            import os
            # Resolve pyfs root object or string path
            if hasattr(path, "path"):
                path = path.path
            if isinstance(path, str):
                path = os.path.expanduser(path)
                path = os.path.abspath(path)
            else:
                # Unsupported path type
                return False
            # Must be a directory
            if not os.path.isdir(path):
                return False
            # OCFL root must contain a .ocfl directory
            ocfl_dir = os.path.join(path, ".ocfl")
            if not os.path.isdir(ocfl_dir):
                return False
            # Check for at least one manifest file in .ocfl
            manifest_found = False
            for f in os.listdir(ocfl_dir):
                if f.lower().endswith(".json"):
                    manifest_found = True
                    break
            if not manifest_found:
                return False
            # .ocfl must contain an "objects" directory
            objects_dir = os.path.join(ocfl_dir, "objects")
            if not os.path.isdir(objects_dir):
                return False
            # Basic check: at least one object folder exists
            obj_folders = [
                d for d in os.listdir(objects_dir)
                if os.path.isdir(os.path.join(objects_dir, d))
            ]
            if not obj_folders:
                return False
            # Additional simple validation: each object folder should contain
            # a metadata.json file and a content directory (placeholders)
            for obj in obj_folders:
                obj_path = os.path.join(objects_dir, obj)
                meta_file = os.path.join(obj_path, "metadata.json")
                content_dir = os.path.join(obj_path, "content")
                if not os.path.isfile(meta_file) or not os.path.isdir(content_dir):
                    # Allow warnings: return False if missing critical parts
                    return False
            # All basic checks passed
            return True
        except Exception:
            # Any exception during validation treated as invalid
            return False

