def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Attempt to locate the log attribute
    log = None
    for name in ('validation_log', 'log', 'status_log', 'history'):
        if hasattr(self, name):
            log = getattr(self, name)
            break

    # If no log is found, return an empty string
    if log is None:
        return ''

    # Convert the log to a list of string lines
    try:
        if isinstance(log, str):
            lines = log.splitlines()
        elif isinstance(log, (list, tuple)):
            lines = [str(item) for item in log]
        else:
            # Try to iterate over the log if it's an iterable container
            try:
                it = iter(log)
                # Avoid treating a string as an iterable of chars
                if isinstance(log, str):
                    lines = log.splitlines()
                else:
                    lines = [str(item) for item in it]
            except TypeError:
                # Fallback to a single string representation
                lines = [str(log)]
    except Exception:
        lines = [str(log)]

    # Apply optional prefix to each line
    if prefix:
        prefixed_lines = [f"{prefix}{line}" for line in lines]
    else:
        prefixed_lines = lines

    return "\n".join(prefixed_lines)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")

    try:
        # Attempt to retrieve a validation log from common attribute names
        lines = getattr(self, 'validation_log', None)
        if lines is None:
            lines = getattr(self, 'log', None)
        if lines is None:
            lines = []

        # Normalize to a list of lines
        if isinstance(lines, str):
            lines = [lines]
        else:
            try:
                lines = list(lines)
            except TypeError:
                lines = [str(lines)]

        # Build the output string with the optional prefix
        formatted_lines = []
        for line in lines:
            if line is None:
                continue
            formatted_lines.append(prefix + str(line))

        return "\n".join(formatted_lines)
    except Exception as e:
        # Fallback in case of unexpected runtime issues
        return f"{prefix}Error retrieving status: {e}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Attempt to find a log-related attribute
        log_attr_names = ['log', 'logs', 'messages', 'status']
        log_obj = None
        for name in log_attr_names:
            if hasattr(self, name):
                log_obj = getattr(self, name)
                break

        if log_obj is None:
            return prefix + 'No validation log.'

        # If the log is already a string, just prefix and return it
        if isinstance(log_obj, str):
            return prefix + log_obj

        # If the log is a list or tuple, join its items
        if isinstance(log_obj, (list, tuple)):
            if not log_obj:
                return prefix + 'No validation log.'
            return prefix + '\n'.join(str(item) for item in log_obj)

        # If the log is a dictionary, format key/value pairs
        if isinstance(log_obj, dict):
            if not log_obj:
                return prefix + 'No validation log.'
            return prefix + '\n'.join(f'{k}: {v}' for k, v in log_obj.items())

        # Fallback: use the string representation of the log object
        return prefix + str(log_obj)

    except Exception:
        # Graceful fallback if something unexpected happens
        try:
            return prefix + str(self)
        except Exception:
            return prefix + '<unrepresentable object>'

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check for the inventory parameter
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")

    # Define a set of keys that are expected to be present – adjust as needed
    required_keys = {"name", "description"}
    missing = required_keys - inventory.keys()
    if missing:
        raise ValueError(f"Inventory is missing required keys: {sorted(missing)}")

    # Handle extraction of specification version from the 'type' key
    if extract_spec_version:
        type_val = inventory.get("type")
        # We consider non-empty strings identifying a spec to be valid
        if isinstance(type_val, str) and type_val.strip():
            # Store the spec version on the instance; you might want
            # to validate that this is one of the known versions.
            self.spec_version = type_val.strip()
        else:
            # No valid 'type' value found; fall back to existing spec_version
            if not hasattr(self, "spec_version"):
                raise ValueError(
                    "No 'type' value found in inventory and self.spec_version is unset"
                )
    else:
        # If not extracting spec version, ensure we still have a spec_version set
        if not hasattr(self, "spec_version"):
            raise ValueError("spec_version must be set before validation")

    # Everything passed – return True to indicate success
    return True

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    try:
        # Inventory must be a dict-like mapping
        if not isinstance(inventory, dict):
            raise ValueError("Expected inventory to be a dictionary")

        # Determine spec version
        spec_version = None
        if extract_spec_version:
            spec_type = inventory.get("type")
            if isinstance(spec_type, str) and spec_type:
                spec_version = spec_type
        if spec_version is None:
            spec_version = getattr(self, "spec_version", None)

        if spec_version is None:
            raise ValueError("Specification version could not be determined")

        # Allowable spec versions can be extended as needed
        allowed_versions = {"1.0", "1.1", "2.0"}
        if spec_version not in allowed_versions:
            raise ValueError(f"Unsupported specification version: {spec_version!r}")

        # Basic required keys for the inventory
        required_keys = ["name", "components", "plugins"]
        for key in required_keys:
            if key not in inventory:
                raise ValueError(f"Missing required key: {key!r}")

        # Validate components
        components = inventory["components"]
        if not isinstance(components, list):
            raise ValueError("Components must be a list")
        for comp in components:
            if not isinstance(comp, dict):
                raise ValueError("Each component must be a dictionary")
            if "id" not in comp:
                raise ValueError("Each component must contain an 'id' key")

        # Validate plugins
        plugins = inventory["plugins"]
        if not isinstance(plugins, list):
            raise ValueError("Plugins must be a list")
        for plugin in plugins:
            if not isinstance(plugin, dict):
                raise ValueError("Each plugin must be a dictionary")
            if "name" not in plugin:
                raise ValueError("Each plugin must contain a 'name' key")
            if "enabled" in plugin and not isinstance(plugin["enabled"], bool):
                raise ValueError("Plugin 'enabled' value must be a boolean")

        # If we reach this point, validation passed
        return True

    except Exception as exc:
        # Re‑raise any exception as a ValueError for the caller
        raise ValueError(f"Inventory validation failed: {exc}") from exc

def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check that every digest listed in ``manifest_files`` is also used, and that
    every digest reported as used exists in the manifest. ``manifest_files`` is
    expected to be a mapping from digest name (string) to an iterable of file
    paths. ``digests_used`` may be a set, list, or mapping of the same digest
    names. The method raises :class:`TypeError` for invalid input types and
    :class:`ValueError` if any digest is missing or unused. It returns ``True``
    if all checks pass.
    """
    # Validate manifest_files
    if not isinstance(manifest_files, dict):
        raise TypeError(
            f"manifest_files should be a dict, got {type(manifest_files)!r}"
        )
    # Validate digests_used
    if isinstance(digests_used, dict):
        used_digest_names = set(digests_used.keys())
    elif isinstance(digests_used, (set, list, tuple)):
        used_digest_names = set(digests_used)
    else:
        raise TypeError(
            f"digests_used should be a set, list, tuple or dict, got {type(digests_used)!r}"
        )

    # Ensure every digest in manifest is used
    for digest_name, file_iterable in manifest_files.items():
        if not isinstance(digest_name, str):
            raise TypeError(
                f"Digest names must be strings, got {type(digest_name)!r}"
            )
        if not hasattr(file_iterable, "__iter__"):
            raise TypeError(
                f"Files for digest '{digest_name}' must be an iterable, got {type(file_iterable)!r}"
            )
        # Skip check if the digest is somehow not expected to be used (e.g. empty list)
        if ", ".join(map(str, file_iterable)) == "":
            continue
        if digest_name not in used_digest_names:
            raise ValueError(
                f"Digest '{digest_name}' appears in the manifest but is not reported as used."
            )

    # Ensure every used digest actually exists in the manifest
    for used_digest in used_digest_names:
        if used_digest not in manifest_files:
            raise ValueError(
                f"Digest '{used_digest}' is reported as used but does not exist in the manifest."
            )

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests in the manifest that are needed are both present
    and used. The function accepts any iterable for `manifest_files` where
    each item may be:
      - a mapping containing a 'digest' key,
      - an object exposing a `digest` attribute,
      - a string that is already the digest.
    `digests_used` is expected to be an iterable of digest strings.
    If any mismatch is found ValueError is raised, otherwise True is
    returned.
    """
    # Normalise digests_used to a set for efficient set operations
    if isinstance(digests_used, set):
        used_set = digests_used
    else:
        try:
            used_set = set(digests_used)
        except Exception as exc:
            raise ValueError(
                f"digests_used could not be converted to a set: {exc}"
            ) from exc

    # Extract digests from the manifest
    manifest_set = set()
    for idx, entry in enumerate(manifest_files):
        try:
            if isinstance(entry, dict):
                digest = entry.get('digest')
                if digest is None:
                    raise KeyError
            else:
                digest = getattr(entry, 'digest', None)
                if digest is None:
                    # If entry is a string treat it directly as a digest
                    if isinstance(entry, str):
                        digest = entry
                    else:
                        raise KeyError
        except KeyError:
            raise ValueError(
                f"Manifest entry at index {idx} lacks a usable digest: {entry}"
            ) from None
        if not isinstance(digest, str):
            raise ValueError(
                f"Digest extracted from manifest entry at index {idx} is not a string: {digest}"
            )
        manifest_set.add(digest)

    # Detect missing and unused digests
    missing = used_set - manifest_set
    if missing:
        raise ValueError(
            f"Used digests missing from manifest: {', '.join(sorted(missing))}"
        )

    unused = manifest_set - used_set
    if unused:
        raise ValueError(
            f"Digests present in manifest but not used: {', '.join(sorted(unused))}"
        )

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate that `manifest_files` is iterable
    try:
        manifest_iter = iter(manifest_files)
    except TypeError:
        raise TypeError("manifest_files must be an iterable of manifest dictionaries")

    # Normalise digests_used to a set for fast lookup
    if digests_used is None:
        digests_used_set = set()
    else:
        try:
            digests_used_set = set(digests_used)
        except TypeError:
            raise TypeError("digests_used must be an iterable of digest strings")

    # Collect all digests that should be present (found in the manifests)
    present_digests = set()

    for idx, manifest in enumerate(manifest_iter, start=1):
        if not isinstance(manifest, dict):
            raise ValueError(f"Manifest entry #{idx} is not a dictionary")
        digests = manifest.get("digests")
        if not isinstance(digests, dict):
            raise ValueError(f"Manifest entry #{idx} has no 'digests' dictionary")

        for alg, expected in digests.items():
            if not isinstance(expected, str):
                raise ValueError(f"Digest for algorithm '{alg}' in manifest #{idx} must be a string")
            digest_val = expected.strip()
            if not digest_val:
                raise ValueError(f"Digest for algorithm '{alg}' in manifest #{idx} is empty")

            present_digests.add(digest_val)

            # If a digest is required by the manifest but isn't used, raise an error
            if digest_val not in digests_used_set:
                raise ValueError(
                    f"Digest '{digest_val}' (algorithm '{alg}') from manifest #{idx} is required but not present in digests_used"
                )

    # After processing all manifests, ensure no unused digests remain
    for used in digests_used_set:
        if used not in present_digests:
            raise ValueError(f"Digest '{used}' is present in digests_used but not found in any manifest file")

    return True

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if prior is None:
            raise ValueError("prior cannot be None")
        # Ensure the object type
        try:
            import inspect
            if not inspect.isclass(prior.__class__):
                raise TypeError
        except Exception:
            # If InventoryValidator is not imported, defer to isinstance check
            pass
        if not isinstance(prior, InventoryValidator):
            raise TypeError(f"prior must be an InventoryValidator instance, got {type(prior).__name__}")

        # Helper to fetch an attribute safely
        def _get_attr(obj, *attrs):
            for name in attrs:
                if hasattr(obj, name):
                    return getattr(obj, name)
            return None

        # Check that both represent the same inventory entity
        self_id = _get_attr(self, "inventory_id", "id", "name")
        prior_id = _get_attr(prior, "inventory_id", "id", "name")
        if self_id is None or prior_id is None:
            raise ValueError("Unable to determine inventory identifiers on one or both objects.")
        if self_id != prior_id:
            raise ValueError(f"Inventory identity mismatch: self={self_id}, prior={prior_id}")

        # Retrieve the version values
        self_version = _get_attr(self, "version", "revision", "version_number")
        prior_version = _get_attr(prior, "version", "revision", "version_number")
        if self_version is None or prior_version is None:
            raise ValueError("Unable to determine version for one or both inventory objects.")

        # Compare versions: the prior must be older (smaller) than self
        try:
            # Try numeric comparison first
            self_num = float(self_version)
            prior_num = float(prior_version)
            comparator = lambda a, b: a > b
        except Exception:
            # Fallback to lexicographic
            self_num = self_version
            prior_num = prior_version
            comparator = lambda a, b: a > b

        if not comparator(self_num, prior_num):
            raise ValueError(
                f"Prior version ({prior_version}) is not earlier than current version ({self_version})."
            )

        # All checks passed
        return True

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure the passed object is an InventoryValidator instance
        if not isinstance(prior, InventoryValidator):
            raise TypeError("prior must be an InventoryValidator instance")

        # Helper to retrieve the first existing attribute from a list of names
        def _get_attr(obj, names):
            for name in names:
                if hasattr(obj, name):
                    return getattr(obj, name)
            return None

        # The inventory should refer to the same logical entity
        self_id = _get_attr(self, ["id", "inventory_id", "uuid"])
        prior_id = _get_attr(prior, ["id", "inventory_id", "uuid"])
        if self_id is None or prior_id is None:
            raise ValueError("unable to determine inventory identifiers")
        if self_id != prior_id:
            raise ValueError("prior inventory does not match current inventory")

        # Version comparison: prior should be strictly older than self
        self_version = _get_attr(self, ["version", "ver", "v"])
        prior_version = _get_attr(prior, ["version", "ver", "v"])
        if self_version is None or prior_version is None:
            raise ValueError("missing version information")

        def _numeric(val):
            try:
                return float(val)
            except Exception:
                return None

        float_self = _numeric(self_version)
        float_prior = _numeric(prior_version)

        if float_self is not None and float_prior is not None:
            if not float_prior < float_self:
                raise ValueError("prior version is not older than current version")
        else:
            # Fall back to lexical string comparison
            if str(prior_version) >= str(self_version):
                raise ValueError("prior version must be lexically older than current")

        # Timestamp comparison: prior should be earlier
        self_ts = _get_attr(self, ["timestamp", "updated", "last_modified"])
        prior_ts = _get_attr(prior, ["timestamp", "updated", "last_modified"])
        if self_ts is not None and prior_ts is not None:
            try:
                # If they are datetime-like objects with a timestamp() method
                if hasattr(self_ts, "timestamp") and hasattr(prior_ts, "timestamp"):
                    if prior_ts.timestamp() >= self_ts.timestamp():
                        raise ValueError("prior inventory has a newer timestamp")
                else:
                    # Fallback string comparison
                    if str(prior_ts) >= str(self_ts):
                        raise ValueError("prior inventory has a newer timestamp")
            except Exception:
                # If comparison fails we ignore the timestamp check but
                # the earlier version check is still enforced
                pass

        # All checks passed; prior is a valid earlier version
        return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Verify that prior is an instance of the same class
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"prior must be an instance of {type(self).__name__}, "
            f"got {type(prior).__name__}"
        )
    # Ensure both objects have the required attributes
    required_attrs = ("inventory_id", "version")
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(f"Current object missing required attribute '{attr}'")
        if not hasattr(prior, attr):
            raise AttributeError(f"Prior object missing required attribute '{attr}'")
    # Check that the inventory identifiers match
    if self.inventory_id != prior.inventory_id:
        raise ValueError(
            f"Inventory IDs do not match: current='{self.inventory_id}' vs prior='{prior.inventory_id}'"
        )
    # Ensure versions are numeric and comparable
    if not isinstance(self.version, (int, float)):
        raise TypeError(f"Current version must be numeric, got {type(self.version).__name__}")
    if not isinstance(prior.version, (int, float)):
        raise TypeError(f"Prior version must be numeric, got {type(prior.version).__name__}")
    # Prior version must be strictly less than current version
    if prior.version >= self.version:
        raise ValueError(
            f"Prior version ({prior.version}) must be less than current version ({self.version})"
        )
    # Optional consistency checks could be added here (e.g., timestamps, checksums) if available
    return True

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Basic type check
        if not isinstance(prior, type(self)):
            raise TypeError(f"Expected prior to be an instance of {type(self).__name__}, got {type(prior).__name__}")

        # Ensure both objects have the required attributes
        required_attrs = ('version', 'last_modified', 'items')
        for attr in required_attrs:
            if not hasattr(self, attr) or not hasattr(prior, attr):
                raise AttributeError(f"Both inventory objects must have a '{attr}' attribute")

        # Compare version numbers: prior must be older
        try:
            if prior.version >= self.version:
                raise ValueError(f"Prior version ({prior.version}) is not older than current version ({self.version})")
        except Exception as exc:
            raise TypeError(f"Version comparison failed: {exc}")

        # Compare modification timestamps: prior must be earlier or same
        try:
            # Assume last_modified is comparable (datetime or numeric)
            if prior.last_modified > self.last_modified:
                raise ValueError(f"Prior last_modified ({prior.last_modified}) is later than current last_modified ({self.last_modified})")
        except Exception as exc:
            raise TypeError(f"Last modified comparison failed: {exc}")

        # Ensure prior items are a subset of current items (if they are dict-like)
        try:
            prior_keys = set(prior.items.keys())
            current_keys = set(self.items.keys())
            if not prior_keys.issubset(current_keys):
                missing = prior_keys - current_keys
                raise ValueError(f"Prior inventory has items not present in current inventory: {missing}")
        except Exception as exc:
            # If items attribute is not a dict-like, skip subset check
            pass

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is a valid InventoryValidator instance
    try:
        # Look up the class name of the current instance for type checking
        validator_cls = type(self)
    except Exception:
        raise TypeError("Current object is not a valid InventoryValidator instance")

    if not isinstance(prior, validator_cls):
        raise TypeError(
            f"prior must be an instance of {validator_cls.__name__}, "
            f"got {type(prior).__name__}"
        )

    # Check that both inventories have the same underlying type
    if not hasattr(self, "inventory") or not hasattr(prior, "inventory"):
        raise AttributeError("Both objects must have an 'inventory' attribute")

    self_inv = self.inventory
    prior_inv = prior.inventory

    if type(self_inv) is not type(prior_inv):
        raise ValueError("Inventory objects types do not match")

    # Attempt to determine ordering using common attributes
    def _get_order_key(inv):
        # Prefer explicit 'version' attribute if present
        if hasattr(inv, "version"):
            return int(inv.version)
        # Fallback to timestamp attribute
        if hasattr(inv, "created_at"):
            return inv.created_at
        # Fallback to id comparison if both have numeric ids
        if hasattr(inv, "id") and isinstance(inv.id, (int, float)):
            return inv.id
        # If nothing identifiable, raise
        raise AttributeError(
            "Cannot determine ordering: inventory lacks 'version', 'created_at', or numeric 'id'"
        )

    try:
        self_key = _get_order_key(self_inv)
        prior_key = _get_order_key(prior_inv)
    except AttributeError as exc:
        raise ValueError(str(exc))

    # If keys are timestamps or numeric, ensure prior < current
    try:
        if prior_key >= self_key:
            raise ValueError(
                f"prior inventory is not older than the current inventory "
                f"(prior key: {prior_key}, current key: {self_key})"
            )
    except TypeError:
        # If comparison is not supported (e.g., different types)
        raise ValueError(
            f"Unable to compare inventory version keys: prior={prior_key}, current={self_key}"
        )

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate input types
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or list")
    if not isinstance(version, (int, str)):
        raise TypeError("version must be an int or a string")

    # Helper to get numeric value for sorting
    def _to_num(v):
        try:
            return float(v)
        except Exception:
            return None

    # Helper to create mapping from logical_path to set of files for a specific data dict
    def _map_from_dict(data_dict):
        mapping = {}
        for lp, files in data_dict.items():
            if isinstance(files, (list, tuple, set)):
                mapping.setdefault(lp, set()).update(files)
            else:
                mapping.setdefault(lp, set()).add(files)
        return mapping

    # Main logic
    try:
        # Case 1: inventory is a dict with a 'versions' mapping
        if isinstance(inventory, dict) and 'versions' in inventory:
            versions_map = inventory['versions']
            if not isinstance(versions_map, dict):
                raise ValueError("'versions' entry should be a dict")
            # Ensure requested version exists
            if version not in versions_map:
                raise KeyError(f"Version {version} not found in inventory")
            # Start with mapping from current version
            result = _map_from_dict(versions_map[version]) if isinstance(versions_map[version], dict) else {}

            # Gather duplicates from later versions
            # Determine order: try numeric sort, fall back to original order
            version_keys = list(versions_map.keys())
            # Determine numeric values if possible
            numeric_versions = [_to_num(v) for v in version_keys]
            if all(val is not None for val in numeric_versions):
                # sort numerically
                ordered_keys = sorted(zip(numeric_versions, version_keys), key=lambda x: x[0])
                ordered_keys = [k for _, k in ordered_keys]
            else:
                ordered_keys = version_keys  # keep original order

            try:
                idx = ordered_keys.index(version)
            except ValueError:
                idx = -1
            if idx != -1:
                later_keys = ordered_keys[idx + 1 :]
                for later_ver in later_keys:
                    later_data = versions_map[later_ver]
                    if not isinstance(later_data, dict):
                        continue
                    for lp, files in later_data.items():
                        if lp in result:
                            if isinstance(files, (list, tuple, set)):
                                result[lp].update(files)
                            else:
                                result[lp].add(files)
                        else:
                            result.setdefault(lp, set()).update(
                                files if isinstance(files, (list, tuple, set)) else {files}
                            )
            return result

        # Case 2: inventory is a dict where each key is a version mapping to logical-path data
        if isinstance(inventory, dict):
            # Assume version key maps directly to data dict
            if version in inventory:
                data = inventory[version]
                if isinstance(data, dict):
                    result = _map_from_dict(data)
                    # Attempt to merge later versions if numeric
                    keys = list(inventory.keys())
                    numeric_keys = [_to_num(k) for k in keys]
                    if all(v is not None for v in numeric_keys):
                        ordered_keys = sorted(zip(numeric_keys, keys), key=lambda x: x[0])
                        ordered_keys = [k for _, k in ordered_keys]
                    else:
                        ordered_keys = keys
                    try:
                        idx = ordered_keys.index(version)
                    except ValueError:
                        idx = -1
                    if idx != -1:
                        later_keys = ordered_keys[idx + 1 :]
                        for later_ver in later_keys:
                            later_data = inventory[later_ver]
                            if isinstance(later_data, dict):
                                for lp, files in later_data.items():
                                    if lp in result:
                                        if isinstance(files, (list, tuple, set)):
                                            result[lp].update(files)
                                        else:
                                            result[lp].add(files)
                                    else:
                                        result.setdefault(lp, set()).update(
                                            files if isinstance(files, (list, tuple, set)) else {files}
                                        )
                    return result
            # If version key not found, try deep scan of dict values
            result = {}
            for key, value in inventory.items():
                if isinstance(value, dict) and 'version' in value and value['version'] == version:
                    logical_path = value.get('logical_path')
                    files = value.get('content_files') or value.get('files') or value.get('file')
                    if logical_path:
                        if isinstance(files, (list, tuple, set)):
                            result.setdefault(logical_path, set()).update(files)
                        else:
                            result.setdefault(logical_path, set()).add(files)
            return result

        # Case 3: inventory is a list of entries
        if isinstance(inventory, list):
            result = {}
            for entry in inventory:
                if not isinstance(entry, dict):
                    continue
                if entry.get('version') == version:
                    logical_path = entry.get('logical_path')
                    files = entry.get('content_files') or entry.get('files') or entry.get('file')
                    if logical_path:
                        if isinstance(files, (list, tuple, set)):
                            result.setdefault(logical_path, set()).update(files)
                        else:
                            result.setdefault(logical_path, set()).add(files)
            # Merge duplicates from later list entries with higher version
            try:
                version_index = [e.get('version') for e in inventory].index(version)
            except Exception:
                version_index = -1
            if version_index != -1:
                later_entries = inventory[version_index + 1 :]
                for entry in later_entries:
                    if not isinstance(entry, dict):
                        continue
                    if entry.get('version') == entry.get('version'):  # just continue
                        logical_path = entry.get('logical_path')
                        files = entry.get('content_files') or entry.get('files') or entry.get('file')
                        if logical_path:
                            if logical_path in result:
                                if isinstance(files, (list, tuple, set)):
                                    result[logical_path].update(files)
                                else:
                                    result[logical_path].add(files)
                            else:
                                result.setdefault(logical_path, set()).update(
                                    files if isinstance(files, (list, tuple, set)) else {files}
                                )
            return result

    except Exception:
        # If any error occurs, fall back to an empty mapping
        return {}

    # If no mapping found, return empty dict
    return {}

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")
    if version is None:
        raise ValueError("version must not be None")

    path_map = {}

    # Try to determine if inventory is a mapping or iterable of items
    try:
        iter_invent = iter(inventory)
    except TypeError:
        raise TypeError("inventory must be a mapping or iterable of items")

    # Helper to extract fields with common alternatives
    def get_field(item, *names):
        for name in names:
            if isinstance(item, dict) and name in item:
                return item[name]
            # Handle attribute access if item is an object
            if hasattr(item, name):
                return getattr(item, name)
        return None

    for entry in iter_invent:
        if entry is None:
            continue

        entry_version = get_field(entry, "version", "ver", "item_version")
        if entry_version is None:
            continue
        # Convert numeric string versions to same type for comparison
        try:
            if isinstance(version, int):
                entry_version = int(entry_version)
            else:
                entry_version = str(entry_version)
        except Exception:
            # If conversion fails, skip this entry
            continue

        if entry_version != version:
            continue

        logical_path = get_field(entry, "logical_path", "path", "key")
        if logical_path is None:
            continue

        content_file = get_field(entry, "content_file", "file", "file_name", "file_path")
        if content_file is None:
            continue

        try:
            content_set = path_map.setdefault(logical_path, set())
            content_set.add(content_file)
        except Exception as e:
            # In case of any error in adding, skip that entry
            continue

    return path_map

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """
    from collections import defaultdict

    def _ver_key(v):
        """Return a comparable key for a version string."""
        if isinstance(v, (int, float)):
            return (v,)
        try:
            return tuple(int(part) if part.isdigit() else part for part in str(v).split('.'))
        except Exception:
            return (str(v),)

    # Validate input types
    if version is None:
        raise ValueError("Missing version argument")
    if inventory is None:
        raise ValueError("Missing inventory argument")

    result = defaultdict(set)

    # Helper to process mapping of logical_path -> iterable of content files
    def _process_mapping(mapping):
        for lp, files in mapping.items():
            if isinstance(files, (set, list, tuple)):
                result[lp].update(files)
            else:
                result[lp].add(files)

    # Case 1: inventory is a dict mapping versions to mappings
    if isinstance(inventory, dict):
        # If inventory contains nested structure like {'versions': {...}}
        if 'versions' in inventory and isinstance(inventory['versions'], dict):
            inv_map = inventory['versions']
        else:
            inv_map = inventory

        base_key = _ver_key(version)

        for ver, mapping in inv_map.items():
            if not isinstance(mapping, dict):
                continue
            if _ver_key(ver) >= base_key:
                _process_mapping(mapping)

    # Case 2: inventory is a list of entries
    elif isinstance(inventory, (list, tuple)):
        base_key = _ver_key(version)
        for entry in inventory:
            try:
                if isinstance(entry, dict):
                    lp = entry.get('logical_path')
                    cf = entry.get('content_file')
                    ver = entry.get('version')
                    if not (lp and cf and ver is not None):
                        continue
                    if _ver_key(ver) >= base_key:
                        result[lp].add(cf)
                elif isinstance(entry, (list, tuple)) and len(entry) >= 3:
                    lp, cf, ver = entry[0], entry[1], entry[2]
                    if not (lp and cf and ver is not None):
                        continue
                    if _ver_key(ver) >= base_key:
                        result[lp].add(cf)
            except Exception:
                # Ignore malformed entries
                continue
    else:
        raise TypeError("Unsupported inventory type: must be dict or list")

    return dict(result)

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic input validation
    if not hasattr(inventory, "__getitem__"):
        raise TypeError("inventory must support key access (e.g., a dict or similar mapping)")
    # Retrieve the state for the requested version
    try:
        state = inventory[version]
    except KeyError:
        raise ValueError(f"Version '{version}' not found in inventory")
    mapping = {}
    # Determine the mapping structure
    if isinstance(state, dict):
        # Assume state itself is a logical-path-to-files mapping
        for logical_path, files in state.items():
            if isinstance(files, (set, list, tuple)):
                mapping[logical_path] = set(files)
            else:
                mapping[logical_path] = {files}
    else:
        # Try to call a method if the state object offers one
        get_map = getattr(state, "get_logical_path_map", None)
        if callable(get_map):
            try:
                map_result = get_map()
            except Exception as exc:  # pragma: no cover
                raise RuntimeError(f"Error calling get_logical_path_map on state {version}: {exc}") from exc
            if not isinstance(map_result, dict):
                raise TypeError(f"get_logical_path_map() should return a dict; got {type(map_result).__name__}")
            # Normalize values to sets
            for key, val in map_result.items():
                if isinstance(val, (set, list, tuple)):
                    mapping[key] = set(val)
                else:
                    mapping[key] = {val}
        else:  # pragma: no cover
            raise TypeError("inventory[version] must be a mapping or provide a get_logical_path_map() method")

    # Include references to duplicate files from later versions if available
    try:
        later_versions = [v for v in inventory.keys() if v > version]
    except Exception:  # pragma: no cover
        later_versions = []

    for later_ver in later_versions:
        try:
            later_state = inventory[later_ver]
        except Exception:  # pragma: no cover
            continue
        if isinstance(later_state, dict):
            for lp, files in later_state.items():
                if lp in mapping:
                    if isinstance(files, (set, list, tuple)):
                        mapping[lp].update(files)
                    else:
                        mapping[lp].add(files)
        else:
            get_map = getattr(later_state, "get_logical_path_map", None)
            if callable(get_map):
                try:
                    later_map = get_map()
                except Exception:  # pragma: no cover
                    continue
                if isinstance(later_map, dict):
                    for lp, files in later_map.items():
                        if lp in mapping:
                            if isinstance(files, (set, list, tuple)):
                                mapping[lp].update(files)
                            else:
                                mapping[lp].add(files)
    return mapping

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.
    """
    try:
        # Basic type checks
        if fixity is None:
            # No fixity block to validate – consider it valid
            return True
        if not isinstance(fixity, dict):
            raise TypeError("fixity must be a dict")

        if manifest_files is None:
            raise TypeError("manifest_files must be provided")
        if not isinstance(manifest_files, (set, list, tuple)):
            # Attempt to convert iterable to set for membership tests
            try:
                manifest_set = set(manifest_files)
            except Exception as exc:
                raise TypeError("manifest_files must be an iterable of file names") from exc
        else:
            manifest_set = set(manifest_files)

        # Validate each entry in the fixity block
        for file_path, checks in fixity.items():
            if file_path not in manifest_set:
                raise ValueError(f"Fixity references unknown file '{file_path}' not present in manifest")
            if not isinstance(checks, dict):
                raise ValueError(f"Fixity entry for '{file_path}' must be a dict mapping checksum algorithms to values")
            if not checks:
                raise ValueError(f"Fixity entry for '{file_path}' is empty; at least one checksum is required")
            for algo, value in checks.items():
                if not isinstance(algo, str) or not isinstance(value, str):
                    raise ValueError(
                        f"Checksum algorithm and value must be strings for file '{file_path}': got algo={algo!r}, value={value!r}"
                    )

        # All checks passed
        return True

    except (TypeError, ValueError) as exc:
        # Re‑raise validation errors to callers
        raise
    except Exception as exc:
        # Wrap unexpected exceptions in a RuntimeError to preserve the stack trace
        raise RuntimeError(f"Error while validating fixity block: {exc}") from exc

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise TypeError("fixity must be a dict mapping file paths to checksum values")
    if not isinstance(manifest_files, (list, set, tuple)):
        raise TypeError("manifest_files must be an iterable of file path strings")

    # Convert manifest list to a set for faster lookup
    manifest_set = set()
    for f in manifest_files:
        if not isinstance(f, str):
            raise TypeError(f"Manifest entry {f!r} is not a string")
        manifest_set.add(f)

    errors = []

    # Ensure each key in fixity is a string path present in the manifest
    for file_path, checksum in fixity.items():
        if not isinstance(file_path, str):
            errors.append(f"Fixity key {file_path!r} is not a string")
            continue
        if file_path not in manifest_set:
            errors.append(f"File {file_path!r} referenced in fixity but not present in manifest")
        if not isinstance(checksum, str):
            errors.append(f"Checksum for file {file_path!r} is not a string")

    if errors:
        raise ValueError("Fixity validation failed: " + "; ".join(errors))

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Basic type checks
        if not isinstance(fixity, dict):
            raise ValueError(f"Fixity block must be a dictionary, got {type(fixity).__name__}")
        if not isinstance(manifest_files, (list, tuple, set)):
            raise ValueError(f"manifest_files must be a list/tuple/set, got {type(manifest_files).__name__}")

        # Determine the key that contains the list of referenced files.
        # Common conventions: 'files', 'items', 'file', 'data', etc.
        file_keys = {"files", "items", "file", "data"}
        file_list = None
        for key in file_keys:
            if key in fixity:
                file_list = fixity[key]
                break

        if file_list is None:
            raise KeyError(f"Fixity block does not contain any recognized key for file list: {file_keys}")

        # Ensure the file list is iterable
        if not isinstance(file_list, (list, tuple)):
            raise ValueError(f"The value for key '{key}' must be a list or tuple, got {type(file_list).__name__}")

        # If the list contains dicts, look for 'path' or 'name' keys
        referenced_files = []
        for entry in file_list:
            if isinstance(entry, dict):
                # Attempt to find a plausible filename key
                for fname_key in ("path", "name", "filename"):
                    if fname_key in entry:
                        referenced_files.append(entry[fname_key])
                        break
                else:
                    # No filename key found; treat entire dict as is (skip)
                    continue
            elif isinstance(entry, str):
                referenced_files.append(entry)
            else:
                raise ValueError(f"Unexpected entry type in fixity file list: {type(entry).__name__}")

        # Check that each referenced file is present in the manifest
        missing_entries = [f for f in referenced_files if f not in manifest_files]
        if missing_entries:
            raise ValueError(f"Fixity block references files not present in the manifest: {missing_entries}")

        # If all checks pass, return a truthy value (True)
        return True

def files_list(path):
    """
    Return the files in `path`
    """
    # Use __import__ to avoid a top‑level import statement
    os = __import__("os")

    # Validate input type
    if not isinstance(path, (str, os.PathLike)):
        raise TypeError(f"`path` must be a string or PathLike object, got {type(path).__name__}")

    # Resolve the path to a string if it's PathLike
    try:
        path_str = os.fspath(path)
    except Exception as e:
        raise TypeError(f"Unable to convert `path` to a path string: {e}") from e

    # Check existence
    if not os.path.exists(path_str):
        raise FileNotFoundError(f"The specified path does not exist: {path_str}")

    # Must be a directory
    if not os.path.isdir(path_str):
        raise NotADirectoryError(f"Specified path is not a directory: {path_str}")

    try:
        # List entries, filter to files only
        files = [
            entry
            for entry in os.listdir(path_str)
            if os.path.isfile(os.path.join(path_str, entry))
        ]
        # Return sorted list for consistency
        return sorted(files)
    except OSError as exc:
        # Wrap low‑level OS errors into a more general exception
        raise RuntimeError(f"Error reading directory '{path_str}': {exc}") from exc

def files_list(path):
    """
    Return the files in `path`.
    """
    # Import modules locally to avoid top‑level imports
    try:
        import os
        from pathlib import Path
    except Exception as exc:
        raise RuntimeError("Required modules (os, pathlib) are not available") from exc

    # Validate the input path
    try:
        p = Path(path)
    except Exception as exc:
        raise TypeError("The 'path' argument must be a string, bytes, or Pathlike object") from exc

    if not p.exists():
        raise FileNotFoundError(f"Path '{p}' does not exist.")
    if not p.is_dir():
        raise NotADirectoryError(f"Path '{p}' is not a directory.")

    # Retrieve files only
    try:
        files = [entry.name for entry in p.iterdir() if entry.is_file()]
    except OSError as exc:
        raise RuntimeError(f"Error accessing contents of directory '{p}': {exc}") from exc

    return files

def files_list(path):
    """
    Return the files in `path`
    """
    # Validate input
    if not isinstance(path, str):
        return []
    try:
        os = __import__('os')
        if not os.path.isdir(path):
            return []
        entries = os.listdir(path)
        files = []
        for entry in entries:
            full_path = os.path.join(path, entry)
            if os.path.isfile(full_path):
                files.append(entry)
        return files
    except Exception:
        return []

def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : Any
        Root source (unused in this implementation but kept for compatibility).
    xmls : list of str
        XML filenames.
    files : list of str
        List of files in the folder or zipfile.

    Returns
    -------
    dict
        key: basename of the XML files without extension
        value: list of files belonging to that basename
    """
    # Validate input types
    if not isinstance(xmls, (list, tuple)):
        raise TypeError("xmls must be a list or tuple of strings")
    if not isinstance(files, (list, tuple)):
        raise TypeError("files must be a list or tuple of strings")
    for i, xml in enumerate(xmls):
        if not isinstance(xml, str):
            raise TypeError(f"xmls[{i}] is not a string")
    for i, f in enumerate(files):
        if not isinstance(f, str):
            raise TypeError(f"files[{i}] is not a string")

    # Build a mapping from XML basename to a list of files
    mapping = {}
    try:
        for xml in xmls:
            # Strip extension and keep only the base name
            if '.' in xml:
                base = xml.rsplit('.', 1)[0]
            else:
                base = xml
            mapping[base] = []

        for file_path in files:
            # Extract the file name (basename) without directories
            # Handle both Unix and Windows path separators
            basename = file_path.split('/')[-1].split('\\')[-1]
            if '.' in basename:
                file_base = basename.rsplit('.', 1)[0]
            else:
                file_base = basename
            # Assign the file to the corresponding XML base group if it exists
            if file_base in mapping:
                mapping[file_base].append(file_path)
            else:
                # If the file base does not match any XML base, we can skip or
                # optionally place it in a special "unmatched" group.
                # Here we simply skip it.
                continue
    except Exception as exc:
        raise RuntimeError(f"Failed to group files by XML basename: {exc}") from exc

    return mapping

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError("The 'folder' argument must be a string representing a path.")
    if not os.path.isdir(folder):
        raise NotADirectoryError(f"The specified path does not exist or is not a directory: {folder}")

    grouped = {}
    try:
        for entry in os.listdir(folder):
            path = os.path.join(folder, entry)
            if not os.path.isfile(path):
                continue  # skip non-file entries
            base, ext = os.path.splitext(entry)
            grouped.setdefault(base, []).append(entry)
    except OSError as exc:
        raise RuntimeError(f"Error accessing files in '{folder}': {exc}") from exc

    # Filter only basenames that have at least one XML file
    result = {base: files for base, files in grouped.items() if any(os.path.splitext(f)[1].lower() == ".xml" for f in files)}
    return result

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    try:
        # Dynamically import os to avoid top‑level import
        os = __import__('os')
        if not os.path.isdir(folder):
            return {}
        data = {}
        # Walk through the directory tree
        for root, _, files in os.walk(folder):
            for fname in files:
                base, ext = os.path.splitext(fname)
                full_path = os.path.join(root, fname)
                data.setdefault(base, []).append(full_path)
        # Keep only groups that contain an XML file
        result = {}
        for base, paths in data.items():
            if any(p.lower().endswith('.xml') for p in paths):
                result[base] = paths
        return result
    except Exception:
        # If anything goes wrong (e.g., permission error), return empty dict
