def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    if not isinstance(folder, str):
        raise TypeError("folder must be a string")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder not found: {folder}")
    data = {}
    # First pass: collect all XML base names
    xml_bases = set()
    try:
        for name in os.listdir(folder):
            full_path = os.path.join(folder, name)
            if os.path.isfile(full_path):
                _, ext = os.path.splitext(name)
                if ext.lower() == ".xml":
                    xml_bases.add(os.path.splitext(name)[0])
    except OSError as exc:
        raise RuntimeError(f"Error accessing folder {folder}: {exc}") from exc
    # Second pass: group files by those base names
    try:
        for name in os.listdir(folder):
            full_path = os.path.join(folder, name)
            if os.path.isfile(full_path):
                base = os.path.splitext(name)[0]
                if base in xml_bases:
                    data.setdefault(base, []).append(full_path)
    except OSError as exc:
        raise RuntimeError(f"Error scanning folder {folder}: {exc}") from exc
    return data

def add_rendition(self, lang, file_path):
        """
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }
        """
        try:
            if not isinstance(lang, str) or not isinstance(file_path, str):
                raise TypeError("Both 'lang' and 'file_path' must be strings.")
            # Separate base name and extension
            if '.' in file_path:
                base, ext = file_path.rsplit('.', 1)
                ext = '.' + ext
            else:
                base, ext = file_path, ''
            # Attempt to remove the language suffix (e.g., '-en') from the base
            suffix = '-' + lang
            if base.endswith(suffix):
                original_base = base[:-len(suffix)]
            else:
                # Fallback: assume file_path itself is the original
                original_base = base
            original = original_base + ext
            # Initialize the renditions dictionary if it doesn't exist
            if not hasattr(self, 'renditions') or not isinstance(self.renditions, dict):
                self.renditions = {}
            # Store the rendition in a nested dictionary
            if original not in self.renditions:
                self.renditions[original] = {}
            self.renditions[original][lang] = file_path
        except Exception as exc:
            raise RuntimeError(f"add_rendition failed: {exc}") from exc

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        A dictionary where each key is the basename of an XML file (without extension) found
        in the zip archive. Each value is another dictionary with two keys:
            - 'xml'   : the XML file's content as a UTF-8 decoded string, or None if no XML
            - 'files' : a list of all file names within the zip that share this basename,
                        including the XML itself.
    """
    import os
    import zipfile

    # Basic input validation
    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")
    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for arcname in zf.namelist():
                # Ignore directories
                if arcname.endswith('/'):
                    continue

                base_name = os.path.splitext(os.path.basename(arcname))[0]
                if base_name not in result:
                    result[base_name] = {'xml': None, 'files': []}

                result[base_name]['files'].append(arcname)

                if arcname.lower().endswith('.xml'):
                    try:
                        raw_bytes = zf.read(arcname)
                        # Attempt UTF-8 decoding; fallback to raw bytes if decoding fails
                        try:
                            text = raw_bytes.decode('utf-8')
                        except UnicodeDecodeError:
                            text = raw_bytes.decode('latin1')
                        result[base_name]['xml'] = text
                    except (KeyError, OSError) as exc:
                        # If reading fails, log the issue and continue
                        result[base_name]['xml'] = None
    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Error reading zip file '{zip_path}': {exc}") from exc
    except Exception as exc:
        # Catch any other unexpected errors and raise more informative messages
        raise RuntimeError(f"An unexpected error occurred while processing '{zip_path}': {exc}") from exc

    return result

def files_list_from_zipfile(zip_path):
    """
    Return the files in `zip_path`
    """
    try:
        import zipfile
        with zipfile.ZipFile(zip_path, 'r') as z:
            # Filter out directory entries and sort the file list
            file_names = sorted(
                [name for name in z.namelist() if not name.endswith('/')]
            )
            return file_names
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Zip file not found: {zip_path}") from e
    except zipfile.BadZipFile as e:
        raise ValueError(f"Cannot read zip file, bad format: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error reading zip file {zip_path}: {e}") from e

