def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            results = node.xpath(xpath)
        except Exception:
            # seu node pode não suportar xpath ou a expressão é inválida; tenta a próxima
            continue
        if not results:
            continue
        first = results[0]
        # Se o resultado já for string, devolve direto
        if isinstance(first, str):
            return first
        # Caso seja um elemento XML
        if hasattr(first, 'text'):
            if first.text and first.text.strip():
                return first.text.strip()
            # Se text estiver vazio, tenta concatenar todo o texto descendente
            text = ''.join(first.itertext()).strip()
            if text:
                return text
        # Tipo inesperado, converte para string
        try:
            return str(first).strip()
        except Exception:
            continue
    # Se não encontrou nenhuma correspondência, devolve None
    return None

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Se node não for fornecido ou não possuir método xpath, não há nada a fazer
    if node is None:
        return None
    try:
        # Itera sobre as expressões XPath na ordem dada
        for xp in pubdate_xpaths:
            try:
                # Executa a consulta XPath
                result = node.xpath(xp)
                # Se retornou algo, tenta extrair o valor
                if result:
                    # Se for lista/tupla retornamos o primeiro item
                    if isinstance(result, (list, tuple)):
                        first = result[0]
                        # Se for string, retornamos direto
                        if isinstance(first, str):
                            return first
                        # Se for elemento XML, retornamos seu texto
                        if hasattr(first, 'text'):
                            return first.text
                        # Caso não seja string nem tenha texto, retornamos o objeto
                        return first
                    # Se o resultado não for lista (string, número, etc.), retornamos
                    return result
            except Exception:
                # Se a expressão XPath falhar (por erros de sintaxe ou outros), simplesmente ignoramos
                continue
    except Exception:
        # Qualquer outro erro inesperado
        pass
    # Se nenhuma expressão produziu resultado, retornamos None
    return None

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Ensure node is not None
    if node is None:
        return None

    # Normalise pubdate_xpaths to a list
    if isinstance(pubdate_xpaths, (list, tuple)):
        xpaths = pubdate_xpaths
    elif isinstance(pubdate_xpaths, str):
        xpaths = [pubdate_xpaths]
    else:
        return None

    for xpath_expr in xpaths:
        try:
            # Execute the XPath expression
            result = node.xpath(xpath_expr)

            if not result:
                continue

            # If result is a list, take the first element
            if isinstance(result, list):
                value = result[0]
            else:
                value = result

            # Convert the value to a string
            if isinstance(value, str):
                value_str = value.strip()
            elif hasattr(value, "itertext"):
                # For lxml Element nodes
                value_str = "".join(value.itertext()).strip()
            else:
                value_str = str(value).strip()

            if value_str:
                return value_str
        except Exception:
            # Skip any XPath errors and continue
            continue

    return None

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths.
    Se nenhum XPath devolver resultados, retorna None.
    """
    # Validações básicas
    if node is None:
        return None
    if not hasattr(node, "xpath"):
        return None
    if not isinstance(pubdate_xpaths, (list, tuple)):
        try:
            pubdate_xpaths = list(pubdate_xpaths)
        except Exception:
            return None

    for expr in pubdate_xpaths:
        if not expr:
            continue
        try:
            # Executa o XPath
            result = node.xpath(expr)
        except Exception:
            # Caso a expressão seja inválida ou ocorra erro de execução, ignora e tenta o próximo
            continue

        if result:
            first = result[0]
            # Se o resultado for string, simplesmente devolve
            if isinstance(first, str):
                return first.strip()
            # Se for um elemento, tenta extrair o texto interno
            if hasattr(first, "text"):
                text = first.text
                if text is not None:
                    return text.strip()
            # Caso não consiga extrair texto, devolve a representação string do objeto
            return str(first).strip()

    # Nenhum XPath retornou resultado válido
    return None

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re
    try:
        if issue is None:
            return None, None
        # Extract text content if issue is an lxml element
        if hasattr(issue, 'text'):
            content = issue.text or ''
        else:
            content = str(issue)

        content = content.strip()
        if not content:
            return None, None

        # Find number (sequence of digits, possibly with a hyphen)
        number_match = re.search(r'\d+(?:-\d+)?', content)
        number = number_match.group() if number_match else None

        # Detect supplement keyword (suppl, supp, spe, or s)
        suppl = None
        L = content.lower()
        if 'suppl' in L:
            suppl = 'suppl'
        elif 'supp' in L:
            suppl = 'supp'
        elif 'spe' in L:
            # Ensure we are not matching substrings like 'spelling'
            if re.search(r'\b[sS][pP][eE]', L):
                suppl = 'spe'
        if suppl is None and content and content[0].lower() == 's':
            # could be 's2' or similar
            if re.match(r'^s\d+', content, re.IGNORECASE):
                suppl = 's'
        return number, suppl
    except Exception:
        return None, None

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re

    try:
        if issue is None:
            return None, None
        # Retira tudo que não pertencem a texto do elemento, caso seja lxml.etree.Element
        if hasattr(issue, "text_content"):
            text = issue.text_content()
        else:
            # Se for string
            try:
                text = str(issue)
            except Exception:
                return None, None
        text = text.strip()
        if not text:
            return None, None

        # Inicializa retornos
        number = None
        suppl = None

        # Busca por número (poderia ser range, ex. '2-5')
        num_match = re.search(r'\d+(?:-\d+)?', text)
        if num_match:
            num_str = num_match.group()
            # Se houver hífen, mantém como string, senão tenta converter para int
            if '-' in num_str:
                number = num_str
            else:
                try:
                    number = int(num_str)
                except ValueError:
                    number = num_str
            rest = text[num_match.end():].strip()

            # Busca pela próxima palavra que contenha letra(s) (suppl, spe, etc.)
            sup_match = re.search(r'([a-zA-Z\.]+)', rest)
            if sup_match:
                sup_word = sup_match.group(1)
                # Remove possíveis pontuações no início ou fim da palavra
                sup_word = sup_word.strip('.')
                # Verifica se há número logo após a palavra
                post_digits = re.search(r'\d+', rest[sup_match.end():])
                if post_digits:
                    suppl = f"{sup_word} {post_digits.group()}"
                else:
                    suppl = sup_word
        else:
            # Caso não haja número, busca apenas palavra(s) de suplemento
            sup_match = re.search(r'([a-zA-Z\.]+)', text)
            if sup_match:
                sup_word = sup_match.group(1).strip('.')
                post_digits = re.search(r'\d+', text[sup_match.end():])
                if post_digits:
                    suppl = f"{sup_word} {post_digits.group()}"
                else:
                    suppl = sup_word

        # Normaliza valor de suppl para None caso esteja vazio
        if suppl is not None:
            suppl = suppl.strip()
            if not suppl:
                suppl = None

        return number, suppl

    except Exception:
        # Em caso de erro inesperado, devolve None, None
        return None, None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate indent
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non‑negative integer")

    def _pretty_obj(obj, cur_indent, is_root=False):
        indent_str = " " * cur_indent
        # Simple atomic types
        if isinstance(obj, (str, bytes, int, float, bool, type(None))):
            result = f"{indent_str}{repr(obj)}"
        # Avoid recursive call to self.pretty (infinite loop)
        elif hasattr(obj, "pretty") and obj.__class__ is not type(self):
            try:
                result = obj.pretty(cur_indent, debug=debug)
            except Exception:
                result = f"{indent_str}{repr(obj)}"
        # Dictionaries
        elif isinstance(obj, dict):
            lines = [f"{indent_str}{{"]
            for k, v in obj.items():
                val_str = _pretty_obj(v, cur_indent + 4)
                lines.append(f"{indent_str}    {repr(k)}: {val_str.strip()}")
            lines.append(f"{indent_str}}}")
            result = "\n".join(lines)
        # Sequences and sets
        elif isinstance(obj, (list, tuple, set)):
            if isinstance(obj, list):
                open_sym, close_sym = "[", "]"
            elif isinstance(obj, tuple):
                open_sym, close_sym = "(", ")"
            else:
                open_sym, close_sym = "{", "}"
            lines = [f"{indent_str}{open_sym}"]
            for item in obj:
                lines.append(_pretty_obj(item, cur_indent + 4))
            lines.append(f"{indent_str}{close_sym}")
            result = "\n".join(lines)
        # Objects with attributes
        elif hasattr(obj, "__dict__"):
            cls_name = obj.__class__.__name__
            lines = [f"{indent_str}{cls_name}("]
            attrs = sorted(vars(obj).items())
            for k, v in attrs:
                val_str = _pretty_obj(v, cur_indent + 4)
                lines.append(f"{indent_str}    {k}={val_str.strip()}")
            lines.append(f"{indent_str})")
            result = "\n".join(lines)
        else:
            result = f"{indent_str}{repr(obj)}"

        # Add debug header for the top‑level call
        if is_root and debug:
            header = f"{indent_str}DEBUG: {obj.__class__.__name__} object id {hex(id(obj))}"
            return header + "\n" + result
        return result

    return _pretty_obj(self, indent, is_root=True)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    seen = set()

    def _pretty(obj, level):
        # Handle circular references
        obj_id = id(obj)
        if obj_id in seen:
            return '...'
        seen.add(obj_id)

        # Base cases: simple terminal types
        if isinstance(obj, (str, bytes)):
            return repr(obj)
        if isinstance(obj, (int, float, complex, bool, type(None))):
            return repr(obj)

        # Containers
        if isinstance(obj, (list, tuple, set)):
            if isinstance(obj, list):
                open_sym, close_sym = '[', ']'
            elif isinstance(obj, tuple):
                open_sym, close_sym = '(', ')'
            else:
                open_sym, close_sym = '{', '}'

            if not obj:
                return open_sym + close_sym

            inner = []
            for item in obj:
                inner.append(' ' * ((level + 1) * 4) + _pretty(item, level + 1) + ',')
            return '\n'.join([open_sym] + inner + [' ' * (level * 4) + close_sym])

        if isinstance(obj, dict):
            if not obj:
                return '{}'
            inner = []
            for k, v in obj.items():
                inner.append(' ' * ((level + 1) * 4) + f'{repr(k)}: {_pretty(v, level + 1)},')
            return '\n'.join(['{'] + inner + [' ' * (level * 4) + '}'])

        # Objects with __dict__
        if hasattr(obj, '__dict__'):
            # Class objects
            if isinstance(obj, type):
                name = obj.__name__
                bases = ', '.join(b.__name__ for b in obj.__bases__ if b is not object)
                header = f'class {name}({bases}):'
                inner = []
                for attr in sorted(obj.__dict__):
                    if attr.startswith('__') and attr.endswith('__'):
                        continue
                    try:
                        val = getattr(obj, attr)
                    except Exception:
                        val = '‹unavailable›'
                    inner.append(' ' * ((level + 1) * 4) + f'{attr} = {_pretty(val, level + 1)}')
                return '\n'.join([header] + inner)

            # Instance objects
            cls_name = obj.__class__.__name__
            header = f'{cls_name} (id:{obj_id})' if debug else cls_name
            inner = []
            try:
                attrs = obj.__dict__
            except Exception:
                attrs = {}
            for attr in sorted(attrs):
                try:
                    val = getattr(obj, attr)
                except Exception:
                    val = '‹unavailable›'
                inner.append(' ' * ((level + 1) * 4) + f'{attr} = {_pretty(val, level + 1)}')
            return '\n'.join([header] + inner)

        # Fallback to repr
        try:
            return repr(obj)
        except Exception:
            return '<unrepresentable>'

    return _pretty(self, indent)

def pretty(self, indent=0, debug=False):
        """Return a pretty formatted representation of self."""
        seen_ids = set()

        def _format(obj, level):
            """Recursively format obj with indentation."""
            # Avoid infinite recursion for self-referential objects
            try:
                obj_id = id(obj)
            except Exception:
                return repr(obj)
            if obj_id in seen_ids:
                return '...'
            seen_ids.add(obj_id)

            indent_str = ' ' * level
            # Handle basic immutable types directly
            if isinstance(obj, (str, bytes)):
                return repr(obj)
            if isinstance(obj, (int, float, complex, bool, type(None))):
                return repr(obj)

            # Handle dictionaries
            if isinstance(obj, dict):
                if not obj:
                    return '{}'
                items = []
                for k, v in obj.items():
                    key_repr = _format(k, level + 2)
                    val_repr = _format(v, level + 2)
                    items.append(f"{indent_str}  {key_repr}: {val_repr}")
                return "{\n" + "\n".join(items) + f"\n{indent_str}}}"

            # Handle sequences (list, tuple)
            if isinstance(obj, (list, tuple, set, frozenset)):
                if not obj:
                    opening = '[' if isinstance(obj, list) else '(' if isinstance(obj, tuple) else '{'
                    closing = ']' if isinstance(obj, list) else ')' if isinstance(obj, tuple) else '}'
                    return opening + closing
                opening = '[' if isinstance(obj, list) else '(' if isinstance(obj, tuple) else '{'
                closing = ']' if isinstance(obj, list) else ')' if isinstance(obj, tuple) else '}'
                items = []
                for item in obj:
                    items.append(f"{indent_str}  {_format(item, level + 2)}")
                return opening + "\n" + "\n".join(items) + f"\n{indent_str}{closing}"

            # Handle objects with __dict__ (custom classes)
            if hasattr(obj, "__dict__") and not isinstance(obj, (type,)):
                attrs = []
                for attr_name, attr_value in vars(obj).items():
                    val_repr = _format(attr_value, level + 2)
                    attrs.append(f"{indent_str}  {attr_name} = {val_repr}")
                classname = obj.__class__.__name__
                return f"{classname}(\n" + "\n".join(attrs) + f"\n{indent_str})"

            # Fallback for other objects
            try:
                return repr(obj)
            except Exception as e:
                return f"<unrepresentable object {e}>"

        try:
            result = _format(self, indent)
            if debug:
                # Include type information in debug mode
                return f"Type: {type(self).__module__}.{type(self).__qualname__}\n{result}"
            return result
        except Exception as exc:
            return f"<pretty failed: {exc}>"

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # We will maintain a working copy of the argument list and attempt to
    # collapse expressions according to the rules above.  If we cannot
    # determine the expression type or its structure we simply return the
    # original list unchanged.
    try:
        new_args = list(args)
        for i, expr in enumerate(new_args):
            # Skip if the expression is not an And or Or
            # (commonly represented with .is_And / .is_Or attributes).
            # If those attributes do not exist, silently continue.
            is_and = getattr(expr, "is_And", False)
            is_or = getattr(expr, "is_Or", False)
            if not (is_and or is_or):
                continue

            # Extract arguments of binary operators if possible.
            subexprs = getattr(expr, "args", None)
            if not subexprs or len(subexprs) != 2:
                # Skip non-binary construction – we don't handle arity >2
                continue

            a, b = subexprs

            # Helper functions for checking equality with the other subexpression.
            # We compare expressions directly as objects since they may be
            # instances of custom expression classes.
            def contains(expr_container, target):
                """Return True if target is among the args of expr_container."""
                try:
                    if not getattr(expr_container, "args", None):
                        return False
                    return target in expr_container.args
                except Exception:
                    return False

            # --- Absorption rules for & (AND) with | (OR) ---
            if is_and:
                # A & (A | B) -> A
                if getattr(a, "is_Or", False) and contains(a, b):
                    # a is Or(b, B)
                    new_args[i] = b
                    continue
                if getattr(b, "is_Or", False) and contains(b, a):
                    new_args[i] = a
                    continue

                # Negative absorption for AND:
                # A & (~A | B) -> A & B
                if getattr(a, "is_Or", False):
                    try:
                        first = a.args[0]
                        if getattr(first, "is_Not", False) and first.args[0] is b:
                            # a = Or(Not(b), B1)
                            B1 = a.args[1] if a.args[0] is b else a.args[0]
                            new_args[i] = getattr(type(a), "func", lambda *x: None)(b, B1)
                            continue
                    except Exception:
                        pass
                if getattr(b, "is_Or", False):
                    try:
                        first = b.args[0]
                        if getattr(first, "is_Not", False) and first.args[0] is a:
                            B1 = b.args[1] if b.args[0] is a else b.args[0]
                            new_args[i] = getattr(type(b), "func", lambda *x: None)(a, B1)
                            continue
                    except Exception:
                        pass

            # --- Absorption rules for | (OR) with & (AND) ---
            if is_or:
                # A | (A & B) -> A
                if getattr(a, "is_And", False) and contains(a, b):
                    new_args[i] = b
                    continue
                if getattr(b, "is_And", False) and contains(b, a):
                    new_args[i] = a
                    continue

                # Negative absorption for OR:
                # A | (~A & B) -> A | B
                if getattr(a, "is_And", False):
                    try:
                        first = a.args[0]
                        if getattr(first, "is_Not", False) and first.args[0] is b:
                            B1 = a.args[1] if a.args[0] is b else a.args[0]
                            new_args[i] = getattr(type(a), "func", lambda *x: None)(b, B1)
                            continue
                    except Exception:
                        pass
                if getattr(b, "is_And", False):
                    try:
                        first = b.args[0]
                        if getattr(first, "is_Not", False) and first.args[0] is a:
                            B1 = b.args[1] if b.args[0] is a else b.args[0]
                            new_args[i] = getattr(type(b), "func", lambda *x: None)(a, B1)
                            continue
                    except Exception:
                        pass

        # Remove duplicate expressions that might arise after absorption.
        # Preserve the original order of first occurrences.
        seen = set()
        result = []
        for expr in new_args:
            try:
                # expressions should be hashable; if not, use id
                key = expr
            except Exception:
                key = id(expr)
            if key not in seen:
                seen.add(key)
                result.append(expr)
        return result

    except Exception:
        # In case the structure of expressions is unknown or does not
        # fit the expected pattern, fall back to returning the input
        # unchanged to avoid silent failures.
        return list(args)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    Note: The expression representation used by the consumer of this method
    should be a nested tuple structure where the first element is the
    operator (a string) and the remaining elements are the operands.
    Supported operators are '&' (AND), '|' (OR) and '~' (NOT).
    Example:
        ('&', ('|', 'A', 'B'), 'A')  represents A & (A | B)
    """
    def is_equal(expr1, expr2):
        """Check structural equality of two expressions."""
        return expr1 == expr2

    def simplify(expr):
        """Recursively simplify an expression using absorption rules."""
        if not isinstance(expr, tuple):
            return expr

        op = expr[0]

        if op in ('&', '|'):
            left = simplify(expr[1])
            right = simplify(expr[2])

            # Identity: X & X = X, X | X = X
            if op == '&' and is_equal(left, right):
                return left
            if op == '|' and is_equal(left, right):
                return left

            # Absorption
            if op == '&':
                # X & (X | Y) = X
                if isinstance(right, tuple) and right[0] == '|':
                    if is_equal(left, right[1]) or is_equal(left, right[2]):
                        return left
                # (X | Y) & X = X
                if isinstance(left, tuple) and left[0] == '|':
                    if is_equal(right, left[1]) or is_equal(right, left[2]):
                        return right
                # Negative absorption: X & (~X | Y) = X & Y
                if isinstance(right, tuple) and right[0] == '|':
                    if isinstance(right[1], tuple) and right[1][0] == '~' and is_equal(left, simplify(right[1][1])):
                        return ('&', left, simplify(right[2]))
                if isinstance(left, tuple) and left[0] == '|':
                    if isinstance(left[1], tuple) and left[1][0] == '~' and is_equal(right, simplify(left[1][1])):
                        return ('&', simplify(left[2]), right)

            if op == '|':
                # X | (X & Y) = X
                if isinstance(right, tuple) and right[0] == '&':
                    if is_equal(left, right[1]) or is_equal(left, right[2]):
                        return left
                # (X & Y) | X = X
                if isinstance(left, tuple) and left[0] == '&':
                    if is_equal(right, left[1]) or is_equal(right, left[2]):
                        return right
                # Negative absorption: X | (~X & Y) = X | Y
                if isinstance(right, tuple) and right[0] == '&':
                    if isinstance(right[1], tuple) and right[1][0] == '~' and is_equal(left, simplify(right[1][1])):
                        return ('|', left, simplify(right[2]))
                if isinstance(left, tuple) and left[0] == '&':
                    if isinstance(left[1], tuple) and left[1][0] == '~' and is_equal(right, simplify(left[1][1])):
                        return ('|', simplify(left[2]), right)

            return (op, left, right)

        elif op == '~':
            return ('~', simplify(expr[1]))

        return expr  # Unknown operator, return as is

    return [simplify(expr) for expr in args]

def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        # Helper functions to handle different expression representations
        def op_name(expr):
            if isinstance(expr, tuple):
                return expr[0]
            if hasattr(expr, "func"):
                try:
                    return expr.func.__name__
                except AttributeError:
                    return str(expr.func)
            return None

        def op_args(expr):
            if isinstance(expr, tuple):
                return expr[1:]
            if hasattr(expr, "args"):
                return expr.args
            return [expr]

        def is_and(expr):  # A & B
            return op_name(expr) == "And"

        def is_or(expr):   # A | B
            return op_name(expr) == "Or"

        def is_not(expr, subexpr):
            if op_name(expr) != "Not":
                return False
            args = op_args(expr)
            return len(args) == 1 and args[0] == subexpr

        def make_and(a, b):
            """Return a symbolic representation of a & b."""
            try:
                return type(a)(a, b)
            except Exception:
                try:
                    return type(b)(a, b)
                except Exception:
                    return ("And", a, b)

        def make_or(a, b):
            """Return a symbolic representation of a | b."""
            try:
                return type(a)(a, b)
            except Exception:
                try:
                    return type(b)(a, b)
                except Exception:
                    return ("Or", a, b)

        # Main simplification loop
        exprs = list(args)
        changed = True
        while changed:
            changed = False
            new_exprs = []
            removed = [False] * len(exprs)
            for i, A in enumerate(exprs):
                if removed[i]:
                    continue
                absorbed = False
                for j, B in enumerate(exprs):
                    if j == i or removed[j]:
                        continue
                    # Absorption rules
                    if is_and(A) and is_or(B) and A in op_args(B):
                        removed[j] = True
                        absorbed = True
                        changed = True
                        break
                    if is_or(A) and is_and(B) and A in op_args(B):
                        removed[j] = True
                        absorbed = True
                        changed = True
                        break
                    # Negative absorption rules
                    if is_and(A) and is_or(B):
                        # Look for a negated instance of A inside B
                        complement_arg = None
                        other_arg = None
                        for arg in op_args(B):
                            if is_not(arg, A):
                                complement_arg = arg
                            else:
                                other_arg = arg
                        if complement_arg is not None and other_arg is not None:
                            # Replace A & (~A | other) with A & other
                            exprs[i] = make_and(A, other_arg)
                            absorbed = True
                            changed = True
                            break
                    if is_or(A) and is_and(B):
                        complement_arg = None
                        other_arg = None
                        for arg in op_args(B):
                            if is_not(arg, A):
                                complement_arg = arg
                            else:
                                other_arg = arg
                        if complement_arg is not None and other_arg is not None:
                            # Replace A | (~A & other) with A | other
                            exprs[i] = make_or(A, other_arg)
                            absorbed = True
                            changed = True
                            break
                if not absorbed:
                    new_exprs.append(exprs[i])
            exprs = new_exprs
        return exprs

