        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.
        """
        # Ensure the hook is provided
        if hook is None:
            raise ValueError("Hook must be specified.")

        # Initialize the registry if it does not exist
        if not hasattr(self, "_handlers"):
            self._handlers = {}

        # Store handlers per hook
        if hook not in self._handlers:
            self._handlers[hook] = []

        def _decorator(fn):
            if not callable(fn):
                raise TypeError(f"Listener {fn!r} is not callable.")
            self._handlers[hook].append(fn)
            return fn

        return _decorator

