    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate that the registry dictionary exists
    try:
        registry = self._registry
    except AttributeError:
        raise AttributeError("The instance does not have a '_registry' attribute.") from None

    # Basic type check if HookType is defined
    if 'HookType' in globals():
        if not isinstance(hook, globals()['HookType']):
            raise TypeError(f"Expected hook to be an instance of HookType, got {type(hook).__name__}")

    def decorator(func):
        if not callable(func):
            raise TypeError("The decorated object must be callable")

        try:
            # Register or overwrite the handler for the given hook
            registry[hook] = func
        except Exception as exc:
            # Handle any unforeseen errors during registration
            raise RuntimeError(f"Failed to register handler for hook {hook!r}") from exc

        return func

    return decorator

