    if style == "dot":
        return ".".join(str_pieces)
    elif style == "dash":
        return "-".join(str_pieces)
    elif style == "comma":
        return ",".join(str_pieces)
    elif style == "space":
        return " ".join(str_pieces)
    elif style == "json":
        # Simple JSON array representation without importing json
        return "[" + ",".join(map(repr, str_pieces)) + "]"
    else:
        raise ValueError(f"Unknown style: {style}")

def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : Iterable
        A sequence that may contain
        ``major``, ``minor``, ``patch``, ``prerelease`` and ``build`` parts
        in that order.  Each element can be ``None``, an integer, a string,
        a tuple/list (e.g. prerelease = ``('beta', 2)``) or any object that
        has a useful ``__str__`` representation.

    style : str
        The desired rendering style.  Supported styles are:

        ``"semver"``
            Render a semantic‑version string: ``major.minor.patch``
            optionally followed by ``-prerelease`` and/or ``+build``.
        ``"flat"``
            Concatenate all non‑empty parts in order with no separator.
        ``"numeric"``
            Join all parts that can be interpreted as integers with a dot
            (all other parts are omitted).

        The value must be one of the keys above; otherwise a ``ValueError``
        will be raised.

    Returns
    -------
    str
        The rendered string.

    Raises
    ------
    TypeError
        If ``pieces`` is not an iterable (excluding strings) or style is not
        a string.
    ValueError
        If the requested style is unknown.
    """
    if not hasattr(pieces, "__iter__") or isinstance(pieces, (str, bytes)):
        raise TypeError("pieces must be an iterable of version components")

    if not isinstance(style, str):
        raise TypeError("style must be a string")

    # Utility functions
    def _join_if_not_empty(parts, sep):
        return sep.join(str(p) for p in parts if p is not None and str(p))

    def _format_prerelease(pre):
        if pre is None:
            return ""
        if isinstance(pre, (list, tuple)):
            return _join_if_not_empty(pre, ".")
        return str(pre)

    def _format_build(build):
        if build is None:
            return ""
        if isinstance(build, (list, tuple)):
            return _join_if_not_empty(build, ".")
        return str(build)

    # Try to interpret pieces as [major, minor, patch, prerelease, build]
    try:
        major, minor, patch, prerelease, build = (pieces + [None] * 5)[:5]
    except Exception:
        # If pieces is not indexable, fall back to enumeration
        major = minor = patch = prerelease = build = None
        for idx, val in enumerate(pieces):
            if idx == 0:
                major = val
            elif idx == 1:
                minor = val
            elif idx == 2:
                patch = val
            elif idx == 3:
                prerelease = val
            elif idx == 4:
                build = val

    # Render according to style
    if style.lower() == "semver":
        core_parts = [major, minor, patch]
        core_str = _join_if_not_empty(core_parts, ".")
        pre_str = _format_prerelease(prerelease)
        build_str = _format_build(build)

        if pre_str and not pre_str.startswith("-"):
            pre_str = f"-{pre_str}"
        elif pre_str:
            pre_str = f"{pre_str}"

        if build_str and not build_str.startswith("+"):
            build_str = f"+{build_str}"
        elif build_str:
            build_str = f"{build_str}"

        return f"{core_str}{pre_str}{build_str}".strip()

    elif style.lower() == "flat":
        parts = [major, minor, patch, prerelease, build]
        return "".join(str(p) for p in parts if p is not None and str(p))

    elif style.lower() == "numeric":
        numeric_parts = []
        for part in [major, minor, patch, prerelease, build]:
            try:
                numeric_parts.append(int(part))
            except Exception:
                pass
        return ".".join(str(p) for p in numeric_parts)

    else:
        raise ValueError(f"Unknown style '{style}'. Supported styles are 'semver', 'flat', and 'numeric'.")

