def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Validate parameters
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple")

    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple")

    # Combine command and arguments
    full_cmd = cmd_list + list(args)

    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string path or None")

    # Merge environment variables if provided
    merged_env = os.environ.copy()
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a dictionary of environment variables")
        merged_env.update(env)

    # Verbose logging
    if verbose:
        print(f"Executing: {' '.join(full_cmd)}")

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=merged_env,
            capture_output=True,
            text=True,
            check=True
        )
        if verbose:
            if result.stdout:
                print(result.stdout, end="")
            if not hide_stderr and result.stderr:
                print(result.stderr, end="")
        return result
    except subprocess.CalledProcessError as e:
        # Provide output for debugging if verbose
        if verbose:
            if e.stdout:
                print("STDOUT:", e.stdout, end="")
            if not hide_stderr and e.stderr:
                print("STDERR:", e.stderr, end="")
        # Re-raise to allow caller to handle the error
        raise

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Import inside the function to avoid top-level import statements
    import subprocess
    import shlex
    import sys

    try:
        # Validate and prepare the command list
        if commands is None:
            raise ValueError("commands cannot be None")
        if isinstance(commands, str):
            cmd = [commands]
        else:
            try:
                cmd = list(commands)
            except TypeError:
                raise ValueError("commands must be a string or an iterable of arguments")
        if args is not None:
            if not isinstance(args, (list, tuple)):
                raise ValueError("args must be a list or tuple")
            cmd += list(args)

        # Set environment variables if provided
        env_vars = env if env is not None else None

        # Verbose output
        if verbose:
            print("Running command:", " ".join(shlex.quote(c) for c in cmd))

        # Execute the command
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_vars,
            text=True,
            capture_output=not hide_stderr,
            check=True,
        )

        # Handle stderr visibility
        if not hide_stderr and result.stderr:
            print(result.stderr, file=sys.stderr, end="")

        return result.stdout

    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {commands}") from e
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Command '{commands}' returned non-zero exit status {e.returncode}. "
            f"Stderr: {e.stderr}"
        ) from e
    except Exception as e:
        raise RuntimeError(f"Error running command '{commands}': {e}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, shlex, sys
    # Build the command list
    if isinstance(commands, str):
        cmd_parts = shlex.split(commands)
    elif isinstance(commands, list):
        cmd_parts = list(commands)
    else:
        raise TypeError(f"commands must be a string or a list, got {type(commands)}")
    if args:
        if not isinstance(args, list):
            raise TypeError(f"args must be a list of strings, got {type(args)}")
        cmd_parts.extend(args)

    # Prepare subprocess arguments
    run_kwargs = {
        "cwd": cwd,
        "env": env,
        "capture_output": True,
        "text": True,
        "check": False,
    }
    if hide_stderr:
        run_kwargs["stderr"] = subprocess.DEVNULL

    if verbose:
        print(f"Running command: {' '.join(cmd_parts)}", file=sys.stderr)
        if cwd:
            print(f"Working directory: {cwd}", file=sys.stderr)
        if env:
            print(f"Environment: {env}", file=sys.stderr)

    try:
        result = subprocess.run(cmd_parts, **run_kwargs)
        if verbose:
            print(f"Return code: {result.returncode}", file=sys.stderr)
            if result.stdout:
                print(f"stdout:\n{result.stdout}", file=sys.stderr)
            if result.stderr and not hide_stderr:
                print(f"stderr:\n{result.stderr}", file=sys.stderr)
        return result
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd_parts[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run command {' '.join(cmd_parts)}: {e}") from e

