def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    # Ensure a registry exists
    if "_VCS_HANDLERS" not in globals():
        globals()["_VCS_HANDLERS"] = {}
    registry = globals()["_VCS_HANDLERS"]
    # Validate inputs
    try:
        if not isinstance(vcs, str):
            raise TypeError("vcs must be a string")
        if not callable(method):
            raise TypeError("method must be a callable")
        # Register the handler
        registry[vcs] = method
        return method
    except Exception as exc:
        raise RuntimeError(f"Failed to register VCS handler for '{vcs}': {exc}") from exc

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError(f"vcs must be a string, got {type(vcs).__name__}")
    if method is None:
        def decorator(func):
            if not callable(func):
                raise TypeError("decorated object must be callable")
            setattr(func, "_vcs_handler", vcs)
            return func
        return decorator
    if not callable(method):
        raise TypeError("method must be callable")
    setattr(method, "_vcs_handler", vcs)
    return method

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS."""
    # Validate the VCS identifier.
    if not isinstance(vcs, str) or not vcs:
        raise ValueError("vcs must be a non-empty string")

    def _register(func):
        """Inner decorator that attaches the VCS identifier to the method."""
        if not callable(func):
            raise TypeError("Provided handler is not callable")
        # Attach an attribute that records the VCS for later discovery.
        setattr(func, "_vcs_handler", vcs)
        return func

    # Support both @register_vcs_handler('git') and
    # @register_vcs_handler('git', handler_func) invocation styles.
    if method is None:
        return _register
    else:
        return _register(method)

def register_vcs_handler(vcs, method):
    """Register a method as the handler for a given VCS.

    This decorator stores the association in a global registry so that
    other parts of the program can retrieve the appropriate handler by VCS
    name.  It performs basic validation and returns the method unchanged.
    """
    # Basic validation
    if not isinstance(vcs, str) or not vcs.strip():
        raise ValueError("VCS name must be a non-empty string")
    if not callable(method):
        raise TypeError("Provided handler must be callable")

    # Register the handler in a global dictionary
    global _vcs_handlers
    try:
        _vcs_handlers  # ensure it exists
    except NameError:
        _vcs_handlers = {}
    _vcs_handlers[vcs] = method

    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
        Validate storage root hierarchy.

        The method traverses the storage hierarchy stored in `self.storage_root`
        (expected to be a mapping of identifiers to objects).  For each object the
        following checks are optionally performed:

        * If ``validate_objects`` is True, the object is expected to have a
          ``validate()`` method that returns ``True`` when the object is
          internally consistent, and raises an exception otherwise.
        * If ``check_digests`` is True, the object should expose a ``digest``
          attribute and a ``compute_digest()`` method.  The stored digest is
          compared with the freshly computed one.

        Any warning about a failed check is emitted via the :mod:`warnings` module
        if ``show_warnings`` is True; otherwise the warning is silently suppressed.

        Returns:
            tuple[int, int]: ``num_objects`` – the total number of objects
            inspected; ``good_objects`` – the number of objects that passed
            all requested checks.
        """
        import warnings

        # Ensure we have a crawlable structure; fall back to empty mapping if not.
        objects = getattr(self, "storage_root", {})
        if objects is None:
            objects = {}

        num_objects = 0
        good_objects = 0

        for key, obj in objects.items():
            num_objects += 1
            ok = True

            # Object-level validation
            if validate_objects:
                try:
                    # Prefer a validate() method; otherwise skip
                    if hasattr(obj, "validate"):
                        ok = ok and bool(obj.validate())
                except Exception as exc:
                    ok = False
                    if show_warnings:
                        warnings.warn(f"Validation failed for object {key}: {exc}")

            # Digest comparison
            if check_digests and ok:
                try:
                    if hasattr(obj, "digest") and hasattr(obj, "compute_digest"):
                        expected = getattr(obj, "digest")
                        actual = obj.compute_digest()
                        if expected != actual:
                            ok = False
                            if show_warnings:
                                warnings.warn(
                                    f"Digest mismatch for object {key}: "
                                    f"expected {expected}, got {actual}"
                                )
                except Exception as exc:
                    ok = False
                    if show_warnings:
                        warnings.warn(f"Digest check failed for object {key}: {exc}")

            if ok:
                good_objects += 1

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Determine the root path; assume the instance holds it in `_root_path`
    root = getattr(self, "_root_path", None)
    if not root or not hasattr(os, "path") or not os.path.isdir(root):
        raise RuntimeError("Storage root is not set or is not a valid directory.")
    num_objects = 0
    good_objects = 0
    # Walk the directory tree, skipping dot directories and files
    for dirpath, dirnames, filenames in os.walk(root):
        # Filter out hidden directories
        dirnames[:] = [d for d in dirnames if not d.startswith(".")]
        for name in filenames:
            if name.startswith("."):
                continue
            full_path = os.path.join(dirpath, name)
            num_objects += 1
            obj_ok = True
            # Validate the object itself
            if validate_objects:
                try:
                    st = os.stat(full_path)
                    if st.st_size == 0:
                        obj_ok = False
                        if show_warnings:
                            warnings.warn(f"Empty object detected: {full_path}")
                except OSError as e:
                    obj_ok = False
                    if show_warnings:
                        warnings.warn(f"Cannot access object {full_path}: {e}")
            # Validate digest if requested
            if check_digests and obj_ok:
                digest_path = full_path + ".digest"
                if os.path.exists(digest_path):
                    try:
                        with open(digest_path, "r") as df:
                            expected_digest = df.read().strip()
                        # Compute actual digest
                        import hashlib
                        hasher = hashlib.sha256()
                        with open(full_path, "rb") as f:
                            for chunk in iter(lambda: f.read(8192), b""):
                                hasher.update(chunk)
                        actual_digest = hasher.hexdigest()
                        if actual_digest != expected_digest:
                            obj_ok = False
                            if show_warnings:
                                warnings.warn(f"Digest mismatch for {full_path}")
                    except Exception as e:
                        obj_ok = False
                        if show_warnings:
                            warnings.warn(f"Error validating digest for {full_path}: {e}")
            if obj_ok:
                good_objects += 1
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        # Ensure there is something to validate
        try:
            objects_iter = iter(self.objects)
        except AttributeError:
            raise AttributeError("The object does not have an 'objects' attribute to validate.")

        num_objects = 0
        good_objects = 0

        for obj in objects_iter:
            num_objects += 1
            is_valid = True

            # Object-level validation
            if validate_objects:
                try:
                    if hasattr(obj, 'validate') and callable(obj.validate):
                        obj.validate()
                    elif hasattr(obj, '__dict__'):
                        # Simple check: no attribute should be None
                        for key, value in obj.__dict__.items():
                            if value is None:
                                raise ValueError(f"Attribute '{key}' of {obj} is None")
                    # else: nothing specific to validate
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"[Validation Warning] {obj!r}: {exc}")

            # Digest validation
            if is_valid and check_digests:
                try:
                    # If the object has digest and data attributes, validate them
                    if hasattr(obj, 'digest') and hasattr(obj, 'data'):
                        # Compute digest of data assuming bytes
                        if isinstance(obj.data, bytes):
                            import hashlib
                            computed = hashlib.sha256(obj.data).hexdigest()
                        else:
                            # Try to convert to bytes if possible
                            computed = hashlib.sha256(str(obj.data).encode()).hexdigest()
                        if computed != obj.digest:
                            raise ValueError("Digest mismatch")
                    # else: no digest to check
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"[Digest Warning] {obj!r}: {exc}")

            if is_valid:
                good_objects += 1

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
