    try:
        import os
        import hashlib
    except Exception as import_err:
        raise RuntimeError(f"Required modules not available: {import_err}")

    for dirpath, dirnames, filenames in os.walk(root, topdown=True):
        # Skip hidden directories if desired; adjust as needed.
        for filename in filenames:
            file_path = os.path.join(dirpath, filename)

            # Skip digest files from counting as objects.
            if check_digests and filename.endswith(('.sha256', '.md5', '.sha1', '.sha512')):
                continue

            num_objects += 1
            is_good = True

            # Validate object existence and basic integrity
            if validate_objects:
                try:
                    with open(file_path, "rb") as f:
                        data = f.read()
                    if len(data) == 0:
                        warnings.append(f"Object '{file_path}' is empty.")
                        is_good = False
                except Exception as exc:
                    warnings.append(f"Cannot read object '{file_path}': {exc}")
                    is_good = False

            # Validate digests if requested (supports SHA-256 by default)
            if is_good and check_digests:
                digest_name = f"{file_path}.sha256"
                if os.path.exists(digest_name):
                    try:
                        with open(digest_name, "r") as df:
                            expected_digest = df.read().strip()
                        # Compute SHA256 of the object
                        sha256 = hashlib.sha256()
                        with open(file_path, "rb") as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                sha256.update(chunk)
                        actual_digest = sha256.hexdigest()
                        if actual_digest != expected_digest:
                            warnings.append(
                                f"Digest mismatch for '{file_path}'. "
                                f"Expected: {expected_digest}, Actual: {actual_digest}"
                            )
                            is_good = False
                    except Exception as exc:
                        warnings.append(f"Failed to verify digest for '{file_path}': {exc}")
                        is_good = False

            if is_good:
                good_objects += 1

    if show_warnings and warnings:
        # Print warnings to stderr to avoid polluting stdout
        import sys
        for w in warnings:
            print(w, file=sys.stderr)

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
