                            is_valid = False
                            if show_warnings:
                                print(f"Digest mismatch for object {obj}. Expected {expected_digest}, got {actual_digest}.")
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Error checking digest for object {obj}: {exc}")

            if is_valid:
                good_objects += 1

    except Exception as err:
        if show_warnings:
            print(f"Validation encountered an error: {err}")

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    version_str = version.strip()
    if not version_str:
        raise ValueError("version string cannot be empty")
    if not version_str.isdigit():
        raise ValueError(f"invalid version format: {version!r}")
    try:
        current = int(version_str)
    except ValueError as exc:
        raise ValueError(f"cannot parse integer from version {version!r}") from exc
    next_val = current + 1
    # Preserve the original width with leading zeros
    new_version = str(next_val).zfill(len(version_str))
    return new_version

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    :param version_dirs: List of version directory names in ascending order.
    :return: Dictionary mapping content paths to lists of mismatches.
    :raises FileNotFoundError: If an expected inventory file is missing.
    :raises ValueError: If inputs are malformed.
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Validate the input list
    if not isinstance(version_dirs, list):
        raise TypeError("version_dirs must be a list of directory names")

    # Ensure we have a root inventory for comparison
    root_inventory = getattr(self, "root_inventory", {})
    if not isinstance(root_inventory, dict):
        raise ValueError("root_inventory attribute must be a dict")

    # Store mismatched digests
    mismatches = {}

    # Helper to load an inventory file
    def _load_inventory(dir_path):
        # Try YAML first, then JSON
        for suffix in (".yaml", ".yml", ".json"):
            inv_file = os.path.join(dir_path, "inventory" + suffix)
            if os.path.isfile(inv_file):
                try:
                    with open(inv_file, "r", encoding="utf-8") as f:
                        if suffix in (".yaml", ".yml"):
                            if yaml is None:
                                raise RuntimeError("PyYAML is not available")
                            data = yaml.safe_load(f)
                        else:
                            data = json.load(f)
                    if not isinstance(data, dict):
                        raise ValueError(f"Inventory file {inv_file} must contain a mapping")
                    return data
                except Exception as exc:
                    raise RuntimeError(f"Failed to read inventory {inv_file}: {exc}")
        raise FileNotFoundError(f"Missing inventory file for directory {dir_path}")

    # Process each version directory
    for v_dir in version_dirs:
        if not v_dir:
            continue
        try:
            inventory = _load_inventory(v_dir)
        except Exception as exc:
            raise FileNotFoundError(f"Error loading inventory for {v_dir}: {exc}")

        # Compare each digest with the root inventory
        for path, entry in inventory.items():
            # The entry can be a dict containing 'digest' key or a raw digest string
            digest = entry.get("digest") if isinstance(entry, dict) else entry
            if not digest:
                continue
            root_digest = root_inventory.get(path)
            if root_digest is not None and root_digest != digest:
                mismatches.setdefault(path, []).append(
                    {
                        "version": v_dir,
                        "inventory_digest": digest,
                        "root_digest": root_digest,
                    }
                )

    # Store mismatches for later use and return them
    self.inventory_differences = mismatches
    return mismatches

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).

    Returns a dict mapping content paths to a list of tuples (version_dir, inventory_digest)
    for entries whose digest differs from the root inventory.
    """
    import os, json
    from json import JSONDecodeError

    # Helper to load an inventory file and normalise it to a dict of path -> digest
    def _load_inventory(path):
        try:
            with open(path, 'rt', encoding='utf-8') as f:
                data = json.load(f)
                if isinstance(data, list):
                    # Expect list of dicts with 'path' and 'digest' keys
                    return {item['path']: item['digest'] for item in data if 'path' in item and 'digest' in item}
                if isinstance(data, dict):
                    return data
                return {}
        except (FileNotFoundError, PermissionError):
            return {}
        except JSONDecodeError:
            # If the file isn't valid JSON, try parsing as a simple text format: one entry per line
            try:
                with open(path, 'rt', encoding='utf-8') as f:
                    data = {}
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        parts = line.split(None, 1)
                        if len(parts) == 2:
                            data[parts[0]] = parts[1]
                    return data
            except Exception:
                return {}
        except Exception:
            return {}

    inventory_file = getattr(self, 'inventory_file', 'inventory.json')
    # Load root inventory once, if not already cached
    root_inventory = getattr(self, 'root_inventory', None)
    if root_inventory is None:
        root_path = os.path.join(self.root_dir, inventory_file)
        root_inventory = _load_inventory(root_path)
        self.root_inventory = root_inventory

    cumulative_expected = set()
    differing = {}

    # Helper to record messages (ties in to a diagnostics list if available)
    def _record(msg):
        if hasattr(self, 'messages'):
            self.messages.append(msg)
        else:
            # Fallback to printing if diagnostics list isn't present
            print(msg)

    for idx, v_dir in enumerate(version_dirs, start=1):
        inv_path = os.path.join(self.root_dir, v_dir, inventory_file)
        inventory = _load_inventory(inv_path)

        if not inventory:
            _record(f"Inventory for version directory '{v_dir}' is missing or empty.")
            continue

        current_keys = set(inventory.keys())

        # Each subsequent inventory should contain all previously seen items.
        if not cumulative_expected.issubset(current_keys):
            missing = cumulative_expected - current_keys
            _record(f"Inventory for version '{v_dir}' is missing entries from earlier versions: {sorted(missing)}.")

        # Update the cumulative set for the next iteration
        cumulative_expected = current_keys

        # Compare digests against the root inventory and record differences
        for path, digest in inventory.items():
            root_digest = root_inventory.get(path)
            if root_digest is not None and root_digest != digest:
                differing.setdefault(path, []).append((v_dir, digest))

    self.different_digests = differing
    return differing

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Use dynamic imports to avoid top‑level import statements
    try:
        os = __import__('os')
        re = __import__('re')
    except Exception
    def _error(msg):
        return f'error: {msg}'
    # Validate input type
    if not isinstance(path, str):
        return _error('input is not a string')
    try:
        abs_path = os.path.abspath(os.path.expanduser(path))
    except Exception as e:
        return _error(f'cannot resolve path: {e}')
    if not os.path.exists(abs_path):
        return _error('path does not exist')
    # Check if path is a directory
    if os.path.isdir(abs_path):
        # Root: presence of .ocfl_root file
        if os.path.isfile(os.path.join(abs_path, '.ocfl_root')):
            return 'root'
        # Object: look for subdirectory matching "0=*"
        try:
            for entry in os.listdir(abs_path):
                full = os.path.join(abs_path, entry)
                if os.path.isdir(full) and re.match(r'^[0-9]+=.*$', entry):
                    return 'object'
        except Exception:
            # If listing fails due to permissions, consider as error
            return _error('cannot read directory entries')
        return _error('directory is neither root nor object')
    # Path is a file
    if os.path.isfile(abs_path):
        base = os.path.basename(abs_path)
        if re.match(r'^[0-9]+=.*$', base):
            return 'file'
        return _error('file does not match namaste pattern')
    return _error('unknown path type')

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
        import re
    except Exception as exc:
        return f"error: unable to import required modules ({exc})"

    if path is None:
        return "error: path is None"

    # Resolve string representation
    try:
        path_str = os.fspath(path)
    except Exception as exc:
        return f"error: path cannot be converted to a filesystem path ({exc})"

    if not os.path.exists(path_str):
        return f"error: path does not exist ({path_str})"

    # Handle files directly
    if os.path.isfile(path_str):
        return "file"

    # Handle directories: look for Namaste files starting with "0="
    if os.path.isdir(path_str):
        try:
            names = os.listdir(path_str)
        except PermissionError as e:
            return f"error: cannot list directory contents ({e})"
        except OSError as e:
            return f"error: failed to access directory ({e})"

        # Find Namaste files that match the pattern 0=*
        namaste_files = []
        for name in names:
            if name.startswith("0="):
                namaste_files.append(name)

        if not namaste_files:
            return "error: directory does not contain a Namaste file (0=*)"

        # If multiple Namaste files, this is ambiguous: report the first as error
        if len(namaste_files) > 1:
            return (
                f"error: multiple Namaste files found ({', '.join(namaste_files)})"
            )

        # We have exactly one Namaste file: interpret its suffix
        namaste_name = namaste_files[0]
        match = re.fullmatch(r"0=(.+)", namaste_name)
        if not match:
            # This should not happen as we checked the prefix
            return f"error: Namaste file name does not conform to pattern ('{namaste_name}')"

        suffix = match.group(1).lower()

        if suffix == "root":
            return "root"
        elif suffix == "object":
            return "object"
        else:
            # fallback: try to guess based on common OCFL patterns
            # e.g., if suffix contains 'manifest' treat as object
            if "manifest" in suffix or "inventory" in suffix:
                return "object"
            else:
                return f"unknown Namaste type '{suffix}'"

    # If path is neither file nor directory (unlikely), return error
    return f"error: path is neither file nor directory ({path_str})"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")
    if bug_ids is None:
        return params
    # Convert bug_ids to a list of IDs
    if isinstance(bug_ids, int):
        bug_id_list = [bug_ids]
    else:
        try:
            bug_id_list = list(bug_ids)
        except Exception as exc:
            raise ValueError("bug_ids must be an iterable of IDs") from exc
    if not bug_id_list:
        return params
    # Merge with existing 'ids' key if present
    existing_ids = params.get('ids')
    if existing_ids:
        # Ensure existing_ids is iterable; if it's a single int, wrap it
        if isinstance(existing_ids, int):
            existing_ids = [existing_ids]
        try:
            existing_set = set(existing_ids)
        except Exception:
            existing_set = set()
        combined_set = existing_set.union(bug_id_list)
        params['ids'] = sorted(combined_set)
    else:
        params['ids'] = bug_id_list
    return params

def deep_merge_nodes(nodes):
    '''
    Merge a list of (key_node, value_node) pairs deep by mapping nodes. If duplicate keys
    appear, merge their MappingNode values if both are mapping nodes; otherwise
    the later value wins.
    '''
    merged = {}  # key_value_str -> (key_node, value_node)

    for key_node, value_node in nodes:
        try:
            key = key_node.value
        except AttributeError:
            # Skip malformed key
            continue

        if key in merged:
            existing_key_node, existing_value_node = merged[key]
            # If both values are MappingNode, deep merge; else replace with the later node.
            if isinstance(existing_value_node, MappingNode) and isinstance(value_node, MappingNode):
                # Merge the mapping node pairs
                merged_pairs = deep_merge_nodes(existing_value_node.value + value_node.value)
                merged_mapping_node = MappingNode(
                    tag=existing_value_node.tag,
                    value=merged_pairs
                )
                merged[key] = (existing_key_node, merged_mapping_node)
            else:
                # Last value wins
                merged[key] = (existing_key_node, value_node)
        else:
            merged[key] = (key_node, value_node)

    return list(merged.values())

def deep_merge_nodes(nodes):
    """
    Merge a list of ruamel.yaml node tuples by deep-merging values with duplicate keys.
    """
    # Validate input
    if not isinstance(nodes, list):
        raise TypeError("nodes must be a list")
    # Helper to identify a mapping node
    def is_mapping_node(node):
        return getattr(node, "tag", None) == "tag:yaml.org,2002:map" and hasattr(node, "value") and isinstance(node.value, list)
    # Merge two node values
    def merge_values(a, b):
        if is_mapping_node(a) and is_mapping_node(b):
            return merge_mapping_nodes(a, b)
        else:
            return b
    # Merge two mapping nodes into a new mapping node
    def merge_mapping_nodes(m1, m2):
        merged_pairs = []
        key_index = {}
        # Add entries from the first mapping
        for key1, val1 in m1.value:
            key_val = key1.value
            key_index[key_val] = len(merged_pairs)
            merged_pairs.append((key1, val1))
        # Merge or add entries from the second mapping
        for key2, val2 in m2.value:
            key_val = key2.value
            if key_val in key_index:
                idx = key_index[key_val]
                existing_key, existing_val = merged_pairs[idx]
                merged_val = merge_values(existing_val, val2)
                merged_pairs[idx] = (existing_key, merged_val)
            else:
                key_index[key_val] = len(merged_pairs)
                merged_pairs.append((key2, val2))
        # Construct a new MappingNode instance with the same type and tag
        return type(m1)(m1.tag, merged_pairs)
    # Main merging logic
    merged = []
    key_to_index = {}
    for entry in nodes:
        if not (isinstance(entry, tuple) and len(entry) == 2):
            raise TypeError("Each entry must be a tuple of (ScalarNode, value_node)")
        key_node, val_node = entry
        if not hasattr(key_node, "value"):
            raise TypeError("Key node must be a ScalarNode with a 'value' attribute")
        key_val = key_node.value
        if key_val in key_to_index:
            idx = key_to_index[key_val]
            existing_key, existing_val = merged[idx]
            merged_val = merge_values(existing_val, val_node)
            merged[idx] = (existing_key, merged_val)
        else:
            key_to_index[key_val] = len(merged)
            merged.append((key_node, val_node))
    return merged

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:
        (ScalarNode as a key, MappingNode or other Node as a value),
    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper: recursively merge MappingNodes or return the latter node
    def _merge_values(left, right):
        try:
            if getattr(left, 'tag', None) == 'tag:yaml.org,2002:map' and getattr(right, 'tag', None) == 'tag:yaml.org,2002:map':
                return _merge_map_nodes(left, right)
        except Exception:
            pass
        return right

    # Helper: merge two MappingNodes
    def _merge_map_nodes(a, b):
        # Build a dict of key -> (key_node, value_node) for the merged result
        merged_dict = {}
        # Preserve order: first from 'a' then from 'b'
        order = []

        # Process first mapping
        for k_node, v_node in a.value:
            key = k_node.value
            merged_dict[key] = (k_node, v_node)
            order.append(key)

        # Process second mapping
        for k_node, v_node in b.value:
            key = k_node.value
            if key in merged_dict:
                existing_k, existing_v = merged_dict[key]
                merged_v = _merge_values(existing_v, v_node)
                merged_dict[key] = (existing_k, merged_v)
            else:
                merged_dict[key] = (k_node, v_node)
                order.append(key)

        # Assemble the merged pair list in the achieved order
        merged_pairs = []
        for key in order:
            k_node, v_node = merged_dict[key]
            merged_pairs.append((k_node, v_node))

        # Construct a new MappingNode of the same type as 'a'
        try:
            new_node = type(a)(a.tag, merged_pairs)
        except Exception:
            # Fallback: try using 'b' if 'a' failed
            new_node = type(b)(b.tag, merged_pairs)
        return new_node

    # Main merging logic over the provided nodes list
    merged_nodes = []
    key_index = {}

    for key_node, value_node in nodes:
        try:
            key_val = key_node.value
        except Exception:
            # If the key_node doesn't have a 'value' attribute, skip it
            continue

        if key_val in key_index:
            idx = key_index[key_val]
            existing_key_node, existing_value_node = merged_nodes[idx]
            merged_value = _merge_values(existing_value_node, value_node)
            merged_nodes[idx] = (existing_key_node, merged_value)
        else:
            key_index[key_val] = len(merged_nodes)
            merged_nodes.append((key_node, value_node))

    return merged_nodes

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    import ruamel.yaml.nodes as _nodes

    def _merge_mapping_lists(a_list, b_list):
        merged = []
        key_index = {}
        for key_node, val_node in a_list:
            try:
                k = key_node.value
            except Exception:
                k = str(key_node)
            merged.append((key_node, val_node))
            key_index[k] = len(merged) - 1
        for key_node, val_node in b_list:
            try:
                k = key_node.value
            except Exception:
                k = str(key_node)
            if k in key_index:
                idx = key_index[k]
                existing_val = merged[idx][1]
                if isinstance(existing_val, _nodes.MappingNode) and isinstance(val_node, _nodes.MappingNode):
                    new_val = _merge_mapping_nodes(existing_val, val_node)
                else:
                    new_val = val_node
                merged[idx] = (key_node, new_val)
            else:
                merged.append((key_node, val_node))
                key_index[k] = len(merged) - 1
        return merged

    def _merge_mapping_nodes(a, b):
        if not isinstance(a, _nodes.MappingNode) or not isinstance(b, _nodes.MappingNode):
            return b
        new_val = _merge_mapping_lists(a.value, b.value)
        return _nodes.MappingNode(tag=a.tag, value=new_val)

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of tuples')
    result = []
    key_pos = {}
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('each element of nodes must be a 2-tuple')
        key_node, val_node = item
        try:
            key = key_node.value
        except Exception:
            key = str(key_node)
        if key in key_pos:
            idx = key_pos[key]
            existing_key, existing_val = result[idx]
            if isinstance(existing_val, _nodes.MappingNode) and isinstance(val_node, _nodes.MappingNode):
                merged_val = _merge_mapping_nodes(existing_val, val_node)
            else:
                merged_val = val_node
            result[idx] = (existing_key, merged_val)
        else:
            result.append((key_node, val_node))
            key_pos[key] = len(result) - 1
    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate input
    if parser is None:
        raise ValueError("parser cannot be None")
    try:
        actions = getattr(parser, "_actions", None)
        if actions is None:
            raise TypeError("Provided object does not appear to be an ArgumentParser")
    except Exception as exc:
        raise TypeError("Provided object does not appear to be an ArgumentParser") from exc

    flags = []
    for action in actions:
        # Some actions (like epilog or description actions) might not have option_strings
        opt_strings = getattr(action, "option_strings", None)
        if opt_strings:
            for opt in opt_strings:
                if opt:  # filter out empty strings
                    flags.append(opt)

    # Preserve order and remove duplicates
    seen = set()
    unique_flags = []
    for f in flags:
        if f not in seen:
            seen.add(f)
            unique_flags.append(f)

    return " ".join(unique_flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate input
    if not hasattr(parser, '_actions'):
        raise TypeError('Expected an argparse.ArgumentParser instance')
    try:
        actions = parser._actions
    except Exception as exc:
        raise TypeError('Failed to access parser actions: {}'.format(exc)) from exc
    flags = []
    for action in actions:
        # Some actions may not have option_strings
        option_strings = getattr(action, 'option_strings', ())
        if option_strings:
            flags.extend(option_strings)
    return ' '.join(flags)

def parser_flags(parser):
