def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Attempt to collect option strings from the parser's actions.
    try:
        # The public API does not expose a convenient method for retrieving flags,
        # so we inspect the protected `_actions` attribute.
        actions = getattr(parser, '_actions', [])
        flags = []
        for action in actions:
            option_strings = getattr(action, 'option_strings', [])
            if option_strings:
                flags.extend(option_strings)
        return ' '.join(flags)
    except Exception:
        # If the parser is invalid or any unexpected error occurs,
        # fall back to returning an empty string rather than raising.
        return ''

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        return ''
    try:
        flags = []
        for action in getattr(parser, '_actions', []):
            if hasattr(action, 'option_strings'):
                opts = action.option_strings
                if opts:
                    flags.extend(opts)
        return ' '.join(flags)
    except Exception:
        return ''

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments
    and return them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    # Create the top‑level parser and a subparsers group.
    parser = argparse.ArgumentParser(add_help=False)
    subparsers = parser.add_subparsers(dest='subparser_name', required=False)

    # Parse the arguments, keeping any unrecognized tokens.
    try:
        namespace, remaining_args = parser.parse_known_args(unparsed_arguments)
    except Exception as exc:
        raise ValueError(f"Error while parsing arguments: {exc}") from exc

    # Determine the key for the result dictionary
    key = getattr(namespace, 'subparser_name', None)
    if not key:
        key = "global"

    # If a subparser was selected and there are remaining arguments,
    # attempt to parse them with that subparser's own parser.
    if key != "global" and remaining_args:
        # Find the corresponding subparser parser object
        subparser_obj = None
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                subparser_obj = action.choices.get(key)
                break
        if subparser_obj:
            try:
                sub_namespace, sub_remaining = subparser_obj.parse_known_args(remaining_args)
                # Attach the subparser name for reference
                sub_namespace.subparser_name = key
                return {key: sub_namespace}
            except Exception as exc:
                raise ValueError(f"Error while parsing sub‑parser arguments for '{key}': {exc}") from exc

    # No subparser matched or no remaining args – return the top‑level namespace
    return {key: namespace}

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked,
    parse the arguments and return them as a dict mapping from subparser name
    (or "global") to an argparse.Namespace instance.
    """
    import argparse

    def _parse_key_value(args, start_idx=0):
        """Parse a list of args into a dict until a non-key argument is found."""
        result = {}
        i = start_idx
        while i < len(args):
            token = args[i]
            if token.startswith('--') or token.startswith('-'):
                # Handle key
                key = token.lstrip('-')
                # Split on '=' if present
                if '=' in key:
                    part_key, part_val = key.split('=', 1)
                    try:
                        value = int(part_val)
                    except ValueError:
                        try:
                            value = float(part_val)
                        except ValueError:
                            value = part_val
                    result[part_key] = value
                    i += 1
                else:
                    # Determine value
                    if i + 1 < len(args) and not args[i + 1].startswith('-'):
                        val_token = args[i + 1]
                        try:
                            val = int(val_token)
                        except ValueError:
                            try:
                                val = float(val_token)
                            except ValueError:
                                val = val_token
                        result[key] = val
                        i += 2
                    else:
                        # Boolean flag
                        result[key] = True
                        i += 1
            else:
                # Non-key argument encountered; stop parsing
                break
        return result, i

    try:
        args_list = list(unparsed_arguments)
        subparser_name = None
        globals_dict = {}
        subparser_dict = {}

        if not args_list:
            # No arguments: return empty global namespace
            return {"global": argparse.Namespace()}

        # Check for subparser: first non-option argument
        first_non_opt = None
        opt_index = 0
        while opt_index < len(args_list) and (args_list[opt_index].startswith('-')):
            opt_index += 1
        if opt_index < len(args_list):
            first_non_opt = args_list[opt_index]

        if first_non_opt and not first_non_opt.startswith('-'):
            subparser_name = first_non_opt
            # Parse globals before subparser
            globals_dict, _ = _parse_key_value(args_list, 0)
            # Remove the subparser name token
            remaining = args_list[opt_index + 1 :]
            subparser_dict, _ = _parse_key_value(remaining, 0)
        else:
            # No subparser, parse all as globals
            globals_dict, _ = _parse_key_value(args_list, 0)

        if subparser_name:
            return {subparser_name: argparse.Namespace(**subparser_dict)}
        else:
            return {"global": argparse.Namespace(**globals_dict)}

    except Exception:
        # In case of any parsing error, return an empty mapping
        return {}

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse
    # Create a top‑level parser for global options
    top_parser = argparse.ArgumentParser(add_help=False)
    # Detect a sub‑command: first non‑flag token after any global flags
    subparser_index = None
    for i, arg in enumerate(unparsed_arguments):
        if not arg.startswith('-'):
            subparser_index = i
            break

    # If no sub‑command was detected, just parse everything as global
    if subparser_index is None:
        try:
            global_namespace = top_parser.parse_args(unparsed_arguments)
        except SystemExit:
            # If parsing failed, fall back to an empty Namespace
            global_namespace = argparse.Namespace()
        return {"global": global_namespace}

    # Separate global arguments and sub‑command arguments
    global_args = unparsed_arguments[:subparser_index]
    subparser_name = unparsed_arguments[subparser_index]
    sub_args = unparsed_arguments[subparser_index + 1 :]

    # Parse known global arguments; ignore those that are not recognized
    try:
        global_namespace = top_parser.parse_args(global_args)
    except SystemExit:
        global_namespace = argparse.Namespace()
    # Parse sub‑command arguments with a generic (empty) parser
    sub_parser = argparse.ArgumentParser(add_help=False)
    try:
        sub_namespace = sub_parser.parse_args(sub_args)
    except SystemExit:
        sub_namespace = argparse.Namespace()

    return {"global": global_namespace, subparser_name: sub_namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Basic type checks
    if not hasattr(unparsed_arguments, "__iter__"):
        raise TypeError("unparsed_arguments must be an iterable of argument tokens")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dictionary mapping name -> ArgumentParser")

    parsed_results = {}
    remainders = []

    for name, parser in subparsers.items():
        if not hasattr(parser, "parse_known_args"):
            raise TypeError(f"Parser for '{name}' does not support parse_known_args()")
        try:
            args, rem = parser.parse_known_args(unparsed_arguments)
        except SystemExit as e:
            # argparse by default calls sys.exit() which raises SystemExit.
            # Convert it to a more informative exception.
            raise ValueError(
                f"Argument parsing failed for subparser '{name}': {e}"
            ) from e
        parsed_results[name] = args
        remainders.append(rem)

    # Compute arguments not claimed by any subparser: intersection of all remainder lists.
    if remainders:
        remaining = list(remainders[0])
        for rem in remainders[1:]:
            # Keep only items that appear in the current remainder.
            remaining = [item for item in remaining if item in rem]
    else:
        # No subparsers: nothing was consumed
        remaining = list(unparsed_arguments)

    return parsed_results, remaining

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed = {}
    # If there are no subparsers, return empty dict and all arguments as remaining
    if not subparsers:
        return parsed, list(unparsed_arguments)

    remaining_set = None
    first = True
    for name, parser in subparsers.items():
        try:
            ns, rem = parser.parse_known_args(unparsed_arguments)
        except Exception:
            # If parsing fails, treat this subparser as not contributing any known args
            ns = None
            rem = list(unparsed_arguments)
        parsed[name] = ns
        if first:
            remaining_set = set(rem)
            first = False
        else:
            remaining_set &= set(rem)

    # Preserve the original order of the remaining arguments
    if remaining_set is None:
        remaining_list = list(unparsed_arguments)
    else:
        remaining_list = [arg for arg in unparsed_arguments if arg in remaining_set]

    return parsed, remaining_list

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Validate inputs
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError('unparsed_arguments must be a list or tuple of strings')
    if not isinstance(subparsers, dict):
        raise TypeError('subparsers must be a dictionary mapping names to ArgumentParser instances')

    parsed_results = {}
    unknown_sets = []

    for name, parser in subparsers.items():
        # Ensure that the provided object looks like an ArgumentParser
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f'Parser for subparser "{name}" is not a valid ArgumentParser')

        try:
            namespace, unknown_args = parser.parse_known_args(unparsed_arguments)
        except Exception as exc:
            raise RuntimeError(f'Error while parsing arguments for subparser "{name}": {exc}') from exc

        parsed_results[name] = namespace
        unknown_sets.append(set(unknown_args))

    # Determine arguments that remain unclaimed by every subparser
    if unknown_sets:
        remaining_args = sorted(set.intersection(*unknown_sets))
    else:
        remaining_args = []

    return parsed_results, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed = {}
    unknown_sets = {}

    for name, parser in subparsers.items():
        try:
            namespace, unknown = parser.parse_known_args(unparsed_arguments)
        except Exception:  # pragma: no cover
            # If parsing fails, treat as no known args for this subparser
            namespace = argparse.Namespace()
            unknown = list(unparsed_arguments)
        parsed[name] = namespace
        unknown_sets[name] = set(unknown)

    # Determine arguments that are unknown to all subparsers
    remaining = []
    for arg in unparsed_arguments:
        if all(arg in unknown_sets[name] for name in subparsers):
            remaining.append(arg)

    return parsed, remaining

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    try:
        parser = argparse.ArgumentParser()
        subparsers = parser.add_subparsers(dest='command')
        return parser, subparsers
    except Exception as e:
        raise RuntimeError(f"Failed to create parsers: {e}") from e

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    The implementation below uses the node.tag attribute to differentiate a MappingNode from
    other node types. It recursively merges MappingNodes and preserves the order of keys from
    the first appearance.
    '''
    # Basic validation
    if not isinstance(nodes, list):
        raise ValueError('deep_merge_nodes expects a list of (ScalarNode, Node) tuples')

    def is_mapping(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    def merge_mapping_nodes(node_a, node_b):
        """Recursively merge two MappingNode objects."""
        # node_a and node_b are expected to be MappingNode instances
        # Build an indexed dict from node_a's value list for quick lookup
        a_dict = {}
        for k, v in getattr(node_a, 'value', []):
            try:
                k_str = getattr(k, 'value', None)
            except Exception:
                continue
            a_dict[k_str] = (k, v)

        # Prepare output list starting from node_a's order
        merged_pairs = []
        for k, v in getattr(node_a, 'value', []):
            k_str = getattr(k, 'value', None)
            if k_str in a_dict:  # will always be true for this loop
                # will be overridden if node_b has this key
                merged_pairs.append((k, v))
        # Process node_b's pairs
        for k_b, v_b in getattr(node_b, 'value', []):
            try:
                k_str_b = getattr(k_b, 'value', None)
            except Exception:
                continue
            if k_str_b in a_dict:
                # key exists in node_a, replace value appropriately
                old_k, old_v = a_dict[k_str_b]
                if is_mapping(old_v) and is_mapping(v_b):
                    # both are mappings, merge recursively
                    merged_v = merge_mapping_nodes(old_v, v_b)
                else:
                    # otherwise, last wins: use v_b
                    merged_v = v_b
                # update in merged_pairs: find old_k's index
                for idx, (k_curr, _) in enumerate(merged_pairs):
                    if getattr(k_curr, 'value', None) == k_str_b:
                        merged_pairs[idx] = (old_k, merged_v)
                        break
            else:
                # new key, append
                merged_pairs.append((k_b, v_b))
                a_dict[k_str_b] = (k_b, v_b)

        # Construct a new MappingNode with merged pairs
        new_node = type(node_a)()
        new_node.tag = node_a.tag
        new_node.value = merged_pairs
        return new_node

    # Merge across duplicate keys
    merged_dict = {}
    key_node_map = {}
    for item in nodes:
        if not (isinstance(item, tuple) and len(item) == 2):
            raise ValueError('Each element of nodes must be a (key_node, value_node) tuple')
        key_node, val_node = item
        try:
            key_str = getattr(key_node, 'value', None)
        except Exception:
            raise ValueError('Key node must have a value attribute')
        if key_str in merged_dict:
            existing_val = merged_dict[key_str]
            if is_mapping(existing_val) and is_mapping(val_node):
                merged_val = merge_mapping_nodes(existing_val, val_node)
            else:
                merged_val = val_node  # last wins
            merged_dict[key_str] = merged_val
            key_node_map[key_str] = key_node  # keep latest key node (last wins)
        else:
            merged_dict[key_str] = val_node
            key_node_map[key_str] = key_node

    # Preserve order from the original nodes list
    result = []
    seen = set()
    for item in nodes:
        key_node, _ = item
        key_str = getattr(key_node, 'value', None)
        if key_str not in seen:
            seen.add(key_str)
            result.append((key_node_map[key_str], merged_dict[key_str]))
    return result

def deep_merge_nodes(nodes):
    """
    Merge a list of YAML nodes with duplicate keys, deep‑merging any mapping values.
    If a duplicated key maps to non‑MappingNode values, the later value wins.
    """
    # Attempt to get MappingNode class; if unavailable, fall back to duck typing.
    try:
        MappingNodeCls = ruamel.yaml.nodes.MappingNode
    except Exception:
        MappingNodeCls = None

    def _is_mapping(v):
        if MappingNodeCls:
            return isinstance(v, MappingNodeCls)
        return hasattr(v, "tag") and "map" in getattr(v, "tag", "") and hasattr(v, "value") and isinstance(v.value, list)

    def _merge_mapping_nodes(node1, node2):
        # Merge two MappingNode instances (node1 and node2) into a new MappingNode.
        mapping = {}
        order = []

        def add_pair(k_node, v_node, new=False):
            key = k_node.value
            if key not in mapping:
                mapping[key] = (k_node, v_node)
                if not new:
                    order.append(key)
            else:
                # replace value, keep original position
                mapping[key] = (k_node, v_node)

        for k_node, v_node in node1.value:
            add_pair(k_node, v_node, new=False)

        for k_node, v_node in node2.value:
            key = k_node.value
            if key in mapping:
                old_v_node = mapping[key][1]
                if _is_mapping(old_v_node) and _is_mapping(v_node):
                    merged = _merge_mapping_nodes(old_v_node, v_node)
                    mapping[key] = (k_node, merged)
                else:
                    mapping[key] = (k_node, v_node)
            else:
                mapping[key] = (k_node, v_node)
                order.append(key)

        merged_list = [(mapping[k][0], mapping[k][1]) for k in order]
        # Create a new MappingNode using the class of node1 if possible
        if MappingNodeCls:
            return MappingNodeCls(node1.tag, merged_list)
        # Fallback: assume node1 has similar constructor
        return type(node1)(node1.tag, merged_list)

    result_dict = {}
    result_order = []

    for key_node, val_node in nodes:
        key = key_node.value
        if key in result_dict:
            old_val = result_dict[key][1]
            if _is_mapping(old_val) and _is_mapping(val_node):
                merged_val = _merge_mapping_nodes(old_val, val_node)
                result_dict[key] = (key_node, merged_val)
            else:
                result_dict[key] = (key_node, val_node)
        else:
            result_dict[key] = (key_node, val_node)
            result_order.append(key)

    return [(result_dict[k][0], result_dict[k][1]) for k in result_order]

def deep_merge_nodes(nodes):
    '''
    Merge duplicate keys in a list of YAML nodes, merging nested mapping nodes recursively.
    '''
    def merge_lists(list1, list2):
        '''Merge two lists of (key_node, value_node) tuples, preserving the order from list1
        and appending any new keys from list2. For duplicate keys that map to MappingNode
        objects, merge their .value lists recursively.'''
        merged = list1.copy()
        # Map from key value to value_node for quick lookup
        mapping = {k_node.value: v_node for k_node, v_node in list1}
        for k_node2, v_node2 in list2:
            k_val = k_node2.value
            if k_val in mapping:
                v_node1 = mapping[k_val]
                # both are mapping nodes => deep merge recursively
                if hasattr(v_node1, 'value') and hasattr(v_node2, 'value') and isinstance(v_node1.value, list) and isinstance(v_node2.value, list):
                    new_children = merge_lists(v_node1.value, v_node2.value)
                    v_node1.value = new_children
                else:
                    # last wins for non-mapping values
                    mapping[k_val] = v_node2
                    # replace in merged list
                    for idx, (kn, _) in enumerate(merged):
                        if kn.value == k_val:
                            merged[idx] = (kn, v_node2)
                            break
            else:
                mapping[k_val] = v_node2
                merged.append((k_node2, v_node2))
        return merged

    result = []
    for key_node, value_node in nodes:
        k_val = key_node.value
        found = False
        for idx, (kn, vn) in enumerate(result):
            if kn.value == k_val:
                found = True
                if hasattr(vn, 'value') and hasattr(value_node, 'value') and isinstance(vn.value, list) and isinstance(value_node.value, list):
                    new_children = merge_lists(vn.value, value_node.value)
                    vn.value = new_children
                else:
                    result[idx] = (key_node, value_node)
                break
        if not found:
            result.append((key_node, value_node))
    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    try:
        if not isinstance(nodes, list):
            raise TypeError("nodes must be a list of (key, value) tuples")
        # Helper function to identify MappingNode by its tag
        def is_mapping(node):
            return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

        # Recursive merge of two nodes
        def merge_nodes(existing, new):
            if is_mapping(existing) and is_mapping(new):
                merge_mapping(existing, new)
                return existing
            else:
                # When not both mappings, last value wins
                return new

        # Merge two MappingNodes by merging their value lists
        def merge_mapping(existing, new):
            existing_pairs = existing.value  # list of (key_node, value_node)
            new_pairs = new.value
            # For each new pair, try to merge or append
            for new_key_node, new_val_node in new_pairs:
                key_val = new_key_node.value
                found = False
                for idx, (ex_key_node, ex_val_node) in enumerate(existing_pairs):
                    if ex_key_node.value == key_val:
                        merged_val = merge_nodes(ex_val_node, new_val_node)
                        existing_pairs[idx] = (ex_key_node, merged_val)
                        found = True
                        break
                if not found:
                    # Append new pair (keep key node from new)
                    existing_pairs.append((new_key_node, new_val_node))

        result = []
        index_map = {}  # key value -> index in result
        for key_node, val_node in nodes:
            if not hasattr(key_node, 'value'):
                raise TypeError("Key node must have a 'value' attribute")
            key = key_node.value
            if key in index_map:
                idx = index_map[key]
                existing_key_node, existing_val_node = result[idx]
                merged_val = merge_nodes(existing_val_node, val_node)
                result[idx] = (existing_key_node, merged_val)
            else:
                index_map[key] = len(result)
                result.append((key_node, val_node))
        return result
