def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    # Create a root parser that will capture global arguments.  
    # Subparsers are added, but no specific ones are registered.
    root_parser = argparse.ArgumentParser(prog=None, add_help=False)
    subparsers = root_parser.add_subparsers(dest='subparser')
    # Parse known arguments – leave any unknown arguments aside.
    try:
        namespace, unknown = root_parser.parse_known_args(unparsed_arguments)
    except SystemExit:
        # SystemExit is raised for help or invalid arguments; return empty dict
        return {}
    except Exception as exc:
        # Any other exception – encapsulate in a namespace for diagnostics
        namespace = argparse.Namespace(error=str(exc))
    # Attach unknown arguments if any for debugging purposes.
    if hasattr(namespace, 'unknown'):
        pass
    else:
        # Store them as an attribute of the namespace
        namespace.unknown = unknown
    # Determine the key for the return dictionary
    key = getattr(namespace, 'subparser', None)
    if key:
        return {key: namespace}
    else:
        return {'global': namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed = {}
    unknown_lists = []

    # If no subparsers, return all arguments as remaining
    if not subparsers:
        return {}, list(unparsed_arguments)

    for name, parser in subparsers.items():
        try:
            namespace, unknown = parser.parse_known_args(unparsed_arguments)
        except Exception:
            # If a parser fails, skip it and leave all arguments unclaimed
            namespace, unknown = None, list(unparsed_arguments)
        parsed[name] = namespace
        unknown_lists.append(set(unknown))

    # Remaining arguments are those that were unknown to *all* subparsers
    common_unknown = set.intersection(*unknown_lists) if unknown_lists else set()
    remaining = [arg for arg in unparsed_arguments if arg in common_unknown]

    return parsed, remaining

