def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple of single-character strings, got {type(alphabet).__name__}")
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols to represent a base")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    # Handle negative numbers
    is_negative = number < 0
    number_abs = abs(number)

    # Convert to the target base
    digits = []
    if number_abs == 0:
        digits.append(alphabet[0])
    else:
        while number_abs:
            number_abs, rem = divmod(number_abs, base)
            digits.append(alphabet[rem])
    # Digits are in reverse order; reverse them for most-significant-first
    digits.reverse()
    result = "".join(digits)

    # Apply padding (excluding any leading minus sign)
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    # Prepend minus sign if needed
    if is_negative:
        result = "-" + result

    return result

