    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic validation of input types
    if string is None or alphabet is None:
        raise TypeError("Both `string` and `alphabet` must be provided.")
    if not isinstance(string, str):
        raise TypeError("`string` must be a str instance.")
    if not isinstance(alphabet, list):
        raise TypeError("`alphabet` must be a list of strings.")
    if len(alphabet) == 0:
        raise ValueError("`alphabet` must not be empty.")

    # Build a mapping from symbol to its numeric value
    mapping: dict[str, int] = {}
    for idx, sym in enumerate(alphabet):
        if not isinstance(sym, str):
            raise TypeError("All symbols in `alphabet` must be strings.")
        if sym in mapping:
            raise ValueError(f"Duplicate symbol '{sym}' found in the alphabet.")
        mapping[sym] = idx

    base = len(alphabet)

    # Handle optional sign
    negative = False
    start_index = 0
    if string and string[0] in ('+', '-'):
        negative = string[0] == '-'
        start_index = 1
        if len(string) == 1:  # string contains only a sign
            raise ValueError("String does not contain any digits.")

    # Convert each digit to its numeric value
    value = 0
    for ch in string[start_index:]:
        if ch not in mapping:
            raise ValueError(f"Invalid character '{ch}' not present in alphabet.")
        value = value * base + mapping[ch]

    return -value if negative else value

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    import io
    import tarfile
    import requests
    # Ensure destination path is a Path instance and exists
    if not isinstance(destination_path, Path):
        destination_path = Path(destination_path)
    if not destination_path.exists():
        try:
            destination_path.mkdir(parents=True, exist_ok=True)
        except Exception as exc:
            raise RuntimeError(f"Failed to create destination directory '{destination_path}': {exc}") from exc
    elif not destination_path.is_dir():
        raise RuntimeError(f"Destination path '{destination_path}' is not a directory")

    # Download the archive
    try:
        resp = requests.get(url, stream=True, timeout=30)
        resp.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Error downloading archive from '{url}': {exc}") from exc

    # Read content into memory
    try:
        buf = io.BytesIO()
        for chunk in resp.iter_content(chunk_size=8192):
            if chunk:
                buf.write(chunk)
        buf.seek(0)
    except Exception as exc:
        raise RuntimeError(f"Error reading data from response for '{url}': {exc}") from exc

    # Extract the archive
    try:
        with tarfile.open(fileobj=buf, mode="r:gz") as tar:
            tar.extractall(path=destination_path)
    except Exception as exc:
        raise RuntimeError(f"Error extracting archive from '{url}': {exc}") from exc

    return destination_path

