    regex_map = {}
    # Characters that have special meaning in regex and should be escaped
    _special_chars = ".^$+{}[]|()\\"
    for key, value in item.items():
        if not isinstance(key, str):
            raise TypeError(f"Dictionary keys must be strings, got {type(key).__name__}")
        # Build regex pattern from glob pattern
        parts = []
        for ch in key:
            if ch == "*":
                parts.append(".*")
            elif ch == "?":
                parts.append(".")
            elif ch in _special_chars:
                parts.append(f"\\{ch}")
            else:
                parts.append(ch)
        pattern = "^" + "".join(parts) + "$"
        regex_map[pattern] = value
    return regex_map

