def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import pathlib
    import shutil
    import tempfile
    import os

    archive = pathlib.Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    # Resolve temp path
    tmp_dir = pathlib.Path(tmp_path).resolve()
    try:
        tmp_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Could not create temporary directory {tmp_dir}") from e

    # Determine destination directory for extraction
    if filename:
        dest_dir_name = filename
    else:
        dest_dir_name = archive.stem
    dest_dir = tmp_dir / dest_dir_name

    # If destination exists, remove it to avoid stale data
    if dest_dir.exists():
        try:
            shutil.rmtree(dest_dir)
        except Exception as e:
            raise RuntimeError(f"Could not clean existing extraction directory {dest_dir}") from e

    # Ensure the destination directory exists
    try:
        dest_dir.mkdir(parents=True, exist_ok=False)
    except Exception as e:
        raise RuntimeError(f"Could not create extraction directory {dest_dir}") from e

    # Unpack the archive, trying common formats
    try:
        shutil.unpack_archive(str(archive), str(dest_dir))
    except shutil.ReadError as e:
        # If unpacking fails, provide a clear error
        raise RuntimeError(f"Failed to unpack archive '{archive_path}'. Unsupported format or corrupted file.") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while unpacking '{archive_path}': {e}") from e

    # Build file:// URL suitable for git origin
    repo_url = f"file://{dest_dir.resolve().as_posix()}"
    return repo_url

