def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle None and “always” cases
    if frequency is None:
        return None
    freq_str = frequency.strip()
    if not freq_str:
        return None
    if freq_str.lower() == "always":
        return None

    # Expect format “<number> <unit>” with exactly one space separator
    parts = freq_str.split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: '{frequency}'")

    number_str, unit_str = parts
    try:
        # Support integers and floats
        if '.' in number_str:
            value = float(number_str)
        else:
            value = int(number_str)
    except ValueError as exc:
        raise ValueError(f"Invalid numeric value in frequency: '{frequency}'") from exc

    unit_key = unit_str.lower()
    unit_map = {
        'day': 'days',
        'days': 'days',
        'hour': 'hours',
        'hours': 'hours',
        'minute': 'minutes',
        'minutes': 'minutes',
        'week': 'weeks',
        'weeks': 'weeks',
    }

    if unit_key not in unit_map:
        raise ValueError(f"Unsupported time unit in frequency: '{frequency}'")

    kwargs = {unit_map[unit_key]: value}
    return datetime.timedelta(**kwargs)

