    elif unit in ('week', 'weeks'):
        kwargs['weeks'] = num
    elif unit in ('month', 'months'):
        # Approximate a month as 30 days
        kwargs['days'] = num * 30
    elif unit in ('year', 'years'):
        # Approximate a year as 365 days
        kwargs['days'] = num * 365
    else:
        raise ValueError(f"Unsupported time unit '{unit}'")

    return datetime.timedelta(**kwargs)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None

    f = frequency.strip()
    if f.lower() == 'always':
        return None

    # Match a number followed by a unit, allowing optional whitespace
    import re
    m = re.fullmatch(r'\s*([0-9]*\.?[0-9]+)\s*([a-zA-Z]+)\s*', f)
    if not m:
        raise ValueError(f'Invalid frequency format: {frequency!r}')

    num_str, unit = m.group(1), m.group(2).lower()

    try:
        value = float(num_str)
    except ValueError:
        raise ValueError(f'Invalid numeric value in frequency: {frequency!r}')

    kwargs = {}
    if unit in ('week', 'weeks'):
        kwargs['weeks'] = int(value)
    elif unit in ('day', 'days'):
        kwargs['days'] = value
    elif unit in ('hour', 'hours'):
        kwargs['hours'] = value
    elif unit in ('minute', 'minutes', 'min', 'mins', 'm'):
        kwargs['minutes'] = value
    elif unit in ('second', 'seconds', 'sec', 'secs', 's'):
        kwargs['seconds'] = value
    else:
        raise ValueError(f'Unknown unit in frequency: {frequency!r}')

    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Validate input
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False

    # Direct literal checks
    if host.lower() == "localhost":
        return True
    if host == "127.0.0.1":
        return True
    if host == "::1":
        return True

    # Resolve host to IP addresses and check if any is loopback
    try:
        # The port argument can be None because we only care about address resolution
        addrs = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        # Address resolution failed; not local
        return False
    except Exception:
        # Unexpected error; conservatively return False
        return False

    for family, _, _, _, sockaddr in addrs:
        # sockaddr is a tuple: (address, port) for IPv4
        # For IPv6, it may be (address, port, flowinfo, scopeid)
        try:
            ip = sockaddr[0]
        except Exception:
            continue

        # Check IPv4 loopback range 127.0.0.0/8
        if family == socket.AF_INET:
            if ip.startswith("127."):
                return True
        # Check IPv6 loopback ::1
        elif family == socket.AF_INET6:
            # Normalize IPv6 addressing: ::1 may appear in various forms
            if ip.lower() == "::1":
                return True

    return False

