def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional
    default value. If the variable is not defined in environment and no default
    value is provided, a RuntimeError is raised.

    The matcher can be one of the following:
    * A sequence or tuple: first element is the variable name, second (optional)
      element is the default value.
    * A dictionary with keys 'name' (or 'var'/'variable') and optional 'default'.
    * A string: treated as the variable name with no default.
    * Any object with groups() / group() (typically a re.Match) where the first
      group is the variable name and the second (if present) is the default.
    """
    name = None
    default = None
    try:
        # Handle mapping types
        if isinstance(matcher, dict):
            name = matcher.get('name') or matcher.get('var') or matcher.get('variable')
            default = matcher.get('default')
        # Handle sequences (list/tuple/range)
        elif isinstance(matcher, (list, tuple)):
            if len(matcher) == 0:
                raise ValueError("Empty matcher sequence; cannot extract variable name.")
            name = matcher[0]
            if len(matcher) > 1:
                default = matcher[1]
        # Handle regex match objects or similar
        elif hasattr(matcher, 'groups') and callable(matcher.groups):
            groups = matcher.groups()
            if len(groups) == 0:
                raise ValueError("Matcher has no captured groups.")
            name = groups[0]
            if len(groups) > 1:
                default = groups[1]
        # Fallback: treat as string
        else:
            name = str(matcher)
            default = None

        if not name:
            raise ValueError(f"Unable to determine variable name from matcher: {matcher!r}")

        value = os.getenv(name)
        if value is None:
            if default is not None:
                value = default
            else:
                raise RuntimeError(
                    f"Environment variable '{name}' is not set and no default value provided."
                )
        return value
    except Exception as exc:
        # Provide context for debugging, preserve original exception
        raise RuntimeError(f"Failed to resolve string for matcher {matcher!r}: {exc}") from exc

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern.
    It returns a compiled regular expression that matches the
    literal string provided (after optional stripping).
    """
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    try:
        processed = pattern.strip() if strip else pattern
        # Escape all regex metacharacters so the string is treated literally
        literal_pattern = re.escape(processed)
        return re.compile(literal_pattern)
    except re.error as exc:
        raise ValueError(f"Invalid regex pattern: {exc}") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Normalize commands into a list
    if isinstance(commands, (list, tuple)):
        command_list = list(commands)
    elif isinstance(commands, str):
        command_list = [commands]
    else:
        raise TypeError(f"commands must be a string or a list/tuple of strings, got {type(commands).__name__}")

    # Normalize args into a list
    if args is None:
        args_list = []
    else:
        if isinstance(args, (list, tuple)):
            args_list = list(args)
        else:
            raise TypeError(f"args must be a list/tuple of arguments or None, got {type(args).__name__}")

    results = []

    for cmd in command_list:
        # Build the full command
        if not isinstance(cmd, str):
            raise TypeError(f"Each command must be a string, got {type(cmd).__name__}")

        full_cmd = [cmd] + args_list
        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")

        # Prepare subprocess arguments
        stderr_arg = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=stderr_arg,
                text=True,
                check=False,
            )
            output = {
                'command': full_cmd,
                'returncode': result.returncode,
                'stdout': result.stdout,
            }
            # Only include stderr if it's not hidden
            if not hide_stderr:
                output['stderr'] = result.stderr

            # If a non-zero return code was detected, optionally warn
            if result.returncode != 0:
                if verbose:
                    print(f"Command {' '.join(full_cmd)} exited with return code {result.returncode}")
                if not hide_stderr and result.stderr:
                    print(f"Stderr:\n{result.stderr}")

            results.append(output)
        except FileNotFoundError:
            error_msg = f"Command not found: {cmd}"
            if verbose:
                print(error_msg)
            results.append({'command': full_cmd, 'returncode': None, 'stdout': '', 'stderr': error_msg})
        except OSError as exc:
            error_msg = f"Failed to execute '{cmd}': {exc}"
            if verbose:
                print(error_msg)
            results.append({'command': full_cmd, 'returncode': None, 'stdout': '', 'stderr': error_msg})
        except Exception as exc:
            error_msg = f"Unexpected error running '{cmd}': {exc}"
            if verbose:
                print(error_msg)
            results.append({'command': full_cmd, 'returncode': None, 'stdout': '', 'stderr': error_msg})

    # Return single result if only one command was provided
    if len(results) == 1:
        return results[0]
    return results

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if commands is None:
        raise ValueError("commands cannot be None")

    # Build the command list from the provided commands
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        # Simple split; assumes no complex quoting
        cmd_list = commands.split()

    # Append any arguments
    if args:
        if isinstance(args, (list, tuple)):
            args_list = list(args)
        else:
            args_list = args.split()
        cmd_list.extend(args_list)

    # Show the command if verbose output is requested
    if verbose:
        try:
            print("Running command:", " ".join(cmd_list))
        except Exception:  # In case of printing issues
            pass

    # Configure stderr handling
    stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        process = subprocess.Popen(
            cmd_list,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            text=True,
            env=env,
        )
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            # Build a helpful exception
            error_msg = f"Command '{' '.join(cmd_list)}' failed with return code {process.returncode}"
            if stderr:
                error_msg += f"\nStderr: {stderr.strip()}"
            raise subprocess.CalledProcessError(
                returncode=process.returncode,
                cmd=cmd_list,
                output=stdout,
                stderr=stderr,
            )
        return stdout
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {e})")
    except Exception as e:
        # Re-raise any other exceptions as a runtime error
        raise RuntimeError(f"An error occurred while running command '{' '.join(cmd_list)}': {e}") from e

