def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Return the set of root nodes of a transitive hierarchy defined by ``prop``.
    A root node is a node that has no ancestor via ``prop``.  If ``roots`` is
    supplied, only the nodes in that set are considered when determining
    ancestors: a node whose parent is outside the set is treated as a root.

    Parameters
    ----------
    graph : Graph
        RDFLib graph containing triples of the form (child, prop, parent).
    prop : URIRef
        The predicate that defines the hierarchical relationship.
    roots : Optional[Set[Node]]
        Optional set of nodes to restrict the search to.  If omitted, the
        entire graph is examined.

    Returns
    -------
    Set[Node]
        A set of root nodes.
    """
    try:
        # Determine the set of nodes to consider
        if roots is None:
            # All nodes that appear either as subject or object of the prop
            subjects = {s for s in graph.subjects(predicate=prop)}
            objects = {o for o in graph.objects(predicate=prop)}
            all_nodes = subjects | objects
        else:
            all_nodes = set(roots)

        roots_found: Set["Node"] = set()

        for node in all_nodes:
            # Find direct parents of the current node via ``prop``
            parents = {p for p in graph.objects(subject=node, predicate=prop)}
            # If no parents exist, it is a root
            if roots is None:
                if not parents:
                    roots_found.add(node)
            else:
                # In the restricted case, a node is a root if none of its parents
                # belong to the restricted set of nodes.
                if not any(parent in all_nodes for parent in parents):
                    roots_found.add(node)

        return roots_found
    except Exception:
        # In case of any unexpected error, fall back to an empty set
        return set()

