    """Dump to a py2-unicode or py3-string"""
    # Use yaml.safe_dump for most cases, but allow a custom Dumper class if provided.
    try:
        if dumper is None:
            # Default safe dumping: returns a unicode/str object.
            dumped = yaml.safe_dump(obj)
        else:
            # Validate that the provided dumper is a subclass of yaml.Dumper
            if not isinstance(dumper, type) or not issubclass(dumper, yaml.Dumper):
                raise TypeError(
                    f"dumper must be a subclass of yaml.Dumper, got {type(dumper).__name__}"
                )
            dumped = yaml.dump(obj, Dumper=dumper)
        # Ensure the result is a string (unicode in py2, str in py3)
        if isinstance(dumped, bytes):
            # Decode bytes to unicode/str using default utf-8
            return dumped.decode("utf-8")
        return str(dumped)
    except yaml.YAMLError as exc:
        # Re‑raise as a ValueError with context for callers
        raise ValueError(f"Failed to dump object to YAML string: {exc}") from exc
    except Exception as exc:
        # Catch-all for unexpected errors
        raise ValueError(f"Unexpected error during dumping: {exc}") from exc

