def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input 'x' could not be converted to a numeric array.") from e

    mu = 0.2
    sigma = 0.1
    exponent = -((x_arr - mu) ** 2) / (2.0 * sigma ** 2)
    return np.exp(exponent)

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input x must be array-like and contain numeric values.") from e
    mean = 0.2
    sigma = 0.1
    coeff = 1.0 / (sigma * np.sqrt(2 * np.pi))
    exponent = -((x_arr - mean) ** 2) / (2 * sigma ** 2)
    return coeff * np.exp(exponent)

