def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
      - dict of configuration filename to corresponding parsed configuration,
      - sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, logging, re, os, types

    # Helper to recursively replace ${VAR} placeholders with environment variables
    def _replace_env(obj):
        if isinstance(obj, dict):
            return {k: _replace_env(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_replace_env(v) for v in obj]
        elif isinstance(obj, str):
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            return pattern.sub(repl, obj)
        else:
            return obj

    configs = {}
    records = []
    logger = logging.getLogger('load_configurations')

    # Ensure we have an iterable of filenames
    try:
        iter(config_filenames)
    except TypeError:
        msg = f"config_filenames must be an iterable, got {type(config_filenames).__name__}"
        record = logger.makeRecord(logger.name, logging.ERROR, '', 0, msg, (), None)
        record.exc_info = (TypeError, TypeError(msg), None)
        records.append(record)
        return configs, records

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                raw_data = f.read()
        except FileNotFoundError as e:
            msg = f"File not found: {filename}"
            record = logger.makeRecord(logger.name, logging.ERROR, filename, 0, msg, (), None)
            record.exc_info = (FileNotFoundError, e, e.__traceback__)
            records.append(record)
            continue
        except Exception as e:
            msg = f"Error opening {filename}: {e}"
            record = logger.makeRecord(logger.name, logging.ERROR, filename, 0, msg, (), None)
            record.exc_info = (type(e), e, e.__traceback__)
            records.append(record)
            continue

        try:
            parsed = json.loads(raw_data)
        except Exception as e:
            msg = f"JSON parse error in {filename}: {e}"
            record = logger.makeRecord(logger.name, logging.ERROR, filename, 0, msg, (), None)
            record.exc_info = (type(e), e, e.__traceback__)
            records.append(record)
            continue

        if resolve_env:
            try:
                parsed = _replace_env(parsed)
            except Exception as e:
                msg = f"Environment variable resolution error in {filename}: {e}"
                record = logger.makeRecord(logger.name, logging.ERROR, filename, 0, msg, (), None)
                record.exc_info = (type(e), e, e.__traceback__)
                records.append(record)
                continue

        configs[filename] = parsed

    # Apply any overrides after loading
    if isinstance(overrides, dict):
        for fn, override_value in overrides.items():
            configs[fn] = override_value

    return configs, records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    # Prepare containers
    configs = {}
    error_records = []

    # Helper to create LogRecord for an exception
    def _make_error_record(filename, msg, exc_info):
        return logging.LogRecord(
            name=__name__,
            level=logging.ERROR,
            pathname=filename,
            lineno=0,
            msg=msg,
            args=None,
            exc_info=exc_info
        )

    # Helper to resolve environment variables in string values
    import re
    env_pattern = re.compile(r'\${([^}]+)}')

    def _resolve_env_value(value):
        if isinstance(value, str):
            def replace(match):
                var = match.group(1)
                return os.getenv(var, match.group(0))
            return env_pattern.sub(replace, value)
        return value

    def _recursive_env_resolve(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                obj[k] = _recursive_env_resolve(v)
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                obj[i] = _recursive_env_resolve(item)
        else:
            return _resolve_env_value(obj)
        return obj

    # Validate input type
    try:
        iter(config_filenames)
    except TypeError:
        raise TypeError("config_filenames must be an iterable of filenames")

    import os
    import json

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as fp:
                try:
                    data = json.load(fp)
                except json.JSONDecodeError as exc:
                    error_records.append(_make_error_record(
                        filename,
                        f"JSON decoding error in '{filename}'.",
                        exc_info=(type(exc), exc, exc.__traceback__)
                    ))
                    continue
        except (FileNotFoundError, PermissionError, OSError) as exc:
            error_records.append(_make_error_record(
                filename,
                f"Error opening file '{filename}'.",
                exc_info=(type(exc), exc, exc.__traceback__)
            ))
            continue

        if not isinstance(data, dict):
            error_records.append(_make_error_record(
                filename,
                f"Configuration in '{filename}' is not a JSON object.",
                exc_info=None
            ))
            continue

        # Apply overrides if provided
        if overrides and isinstance(overrides, dict):
            for key, value in overrides.items():
                data[key] = value

        # Resolve environment variables if requested
        if resolve_env:
            try:
                data = _recursive_env_resolve(data)
            except Exception as exc:
                error_records.append(_make_error_record(
                    filename,
                    f"Error resolving environment variables in '{filename}'.",
                    exc_info=(type(exc), exc, exc.__traceback__)
                ))
                continue

        configs[filename] = data

    return configs, error_records

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Validate the input type
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple of (major, minor) or None")

    # Retrieve the registry of protocol handlers; fall back to empty dict if missing
    handlers = getattr(cls, 'PROTOCOL_HANDLERS', {})
    if not isinstance(handlers, dict):
        handlers = {}

    # If a specific protocol version is requested, return it if available
    if protocol_version is not None:
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

    # Return a copy of all available handlers if no specific version requested
    return handlers.copy()

