            seq_list = list(itertools.islice(seq, bufsize))
        else:
            seq_list = list(seq)
        return seq_list, type(seq_list)
    except Exception as exc:
        raise ValueError("Provided object is not iterable or cannot be converted to a sequence") from exc

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Define basic sequence types (incl. string/bytes which are sequence-like)
    _seq_types = (list, tuple, set, str, bytes, bytearray)
    try:
        # Handle None explicitly
        if seq is None:
            return (seq, type(seq))
        # If seq is already a recognized sequence type, return as is
        if isinstance(seq, _seq_types):
            return (seq, type(seq))
        # Special‑case dictionaries: convert to list of (key, value) tuples
        if isinstance(seq, dict):
            return (list(seq.items()), type(seq))
        # Attempt to iterate; if not iterable, treat as single element sequence
        try:
            iter(seq)
        except TypeError:
            return ((seq,), type(seq))
        # Iterable but not a basic sequence type – convert to list
        return (list(seq), type(seq))
    except Exception as exc:
        raise ValueError(f"Cannot construct sequence from {seq!r}") from exc

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Import here to avoid top-level imports
    from collections.abc import Sequence
    try:
        # Strings, bytes, and bytearray are considered sequences anyway,
        # but we want to preserve immutability.
        if isinstance(seq, (str, bytes, bytearray)):
            return seq, type(seq)
        # If seq is an instance of Sequence (including tuple, list, set, etc.)
        if isinstance(seq, Sequence):
            return seq, type(seq)
    except Exception:
        # If the type checks fail we fall back to conversion
        pass

    # If seq is None, treat it as an empty sequence
    if seq is None:
        return [], list

    # Try to build a list from seq; if it's not iterable we wrap it in a list
    try:
        iterable = iter(seq)
    except Exception:
        seq_list = [seq]
    else:
        # Convert iterable to a list (evaluating generators or other non-sequence iterables)
        seq_list = list(iterable)

    return seq_list, list

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    if seq is None:
        raise TypeError("seq must not be None")

    # Treat basic sequence types directly
    if isinstance(seq, (str, bytes, bytearray, list, tuple)):
        return seq, type(seq)

    # Heuristic for other sequence-like objects: check for __len__ and __getitem__
    if (hasattr(seq, "__len__") and hasattr(seq, "__getitem__")):
        return seq, type(seq)

    # Otherwise, attempt to build a list from the iterable
    try:
        seq_list = list(seq)
        return seq_list, list
    except Exception as exc:
        # Re‑raise a more informative error
        raise ValueError(f"Could not interpret {seq!r} as a sequence") from exc

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Basic validation of input parameters
    if not isinstance(field_names, (list, tuple)):
        raise TypeError("field_names must be a list or tuple of strings")
    if len(field_names) < 1:
        raise ValueError("field_names must contain at least one field name")

    # Try to extract bin contents from the histogram
    try:
        # If hist is iterable and returns numbers
        bin_values = list(hist)
    except Exception:
        raise TypeError("Provided histogram object is not iterable or gives non-listable bin contents")

    # Extract coordinate information (left edges and widths)
    left_edges = None
    widths = None

    # Helper to fetch attribute if it exists
    def _get_attr(obj, name):
        return getattr(obj, name, None)

    # With standard histogram interfaces
    if hasattr(hist, 'axes') and isinstance(hist.axes, (list, tuple)):
        if len(hist.axes) > 0:
            axis = hist.axes[0]
            left_edges = _get_attr(axis, 'left') or _get_attr(axis, 'edges')
            widths = _get_attr(axis, 'width')
    # Alternative attribute names
    if left_edges is None:
        left_edges = _get_attr(hist, 'left') or _get_attr(hist, 'edges')
    if widths is None:
        widths = _get_attr(hist, 'width')

    # Determine number of bins and provide defaults if missing
    n_bins = len(bin_values)
    if left_edges is None:
        left_edges = list(range(n_bins))
    elif isinstance(left_edges, (list, tuple)):
        if len(left_edges) != n_bins:
            raise ValueError("Length of left edges does not match number of bins")
    else:
        # If left_edges is a scalar, assume uniform
        left_edges = [left_edges] * n_bins

    # Width handling
    if widths is None:
        widths = [1] * n_bins
    elif isinstance(widths, (list, tuple)):
        if len(widths) != n_bins:
            raise ValueError("Length of widths does not match number of bins")
    else:
        widths = [widths] * n_bins

    # Prepare graph data structure
    class _Graph:
        def __init__(self, field_names, scale):
            self.field_names = tuple(field_names)
            self.scale = scale
            self.points = []

        def add_point(self, point):
            if not isinstance(point, dict):
                raise TypeError("point must be a dictionary")
            self.points.append(point)

        def __iter__(self):
            return iter(self.points)

        def __repr__(self):
            return f"<Graph fields={self.field_names} scale={self.scale} points={len(self.points)}>"

    # Determine scale value
    if scale is True:
        # Attempt to copy scale from histogram
        scale_val = getattr(hist, 'scale', None)
        if scale_val is None:
            raise ValueError("histogram does not provide a scale attribute")
    else:
        scale_val = scale

    # Prepare graph instance
    graph = _Graph(field_names, scale_val)

    # Build the points
    for idx, bin_val in enumerate(bin_values):
        # Determine coordinate
        try:
            left = float(left_edges[idx])
        except Exception:
            left = float(idx)  # fallback: use index
        if get_coordinate == "right":
            coord = left + float(widths[idx])
        elif get_coordinate == "middle":
            coord = left + 0.5 * float(widths[idx])
        else:  # left or any other string defaults to left
            coord = left

        # Compute y values using make_value
        y_values = None
        if make_value is None:
            y_values = bin_val
        else:
            try:
                y_values = make_value(bin_val)
            except Exception as e:
                raise RuntimeError(f"make_value function raised an error: {e}") from e

        # Ensure y_values is iterable if more than one field requested
        expected_y_fields = len(field_names) - 1
        if expected_y_fields == 0:
            # No y fields requested; ignore y_values
            y_list = []
        elif expected_y_fields == 1:
            # Only one y field expected
            if isinstance(y_values, (list, tuple)) and len(y_values) == 1:
                y_list = list(y_values)
            else:
                y_list = [y_values]
        else:
            if not isinstance(y_values, (list, tuple)):
                raise ValueError(f"make_value must return an iterable of length {expected_y_fields}")
            if len(y_values) != expected_y_fields:
                raise ValueError(f"make_value returned {len(y_values)} values but {expected_y_fields} were expected")
            y_list = list(y_values)

        # Assemble point dictionary
        point = {field_names[0]: coord}
        for fn, val in zip(field_names[1:], y_list):
            point[fn] = val

        # Add point to graph
        graph.add_point(point)

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid

    errors = []

    # Step 1: check declaration of provided interface
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except Exception as exc:
            raise Invalid("Cannot determine if candidate provides %s: %s"
                          % (iface, exc))
        if not provided:
            raise Invalid("Candidate %r does not declare that it provides %r"
                          % (candidate, iface))

    # Helper to fetch required method/attribute lists
    def _get_required_methods():
        try:
            return getattr(iface, "getRequiredMethods")()
        except Exception:
            # Fallback: use introspection on interface
            return [name for name, val in inspect.getmembers(iface)
                    if inspect.isfunction(val) and not name.startswith("_")]

    def _get_required_attributes():
        try:
            return getattr(iface, "getRequiredAttributes")()
        except Exception:
            # Fallback: look for attributes not starting with '_' and
            # not callables
            return [name for name, val in inspect.getmembers(iface)
                    if not name.startswith("_") and not inspect.isroutine(val)]

    # Step 2: check required attributes
    for attr_name in _get_required_attributes():
        if not hasattr(candidate, attr_name):
            errors.append("Missing attribute %s" % attr_name)
        else:
            if vtype is not None:
                value = getattr(candidate, attr_name)
                if not isinstance(value, vtype):
                    errors.append("Attribute %s expected type %r got %r"
                                  % (attr_name, vtype, type(value)))

    # Step 3: check required methods
    for method_name in _get_required_methods():
        if not hasattr(candidate, method_name):
            errors.append("Missing method %s" % method_name)
            continue

        cmethod = getattr(candidate, method_name)
        if not callable(cmethod):
            errors.append("%s is not callable" % method_name)
            continue

        iface_method = getattr(iface, method_name, None)
        if iface_method is None:
            # Should not happen; skip signature check
            continue

        try:
            iface_sig = inspect.signature(iface_method)
            c_sig = inspect.signature(cmethod)
        except Exception:
            # Cannot introspect signatures; skip check
            continue

        # Remove automatic instance argument if method defined on class
        def _strip_first_arg(sig):
            params = list(sig.parameters.values())
            if params and params[0].name == "self":
                return sig.replace(parameters=params[1:])
            return sig

        iface_sig = _strip_first_arg(iface_sig)
        c_sig = _strip_first_arg(c_sig)

        if iface_sig != c_sig:
            errors.append("Signature mismatch in %s: expected %s, got %s"
                          % (method_name, iface_sig, c_sig))

    # Final: report or succeed
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.
    """
    from zope.interface import providedBy
    from zope.interface.exceptions import Invalid
    import inspect

    errors = []

    # Check that candidate claims to provide iface, unless tentative
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(Invalid(
                    f"{candidate!r} does not claim to provide {iface!r}"
                ))
        except Exception as exc:
            errors.append(Invalid(f"Error checking providedBy: {exc}"))

    # Determine candidate class for method comparison
    candidate_cls = candidate if isinstance(candidate, type) else type(candidate)

    # Check methods defined in iface
    methods = {}
    if hasattr(iface, "methods"):
        try:
            methods = iface.methods()
        except Exception:
            methods = {}
    for name, iface_method in methods.items():
        # candidate must have an attribute with this name
        if not hasattr(candidate_cls, name):
            errors.append(Invalid(f"Missing method {name!r} in {candidate!r}"))
            continue
        cand_method = getattr(candidate_cls, name)
        if not callable(cand_method):
            errors.append(Invalid(f"Attribute {name!r} is not callable in {candidate!r}"))
            continue

        # Compare signatures
        try:
            iface_sig = inspect.signature(iface_method)
            cand_sig = inspect.signature(cand_method)
            # Simplest comparison: same number of positional/keyword params
            iface_params = list(iface_sig.parameters.values())
            cand_params = list(cand_sig.parameters.values())
            def key(p):
                return (p.kind, p.name)
            if [key(p) for p in iface_params] != [key(p) for p in cand_params]:
                errors.append(Invalid(
                    f"Signature mismatch for method {name!r} "
                    f"in {candidate!r}: expected {iface_sig}, got {cand_sig}"
                ))
        except ValueError as exc:
            errors.append(Invalid(f"Error inspecting signature of {name!r}: {exc}"))
        except Exception as exc:
            errors.append(Invalid(f"Unexpected error inspecting {name!r}: {exc}"))

    # Check attributes defined in iface
    attrs = {}
    if hasattr(iface, "attributes"):
        try:
            attrs = iface.attributes()
        except Exception:
            attrs = {}
    for name in attrs:
        if not hasattr(candidate_cls, name):
            errors.append(Invalid(f"Missing attribute {name!r} in {candidate!r}"))

    # Report errors
    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            messages = "; ".join(str(e) for e in errors)
            raise Invalid(messages)

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    # Import inspect locally to avoid top-level imports.
    try:
        import inspect
    except Exception as exc:
        raise ImportError("inspect module is required for signature checks") from exc

    errors = []

    # Check interface provision unless tentative
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"{candidate!r} does not provide {iface!r}")
        except Exception as exc:
            errors.append(f"Error checking providedBy for {candidate!r} and {iface!r}: {exc}")

    # Helper to get signature or None
    def get_sig(obj, name):
        try:
            return inspect.signature(obj)
        except Exception:
            return None

    # Check methods
    try:
        # Interface methods are accessible via iface.getMethodNames()
        method_names = getattr(iface, "getMethodNames", lambda: [])()
        # If getMethodNames not present, fall back to using iface.__dict__
        if not method_names:
            method_names = [name for name, value in iface.__dict__.items()
                            if callable(value) and not name.startswith("_")]
    except Exception:
        method_names = []

    for name in method_names:
        if not hasattr(candidate, name):
            errors.append(f"Missing method {name!r} in {candidate!r}")
            continue
        interface_func = getattr(iface, name, None)
        candidate_func = getattr(candidate, name, None)
        if not callable(candidate_func):
            errors.append(f"Attribute {name!r} in {candidate!r} is not callable")
            continue
        iface_sig = get_sig(interface_func, name)
        cand_sig = get_sig(candidate_func, name)
        if iface_sig is not None and cand_sig is not None:
            # Compare signatures
            if iface_sig != cand_sig:
                errors.append(
                    f"Signature mismatch for {name!r}: interface {iface_sig} vs candidate {cand_sig}"
                )

    # Check attributes
    try:
        attribute_names = getattr(iface, "getAttributes", lambda: {})()
        if attribute_names is None:
            attribute_names = {}
    except Exception:
        attribute_names = {}

    for attr_name in attribute_names:
        if not hasattr(candidate, attr_name):
            errors.append(f"Missing attribute {attr_name!r} in {candidate!r}")

    # Combine errors into Invalid if any
    if errors:
        from zope.interface import Invalid
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            message = "\n".join(errors)
            raise Invalid(message)

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    If ``tentative`` is ``False``, this function will raise a
    :class:`ValueError` if the candidate fails to provide the required
    members.  If ``tentative`` is ``True``, the function returns a two‑tuple
    ``(ok, errors)``; ``ok`` is a :class:`bool` indicating success,
    and ``errors`` is a list of missing or incorrect member names or
    ``None`` when verification succeeds.
    """
    if iface is None or not hasattr(iface, "__dict__"):
        raise TypeError("iface must be a class or interface-like object")
    if candidate is None:
        raise TypeError("candidate must not be None")
    # Prepare list of missing or invalid members
    missing = []
    # Iterate over interface definitions, skipping magic names
    for name in dir(iface):
        if name.startswith("_"):
            continue
        # Retrieve the interface attribute or method
        try:
            iface_val = getattr(iface, name)
        except Exception:
            continue  # skip any attribute that raises on access
        # Ensure candidate has the attribute
        if not hasattr(candidate, name):
            missing.append(name)
            continue
        cand_val = getattr(candidate, name)
        # If the interface value is callable, candidate must also be callable
        if callable(iface_val) and not callable(cand_val):
            missing.append(name)
    if missing:
        if tentative:
            return False, missing
        raise ValueError(
            f"Candidate {candidate!r} does not provide required members: "
            f"{', '.join(missing)}"
        )
    if tentative:
        return True, None

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate bases iterable
    if not isinstance(bases, (tuple, list)):
        try:
            bases = tuple(bases)
        except TypeError:
            raise TypeError("bases must be an iterable of classes")
    if not bases:
        # No bases provided – default to type
        return type
    for idx, b in enumerate(bases):
        if not isinstance(b, type):
            raise TypeError(f"Base index {idx} ({b!r}) is not a class")
    # Handle explicit metaclass if supplied
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("__metaclass__ must be a class")
        # Explicit metaclass must be a subclass of every base's metaclass
        for b in bases:
            base_meta = type(b)
            if not issubclass(explicit_mc, base_meta):
                raise TypeError(
                    f"__metaclass__ ({explicit_mc.__name__})"
                    f" is not a subclass of base type {base_meta.__name__}"
                )
        return explicit_mc
    # Determine metaclass from bases
    metaclasses = [type(b) for b in bases]
    # Preserve order but remove duplicates
    unique_meta = []
    seen = set()
    for m in metaclasses:
        if m not in seen:
            seen.add(m)
            unique_meta.append(m)
    # If all bases share the same metaclass, return it
    if len(unique_meta) == 1:
        return unique_meta[0]
    # Find a metaclass that is a subclass of all others
    for candidate in unique_meta:
        if all(issubclass(candidate, other) for other in unique_meta):
            return candidate
    # No single most derived metaclass – conflict
    raise TypeError(
        "metaclass conflict: the metaclass of a derived class must "
        "be a (non-strict) subclass of the metaclasses of all its bases"
    )

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate the bases iterable
    try:
        bases_iter = iter(bases)
    except TypeError:
        raise TypeError("bases must be an iterable of classes") from None
    # Convert to list to measure length if needed
    try:
        bases_list = list(bases_iter)
    except Exception as exc:
        raise TypeError("failed to iterate over bases") from exc
    if not bases_list:
        raise TypeError("no bases supplied to determine a metaclass")
    # If explicit metaclass is provided
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a class (type)")
        for base in bases_list:
            if not isinstance(base, explicit_mc):
                raise TypeError(
                    f"metaclass conflict: base {base!r} is not an instance of {explicit_mc!r}"
                )
        return explicit_mc
    # No explicit metaclass; determine common metaclass
    # Start with the metaclass of the first base
    common_meta = type(bases_list[0])
    for base in bases_list[1:]:
        this_meta = type(base)
        if common_meta is this_meta:
            continue
        # Try to detect subclass relationship between metaclasses
        try:
            if issubclass(common_meta, this_meta):
                continue
            if issubclass(this_meta, common_meta):
                common_meta = this_meta
                continue
        except Exception:
            # Fall through to raise TypeError
            pass
        # If none of the above, metaclasses are incompatible
        raise TypeError(
            f"metaclass conflict: {common_meta!r} and {this_meta!r} are not compatible"
        )
    return common_meta

def determineMetaclass(bases, explicit_mc=None):
    """
    Determine the most derived metaclass for a class definition.

    Parameters
    ----------
    bases : tuple of class
        Base classes for the new class.
    explicit_mc : type | None, optional
        Explicit metaclass passed via ``__metaclass__`` in Python 2
        or via the ``metaclass=`` keyword in Python 3.

    Returns
    -------
    type
        The metaclass that should be used to create the new class.
    """
    # Validate bases
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"Base {b!r} is not a class")

    # If a metaclass is explicitly supplied.
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("Explicit metaclass must be a type")
        for b in bases:
            if not issubclass(explicit_mc, type(b)):
                raise TypeError(
                    f"Explicit metaclass {explicit_mc.__name__} is not a subclass of {type(b).__name__}"
                )
        return explicit_mc

    # No explicit metaclass: pick the most derived one from the bases.
    if not bases:
        return type

    candidate = type(bases[0])
    for b in bases[1:]:
        m = type(b)
        if issubclass(candidate, m):
            continue
        if issubclass(m, candidate):
            candidate = m
        else:
            raise TypeError(
                f"Metaclass conflict: {candidate.__name__} and {m.__name__}"
            )
    return candidate

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit `__metaclass__`."""
    # Validate inputs
    if not isinstance(bases, (list, tuple)):
