def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.

    The function accepts a datetime instance and returns a string in a format
    commonly used by D* nodes: an ISO‑8601 UTC timestamp of the form
    ``YYYY-MM-DDTHH:MM:SSZ``.  If *dt* is ``None``, not a datetime,
    or raises any conversion error, an empty string is returned.

    Parameters
    ----------
    dt : datetime.datetime or None
        The datetime to format.  If it contains timezone information it
        will be converted to UTC.

    Returns
    -------
    str
        The formatted timestamp or an empty string on error.
    """
    try:
        import datetime
    except Exception:
        return ""

    if dt is None:
        return ""

    # Ensure dt is a datetime instance
    try:
        if not isinstance(dt, datetime.datetime):
            return ""
    except Exception:
        return ""

    try:
        # Normalize to UTC if tzinfo is present
        if dt.tzinfo is not None:
            dt_utc = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        else:
            dt_utc = dt
        return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    except Exception:
        return ""

