def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    Returns the Content-Type header value if available, otherwise None.
    """
    # Validate input
    if not isinstance(url, str) or not url.strip():
        return None

    try:
        import urllib.request
        import urllib.error
    except Exception:
        # urllib is not available
        return None

    try:
        # Prepare a HEAD request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            # urllib returns an email.message.Message for headers
            content_type = resp.info().get_content_type()
            if content_type:
                return content_type
            # Fallback to explicit header retrieval
            return resp.info().get('Content-Type')
    except (urllib.error.HTTPError, urllib.error.URLError, ValueError):
        # Handle URL errors, HTTP errors, or malformed URLs
        return None
    except Exception:
        # Catch-all for any unexpected errors
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    # Validate input
    if not isinstance(url, str) or not url.strip():
        raise ValueError("URL must be a non-empty string")
    try:
        from urllib.request import Request, urlopen
        from urllib.error import URLError, HTTPError
    except Exception as e:
        raise ImportError("Required modules could not be imported") from e

    req = Request(url, method='HEAD')
    try:
        with urlopen(req, timeout=10) as resp:
            content_type = resp.headers.get('Content-Type')
            return content_type
    except HTTPError as he:
        # HTTP errors contain response headers
        if he.headers:
            return he.headers.get('Content-Type')
        return None
    except URLError:
        return None
    except Exception:
        return None

