    return False

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    # Helper for JSON parsing
    def _parse_json(doc: str) -> dict:
        import json
        data = json.loads(doc)
        # Expected new format
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        # Links are stored under "_links"
        raw_links = data.get("_links", {})
        links = {}
        for rel, link_info in raw_links.items():
            if isinstance(link_info, dict):
                href = link_info.get("href")
                if href:
                    links[rel] = href
        return {"subject": subject, "aliases": aliases, "links": links}

    # Helper for old XRD parsing
    def _parse_xrd(doc: str) -> dict:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(doc)
        # The XRD namespace sometimes uses http://docs.oasis-open.org/wss/.. but we try no namespace too
        ns = {"xrd": "xri://$xrd*($v*2.0)"}
        subject_elem = root.find("xrd:Subject", ns) or root.find("Subject")
        subject = subject_elem.text if subject_elem is not None else None

        aliases = []
        for alias_elem in root.findall("xrd:Alias", ns) or root.findall("Alias"):
            if alias_elem.text:
                aliases.append(alias_elem.text)

        links = {}
        for link_elem in root.findall("xrd:Link", ns) or root.findall("Link"):
            rel = link_elem.get("rel")
            href = link_elem.get("href")
            if rel and href:
                links[rel] = href

        return {"subject": subject, "aliases": aliases, "links": links}

    if not isinstance(document, str):
        raise TypeError("document must be a string")

    doc = document.strip()
    if not doc:
        raise ValueError("empty document")

    # Try JSON first
    try:
        return _parse_json(doc)
    except Exception:
        pass

    # If JSON fails, try XRD
    try:
        return _parse_xrd(doc)
    except Exception as exc:
        raise ValueError(f"Unable to parse Diaspora webfinger document: {exc}") from exc

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    def _strip_ns(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    # Try JSON parsing first
    try:
        result = json.loads(document)
        if isinstance(result, dict):
            return result
    except Exception:
        pass  # fall back to XRD parsing

    # XRD (XML) parsing
    try:
        root = ET.fromstring(document)
        # Helper to find child ignoring namespace
        def find_child(tag_name):
            for child in root:
                if _strip_ns(child.tag) == tag_name:
                    return child
            return None

        def findall_children(tag_name):
            return [child for child in root if _strip_ns(child.tag) == tag_name]

        subject_elem = find_child('Subject')
        subject = subject_elem.text.strip() if subject_elem is not None and subject_elem.text else ''

        aliases = []
        for alias_elem in findall_children('Alias'):
            if alias_elem.text:
                aliases.append(alias_elem.text.strip())

        properties = {}
        for prop_elem in findall_children('Property'):
            name = prop_elem.attrib.get('name')
            if name and prop_elem.text:
                properties[name.strip()] = prop_elem.text.strip()

        links = []
        for link_elem in findall_children('Link'):
            rel = link_elem.attrib.get('rel', '').strip()
            href = link_elem.attrib.get('href', '').strip()
            type_ = link_elem.attrib.get('type', '').strip()
            if href:
                links.append({
                    'rel': rel,
                    'href': href,
                    'type': type_
                })

        return {
            'subject': subject,
            'aliases': aliases,
            'properties': properties,
            'links': links
        }
    except Exception:
        # If parsing fails, return empty dict
        return {}

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse a Diaspora webfinger response, which may be in either the new JSON format
    or the legacy XRD XML format.  The function returns a dictionary with the
    following structure:

        {
            'subject': <subject as string or None>,
            'links': [
                {'rel': <rel>, 'href': <href>, 'type': <type or None>},
                ...
            ]
        }

    The function is tolerant to malformed input; if parsing fails for both
    formats an empty dictionary is returned.  Parsing errors are swallowed
    and not propagated to the caller.
    """
    if not document:
        return {}

    # Try JSON first (new format)
    try:
        import json
        data = json.loads(document)
        if not isinstance(data, dict):
            return {}
        subject = data.get('subject')
        links = []
        for entry in data.get('links', []):
            if isinstance(entry, dict):
                link_dict = {
                    'rel': entry.get('rel'),
                    'href': entry.get('href'),
                    'type': entry.get('type')
                }
                if link_dict['rel'] and link_dict['href']:
                    links.append(link_dict)
        return {'subject': subject, 'links': links}
    except Exception:
        pass

    # Fall back to XRD XML (old format)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        # The XRD spec may contain a default namespace. We'll ignore it.
        def strip_ns(tag):
            return tag.split('}', 1)[-1] if '}' in tag else tag

        subject_elem = None
        # Subject may be directly under root or nested
        for elem in root.iter():
            if strip_ns(elem.tag) == 'subject':
                subject_elem = elem
                break
        subject = subject_elem.text if subject_elem is not None else None

        links = []
        for link_elem in root.iter():
            if strip_ns(link_elem.tag) == 'link':
                rel = link_elem.attrib.get('rel')
                href = link_elem.attrib.get('href')
                ltype = link_elem.attrib.get('type')
                if rel and href:
                    links.append({'rel': rel, 'href': href, 'type': ltype})
        return {'subject': subject, 'links': links}
    except Exception:
        # Both parsing attempts failed
        return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse a Diaspora webfinger document which may be in JSON (new) or XRD (old) format.
    Returns a dictionary with keys: 'subject' (str), 'aliases' (list of str), and
    'links' (list of dicts with keys 'rel', 'type', and 'href').
    Raises ValueError if the document cannot be parsed.
    """
    import json
    import xml.etree.ElementTree as ET

    # Attempt to parse as JSON first
    try:
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        subject = data.get("subject") or data.get("Subject")
        if subject is None:
            raise ValueError("Missing 'subject' field in JSON webfinger")
        # Aliases may be supplied under several keys; normalize to list
        aliases = (
            data.get("aliases") or
            data.get("Aliases") or
            data.get("Alias") or
            []
        )
        if not isinstance(aliases, list):
            aliases = [aliases]
        links = data.get("links") or data.get("Links") or []
        if not isinstance(links, list):
            links = [links]
        return {"subject": subject, "aliases": list(aliases), "links": list(links)}
    except (json.JSONDecodeError, TypeError):
        # Fall back to XML (XRD)
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        try:
            root = ET.fromstring(document)
        except ET.ParseError as e:
            raise ValueError(f"Cannot parse webfinger document: {e}") from e

        def _text(elem, tag, namespace=None):
            if namespace:
                search = root.find(f".//{namespace}:{tag}", ns)
            else:
                search = root.find(f".//{tag}")
            return search.text if search is not None else ""

        def _list_elements(tag, namespace=None):
            if namespace:
                elems = root.findall(f".//{namespace}:{tag}", ns)
            else:
                elems = root.findall(f".//{tag}")
            return [e.text for e in elems if e.text]

        # Try without namespace if the root doesn't contain it
        if root.tag.startswith("{"):
            namespace = "{http://docs.oasis-open.org/ns/xri/xrd-1.0}"
        else:
            namespace = None

        subject = _text("Subject", "xrd", namespace) if namespace else _text("Subject")
        if not subject:
            # Try the older attribute name "acct:" format
            subject = _text("subject") or _text("Subject")

        aliases = _list_elements("Alias", "xrd", namespace) if namespace else _list_elements("Alias")

        links = []
        if namespace:
            for link in root.findall(".//xrd:Link", ns):
                href = link.attrib.get("href")
                if href:
                    links.append(
                        {
                            "rel": link.attrib.get("rel"),
                            "type": link.attrib.get("type"),
                            "href": href,
                        }
                    )
        else:
            for link in root.findall(".//Link"):
                href = link.attrib.get("href")
                if href:
                    links.append(
                        {
                            "rel": link.attrib.get("rel"),
                            "type": link.attrib.get("type"),
                            "href": href,
                        }
                    )

        return {"subject": subject, "aliases": aliases, "links": links}

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str):
        raise TypeError("document must be a string")
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        obj = json.loads(document)
        if isinstance(obj, dict):
            return obj
    except json.JSONDecodeError:
        pass  # fall back to XML

    # Try XML / XRD
    try:
        root = ET.fromstring(document)
    except ET.ParseError as exc:
        raise ValueError(f"Unable to parse webfinger document as JSON or XML: {exc}")

    # Helper to strip XML namespace
    def _strip_ns(tag: str) -> str:
        return tag.split("}", 1)[1] if "}" in tag else tag

    # Find subject
    subject_elem = root.find(".//{*}Subject")
    if subject_elem is None:
        subject_elem = root.find(".//Subject")
    subject = subject_elem.text.strip() if subject_elem is not None and subject_elem.text else None

    links = []
    for link_elem in root.findall(".//{*}Link"):
        link: dict = {}
        for attr in ["rel", "type", "href"]:
            if attr in link_elem.attrib:
                link[attr] = link_elem.attrib[attr]
        # Parse nested <Properties> if present
        props_elem = link_elem.find(".//{*}Properties") or link_elem.find(".//Properties")
        if props_elem is not None:
            props: dict = {}
            for prop in props_elem:
                key = _strip_ns(prop.tag)
                if len(prop):
                    # Nested elements: flatten to dict of child tags
                    child_dict = {}
                    for child in prop:
                        child_key = _strip_ns(child.tag)
                        child_dict[child_key] = child.text.strip() if child.text else None
                    props[key] = child_dict
                else:
                    props[key] = prop.text.strip() if prop.text else None
            link["properties"] = props
        links.append(link)

    return {"subject": subject, "links": links}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    if not handle or '@' not in handle:
        return None
    user, domain = handle.split('@', 1)
    resource = f'acct:{handle}'
    try:
        parse_mod = __import__('urllib.parse')
        resource_enc = parse_mod.quote_plus(resource)
        url = f'https://{domain}/.well-known/webfinger?resource={resource_enc}'
        req_mod = __import__('urllib.request')
        req = req_mod.Request(url, headers={'Accept': 'application/json'})
        with req_mod.urlopen(req, timeout=5) as resp:
            # Some responses may not have getcode(), so use code attribute if absent
            code = getattr(resp, 'getcode', lambda: resp.code)()
            if code == 200:
                data = resp.read()
                try:
                    return data.decode('utf-8', errors='replace')
                except Exception:
                    return data.decode('latin1', errors='replace')
    except Exception:
        return None
    return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
