            return None

        # Construct the resource parameter
        resource = f'acct:{handle}'
        encoded_resource = urllib.parse.quote(resource, safe='')

        # Candidate URLs: first try HTTPS, then fallback to HTTP
        for scheme in ('https', 'http'):
            url = f'{scheme}://{host}/.well-known/webfinger?resource={encoded_resource}'
