    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json
    import xml.etree.ElementTree as ET
    from urllib.error import URLError, HTTPError

    # Validate input handle
    if not isinstance(handle, str):
        raise ValueError("handle must be a string in the format 'user@domain'")
    if '@' not in handle:
        raise ValueError("handle must contain '@' separating local part and domain")

    # Build the WebFinger resource URL
    local_part, domain = handle.split('@', 1)
    resource = f"acct:{local_part}@{domain}"
    query_params = urllib.parse.urlencode({'resource': resource})
    webfinger_url = f"https://{domain}/.well-known/webfinger?{query_params}"

    # Prepare request with appropriate headers
    req = urllib.request.Request(
        webfinger_url,
        headers={'Accept': 'application/json, application/xrd+xml'})

    try:
        with urllib.request.urlopen(req, timeout=10) as response:
            content_type = response.headers.get('Content-Type', '')
            raw_data = response.read()
    except HTTPError as e:
        raise RuntimeError(f"HTTP error {e.code} retrieving WebFinger document: {e.reason}") from e
    except URLError as e:
        raise RuntimeError(f"Failed to connect to WebFinger URL: {e.reason}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error retrieving WebFinger document: {e}") from e

    # Parse the response data
    def _parse_xml(data):
        try:
            root = ET.fromstring(data)
        except ET.ParseError as e:
            raise ValueError("Failed to parse XML WebFinger document") from e
        # Simple conversion: map tag names to attributes or text
        result = {}
        for child in root:
            tag = child.tag
            if child.attrib:
                result[tag] = child.attrib
            else:
                result[tag] = child.text
        return result

    try:
        if 'application/json' in content_type.lower():
            return json.loads(raw_data.decode('utf-8'))
        elif 'xml' in content_type.lower():
            return _parse_xml(raw_data)
        else:
            # Try JSON first as fallback
            return json.loads(raw_data.decode('utf-8'))
    except json.JSONDecodeError as e:
        raise ValueError("WebFinger document is not valid JSON") from e
    except Exception as e:
        raise RuntimeError(f"Failed to parse WebFinger document: {e}") from e

