    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Import requests lazily to avoid global import if not needed
    try:
        import requests
    except Exception as exc:
        # If requests is unavailable, immediately return error
        return (None, exc)

    # Normalize method name to lower case; default to "post"
    method = method.lower() if isinstance(method, str) else "post"
    try:
        # Determine the request method
        if method == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            # Fallback to generic request method for non-POST values
            response = requests.request(method=method, url=url, data=data, timeout=timeout, *args, **kwargs)
        # Return status code; None if response is somehow None
        return (response.status_code if response is not None else None, None)
    except requests.RequestException as e:
        # For request-specific exceptions, return the exception instance
        return (None, e)
    except Exception as e:
        # Catch any other unforeseen exception to avoid crashing
        return (None, e)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    file_names = []
    try:
        if not isinstance(settings_dirs, (list, tuple)):
            settings_dirs = (settings_dirs,)
        for dir_path in settings_dirs:
            if not isinstance(dir_path, str):
                continue
            os_module = globals().get('os')
            if not os_module:
                continue
            try:
                if os_module.path.isdir(dir_path):
                    for entry in os_module.listdir(dir_path):
                        if spec_option is None or entry.endswith(spec_option):
                            file_names.append(entry)
