def list_of_file_names(settings_dirs, spec_option=None):
    """Create a new IniType complex type"""
    # Validate input
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple of directory paths.")
    # Import required modules via builtin __import__ to avoid explicit imports
    os = __import__("os")
    fnmatch = __import__("fnmatch") if spec_option and isinstance(spec_option, str) else None

    matching_files = []
    for dir_path in settings_dirs:
        # Skip if not a directory
        try:
            if not os.path.isdir(dir_path):
                continue
        except Exception:
            # If path can't be inspected, skip
            continue
        try:
            for entry in os.listdir(dir_path):
                # Ensure we only consider files, not subdirectories
                full_path = os.path.join(dir_path, entry)
                try:
                    if not os.path.isfile(full_path):
                        continue
                except Exception:
                    continue

                # Filtering based on spec_option
                if spec_option is None:
                    match = True
                elif callable(spec_option):
                    try:
                        match = bool(spec_option(entry))
                    except Exception:
                        match = False
                elif isinstance(spec_option, str):
                    try:
                        match = fnmatch.fnmatch(entry, spec_option)
                    except Exception:
                        match = False
                else:
                    match = False

                if match:
                    matching_files.append(entry)
        except (OSError, PermissionError):
            # Skip directories we cannot read
            continue
    return matching_files

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file names found in the directories specified by ``settings_dirs``.
    ``settings_dirs`` should be an iterable of directory paths. ``spec_option`` determines
    which files are selected:

    * ``None`` – all files are returned.
    * ``str`` – treated as a glob pattern (e.g. ``*.ini``).
    * ``callable`` – a predicate that receives a file name and returns ``True`` iff the
      file should be included.
    * ``list``/``tuple`` – interpreted as a list of file extensions (with or without a
      leading dot, case‑insensitive). Only files whose extension matches one of the
      extensions are returned.

    The function is tolerant to non‑existent directories and unreadable entries – they
    are simply ignored.  Errors unrelated to the file system (such as a bad ``spec_option``)
    will raise a ``TypeError``.  The returned names do not contain directory paths.

    Example::

        dirs = ['/path/one', '/path/two']
        files = list_of_file_names(dirs, '*.cfg')
        # files contains only the names of .cfg files found in the two directories.

    :param settings_dirs: An iterable of directory path strings.
    :param spec_option: None, str, callable, or list/tuple of extensions.
    :return: List of matching file names (strings).
    :raises TypeError: If inputs are of an unexpected type.
    """
    # Input validation
    try:
        iter(settings_dirs)
    except TypeError:
        raise TypeError("settings_dirs must be an iterable of directory paths")

    # Determine filter function
    filter_func = None
    if spec_option is None:
        filter_func = lambda name: True
    elif callable(spec_option):
        filter_func = spec_option
    elif isinstance(spec_option, str):
        # use glob-style pattern
        import fnmatch

        def filter_func(name):
            return fnmatch.fnmatch(name, spec_option)
    elif isinstance(spec_option, (list, tuple)):
        # treat as extensions list
        exts = []
        for ext in spec_option:
            if not isinstance(ext, str):
                raise TypeError("All extensions in spec_option must be strings")
            if not ext.startswith('.'):
                ext = '.' + ext
            exts.append(ext.lower())

        def filter_func(name):
            return any(name.lower().endswith(ext) for ext in exts)
    else:
        raise TypeError("spec_option must be None, a string pattern, a callable, or a list/tuple of extensions")

    matched_files = []
    for dir_path in settings_dirs:
        # Skip non-string paths
        if not isinstance(dir_path, str):
            continue
        try:
            entries = os.listdir(dir_path)
        except (OSError, FileNotFoundError, NotADirectoryError):
            # Directory cannot be accessed – skip it
            continue
        for entry in entries:
            full_path = os.path.join(dir_path, entry)
            try:
                if not os.path.isfile(full_path):
                    continue
            except OSError:
                # Cannot determine if it's a file – skip it
                continue
            try:
                if filter_func(entry):
                    matched_files.append(entry)
            except Exception:
                # Any error in filter_func means skip the file
                continue

    return matched_files

