    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dictionary")
    # Helper to merge two dictionaries recursively
    def _merge_dict(dest, src):
        for k, v in src.items():
            if isinstance(v, dict) and isinstance(dest.get(k), dict):
                _merge_dict(dest[k], v)
            else:
                dest[k] = v
    # Find all items that contain an 'include' directive
    for key, value in list(parser_dict.items()):
        if isinstance(value, dict) and 'include' in value:
            include_val = value.pop('include')
            if not isinstance(include_val, dict):
                raise TypeError(f"Include directive for key '{key}' must be a dictionary, got {type(include_val).__name__}")
            # If the include directive also contains nested include directives, resolve them first
            self._include_groups(include_val)
            # Merge the included dictionary into the current level
            _merge_dict(parser_dict, include_val)
    # Recursively resolve include directives in nested dictionaries
    for val in parser_dict.values():
        if isinstance(val, dict):
            self._include_groups(val)

