        # Handle both dict-like and iterable containers
        if isinstance(arg_container, dict):
            items = arg_container.items()
        else:
            items = [(getattr(a, "name", None), a) for a in arg_container]
        for name, arg_spec in items:
            if name is None:
                continue
            # Prefer a 'default' attribute; fall back to 'get_default' method if present
            if hasattr(arg_spec, "default"):
                defaults[name] = arg_spec.default
            elif hasattr(arg_spec, "get_default") and callable(arg_spec.get_default):
                try:
