def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args: the dict of arguments from files
        """
        # Ensure we have dictionaries to work with.
        if not isinstance(cli_args, dict) or not isinstance(answer_file_args, dict):
            raise TypeError("cli_args and answer_file_args must be dictionaries")

        # Retrieve the set or mapping of deprecated arguments. It can be either a
        # mapping from old to new argument names or a simple iterable of names.
        # If nothing is defined, nothing to do.
        deprecated = getattr(self, "deprecated_args", None)
        if not deprecated:
            return

        # Normalize to a mapping. If it is a set/list we assume the deprecation
        # suggests no new name (warning only).
        if isinstance(deprecated, (set, list, tuple)):
            deprecated_map = {name: None for name in deprecated}
        else:
            deprecated_map = dict(deprecated)

        # Helper to produce a message for a single deprecation usage.
        def _warn(old, new, source):
            msg = f"Argument '{old}' is deprecated"
            if new:
                msg += f" and should be replaced with '{new}'"
            msg += f" (provided by {source})."
            # Prefer a warning method if available on the instance.
            # If none exist, fall back to the built‑in warning.
            warn_method = getattr(self, "warn", None)
            if callable(warn_method):
                warn_method(msg)
            else:
                # The static module `warnings` is available without imports
                # in CPython, but to avoid pulling it in, just print.
                print(msg)

        # Check CLI arguments.
        for arg in cli_args:
            if arg in deprecated_map:
                _warn(arg, deprecated_map[arg], "CLI")

        # Check answer file arguments.
        for arg in answer_file_args:
            if arg in deprecated_map:
                _warn(arg, deprecated_map[arg], "answer file")

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Fetch deprecated arguments definitions from the instance.
    # It can be either a set of argument names or a mapping from old names to recommended substitutes.
    deprecated = getattr(self, "deprecated_args", {})
    # Additional mapping may be stored separately.
    mapping = getattr(self, "deprecated_mapping", {})
    messages = []
    seen = set()

    def _add_message(arg, new_name=None, sources=None):
        if arg in seen:
            return
        seen.add(arg)
        base_msg = f"Argument '{arg}' is deprecated."
        if new_name:
            base_msg += f" Use '{new_name}' instead."
        elif arg in mapping:
            base_msg += f" Use '{mapping[arg]}' instead."
        if sources:
            base_msg += f" Detected in {', '.join(sources)}."
        messages.append(base_msg)

    if isinstance(deprecated, dict):
        # Legacy format: mapping old -> new names
        for old_arg, new_name in deprecated.items():
            src = []
            if old_arg in cli_args:
                src.append("cli")
            if old_arg in answer_file_args:
                src.append("answer file")
            if src:
                _add_message(old_arg, new_name=new_name, sources=src)
    else:
        # Treat as a set of deprecated argument names
        for arg in deprecated:
            src = []
            if arg in cli_args:
                src.append("cli")
            if arg in answer_file_args:
                src.append("answer file")
            if src:
                _add_message(arg, new_name=None, sources=src)

    if messages:
        # Prefer printing to stderr if available; fall back to stdout.
        try:
            import sys
            out_stream = sys.stderr
        except Exception:
            out_stream = None
        if out_stream:
            for msg in messages:
                print(msg, file=out_stream)
        else:
            for msg in messages:
                print(msg)

