                    return spec
            # Object form: attribute 'name'
            if hasattr(opt, "name") and opt.name == argument_name:
                return opt

    # If we reach here, the option was not found
    raise KeyError(
        f"Option '{argument_name}' not found in command '{command_name}'."
    )

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # validate inputs
    if command_name is None or argument_name is None:
        raise TypeError("Both command_name and argument_name must be provided")
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")

    # Retrieve the option specification from the internal registry.
    # The expected internal structure is a mapping of command names to dictionaries
    # of option names and their corresponding specifications.
    options_registry = getattr(self, "_options", None)
    if options_registry is None or not isinstance(options_registry, dict):
        raise RuntimeError("Option registry (_options) is not initialized correctly")

    try:
        command_opts = options_registry[command_name]
    except KeyError as exc:
        raise KeyError(f"Command '{command_name}' does not exist in the option registry") from exc

    if not isinstance(command_opts, dict):
        raise RuntimeError(f"The options for command '{command_name}' must be a dictionary")

    try:
        spec = command_opts[argument_name]
    except KeyError as exc:
        raise KeyError(
            f"Option '{argument_name}' not found for command '{command_name}'"
        ) from exc

    return spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types and values
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")
    if not isinstance(argument_name, str) or not argument_name:
        raise ValueError("argument_name must be a non-empty string")
    try:
        # Retrieve the command configuration
        command_cfg = None
        try:
            command_cfg = self.commands.get(command_name)
        except AttributeError:
            raise AttributeError("The object has no attribute 'commands'")
        if command_cfg is None:
            raise ValueError(f"Command '{command_name}' does not exist")
        # Determine where options/arguments are stored
        options_container = getattr(command_cfg, "options", None)
        if options_container is None:
            options_container = getattr(command_cfg, "arguments", None)
        if options_container is None:
            raise ValueError(f"Command '{command_name}' has no options/arguments defined")
        # Get the option spec
        spec = options_container.get(argument_name)
        if spec is None:
            raise ValueError(f"Option '{argument_name}' not found for command '{command_name}'")
        return spec
    except Exception as exc:
        # Wrap unexpected exceptions for clarity
        raise ValueError(f"Error retrieving spec for command '{command_name}', option '{argument_name}': {exc}") from exc

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate inputs
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    # Attempt to retrieve the spec from the stored option specifications
    try:
        return self._option_specs[command_name][argument_name]
    except KeyError as exc:
        raise ValueError(
            f"Specification for command '{command_name}' "
            f"and option '{argument_name}' not found"
        ) from exc
    except AttributeError as exc:
        raise RuntimeError(
            "Option specifications have not been initialized for this instance."
        ) from exc
    except Exception as exc:  # pragma: no cover
        raise RuntimeError(f"Unexpected error retrieving option spec: {exc}") from exc

def get_silent_args(self, args):
    """
    Return a list of argument names that are considered "silent".
    Arguments that start with an underscore (e.g., '_private') are treated as silent.
    The input `args` can be a dictionary mapping argument names to values, or an iterable of
    (name, value) pairs. If the input type does not match either expected form, an empty
    list is returned.

    :param args: The received arguments, typically a dictionary or an iterable of name/value pairs.
    :return: list of silent argument names.
    """
    silent_args = []
    try:
        # If args is a dictionary, check keys
        if isinstance(args, dict):
            for key in args:
                if isinstance(key, str) and key.startswith("_"):
                    silent_args.append(key)
        else:
            # Try treating args as an iterable of pairs (name, value)
            for item in args:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    name, _ = item
                    if isinstance(name, str) and name.startswith("_"):
                        silent_args.append(name)
    except Exception:
        # In case of unexpected structure or errors, return empty list
        return []
    return silent_args

def get_silent_args(self, args):
        """
        list of silenced argument

        :param args: The received arguments.
        :return: list, slienced argument names
        """
        try:
            if args is None:
                return []

            silent_names = []
            silence_patterns = ('--silent', '--quiet', '-s', '-q')

            for item in args:
                if isinstance(item, str):
                    for pattern in silence_patterns:
                        if item.startswith(pattern):
                            silent_names.append(item)
                            break
                elif isinstance(item, (list, tuple)):
                    # allow tuple/list like ('--silent', value)
                    if item and isinstance(item[0], str):
                        for pattern in silence_patterns:
                            if item[0].startswith(pattern):
                                silent_names.append(item[0])
                                break
            return silent_names
        except Exception:
            # In case of unexpected input or errors, return an empty list
            return []

def get_silent_args(self, args):
    """
    Retrieve a list of argument names that should be treated as silent (e.g., hidden or ignored).

    Parameters
    ----------
    args : dict or list or tuple
        The received arguments. Can be a dictionary of argument names to values,
        a list of argument names, or a list/tuple of (name, value) pairs.

    Returns
    -------
    list
        A list of argument names considered silent.
    """
    silent_args = []

    # Helper to determine if a key should be considered silent
    def is_silent_key(key):
        if not isinstance(key, str):
            return False
        # Treat keys starting with '_' or 'internal_' as silent
        lower_key = key.lower()
        return key.startswith('_') or lower_key.startswith('internal_')

    if args is None:
        return silent_args

    try:
        if isinstance(args, dict):
            # Use dictionary keys directly
            for key in args:
                if is_silent_key(key):
                    silent_args.append(key)
        elif isinstance(args, (list, tuple)):
            # If each element is a pair, use the first item as the key
            if all(isinstance(item, (tuple, list)) and len(item) == 2 for item in args):
                for key, _ in args:
                    if is_silent_key(key):
                        silent_args.append(key)
            else:
                # Assume it's a list of keys
                for key in args:
                    if is_silent_key(key):
                        silent_args.append(key)
        else:
            # Unsupported type
            raise TypeError(f"Unsupported args type: {type(args)}")
    except Exception:
        # In case of unexpected errors, return whatever has been collected so far
        pass

    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure the class defines which arguments are required
    if not hasattr(self, "required_args"):
        raise AttributeError("The instance has no attribute 'required_args' to validate against.")
    required = getattr(self, "required_args")
    if not isinstance(required, (list, set, tuple)):
        raise TypeError("Attribute 'required_args' must be a list, set, or tuple of argument names.")
    # Normalize arguments container for checking
    missing = []
    if args is None:
        raise TypeError("The 'args' parameter cannot be None.")
    if isinstance(args, dict):
        for key in required:
            if key not in args or args[key] is None:
                missing.append(key)
    else:
        # Try attribute access for non-mapping objects (e.g., argparse.Namespace)
        for key in required:
            if not hasattr(args, key) or getattr(args, key) is None:
                missing.append(key)
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    try:
        # Ensure args is a dictionary
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary")

        # Retrieve the list of required arguments; default to empty list if not defined
        required = getattr(self, "required_args", [])

        # Collect any missing or empty required arguments
        missing = []
        for key in required:
            val = args.get(key, None)
            # Treat None or empty string/blank string as missing
            if val is None or (isinstance(val, str) and not val.strip()):
                missing.append(key)

        if missing:
            raise ValueError(f"Missing required argument(s): {', '.join(missing)}")
        return True
    except Exception:
        # Propagate any exception to the caller
        raise

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a mapping
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary mapping argument names to values")

    # Retrieve the required argument list from the instance, using several common
    # attribute names as fallbacks.
    required = getattr(self, "required_args", None)
    if required is None:
        required = getattr(self, "required", None)
    if required is None:
        required = getattr(self, "required_parameters", [])

    if not isinstance(required, (list, tuple, set)):
        raise TypeError("The instance must have an attribute 'required_args', 'required', "
                        "or 'required_parameters' that is an iterable of argument names")

    # Identify any missing required arguments.
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Helper to evaluate a requirement condition against the provided args.
        def _evaluate(cond, available):
            if isinstance(cond, str):
                # Try to evaluate an expression; fall back to simple lookup.
                try:
                    return bool(
                        eval(cond, {"__builtins__": None}, available)
                    )
                except Exception:
                    return bool(available.get(cond))
            # If the condition is not a string, treat truthiness directly.
            return bool(cond)

        # Normalise the args into a mapping for easy lookup.
        arg_map = {}
        if isinstance(args, dict):
            arg_map = args
        elif isinstance(args, list):
            for item in args:
                if isinstance(item, (tuple, list)) and len(item) == 2:
                    key, value = item
                    arg_map[key] = value

        if not isinstance(options_spec, (list, tuple)):
            raise ValueError(
                "options_spec must be a list or tuple of option spec dicts"
            )

        required = []
        for opt in options_spec:
            if not isinstance(opt, dict):
                continue
            cond = opt.get("required_when")
            if cond is None:
                continue
            try:
                # If the condition is a list or tuple of multiple checks, any True qualifies.
                if isinstance(cond, (list, tuple)):
                    matched = any(_evaluate(c, arg_map) for c in cond)
                else:
                    matched = _evaluate(cond, arg_map)
            except Exception:
                # If evaluation fails, skip this option.
                matched = False
            if matched:
                name = opt.get("name")
                if name:
                    required.append(name)
        return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Guard against non-iterable options_spec
    if not isinstance(options_spec, (list, tuple)):
        return []

    conditional_args = []
    for opt in options_spec:
        if not isinstance(opt, dict):
            continue
        required_when = opt.get("required_when")
        if required_when is None:
            continue

        condition_met = False
        # Evaluate the condition
        try:
            if callable(required_when):
                # If it's a callable, invoke it with the args dict
                condition_met = bool(required_when(args))
            else:
                # Assume it's a string expression; evaluate in a restricted context
                # Provide command_name and args to the expression
                eval_context = {"args": args, "command_name": command_name, "__builtins__": {}}
                condition_met = bool(eval(required_when, {}, eval_context))
        except Exception:
            # If evaluation fails, treat the condition as not met
            condition_met = False

        if condition_met:
            # Gather argument names listed in this option spec
            arguments = opt.get("arguments")
            if isinstance(arguments, (list, tuple)):
                # Strip any falsy entries
                filtered = [arg for arg in arguments if arg]
                conditional_args.extend(filtered)
            elif isinstance(arguments, str):
                conditional_args.append(arguments)

    # Return unique names preserving order
    seen = set()
    unique_args = []
    for arg in conditional_args:
        if arg and arg not in seen:
            seen.add(arg)
            unique_args.append(arg)
    return unique_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    conditionally_required = []
    if not options_spec:
        return conditionally_required
    for opt in options_spec:
        name = opt.get("name")
        if not name:
            continue
        cond = opt.get("required_when")
        if cond is None:
            continue
        try:
            if callable(cond):
                result = cond(args)
            elif isinstance(cond, str):
                # Evaluate the string condition within the context of provided args.
                # The condition may reference keys in ``args`` directly.
                result = eval(cond, {}, args)
            else:
                # Fallback: treat as truthy value.
                result = bool(cond)
            if result:
                conditionally_required.append(name)
        except Exception:
            # If the condition cannot be evaluated, ignore it safely.
            continue
    return conditionally_required

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        # validate inputs
        if not isinstance(options_spec, (list, tuple)):
            raise TypeError("options_spec must be a list or tuple of option specs")
        if not isinstance(args, dict):
            # if args is not a dict, converting it to one might not make sense,
            # so just treat it as empty to avoid false positives
            args = {}

        matched = []

        for opt in options_spec:
            # Each option spec is expected to be a dict with at least a 'name' key.
            opt_name = opt.get('name')
            if not opt_name:
                continue

            cond = opt.get('required_when')
            if cond is None:
                continue

            try:
                # Condition can be a callable, a str, or an iterable of strings.
                if callable(cond):
                    # Callable is expected to accept the args dict and return bool.
                    if cond(args):
                        matched.append(opt_name)
                elif isinstance(cond, str):
                    if cond in args:
                        matched.append(opt_name)
                elif isinstance(cond, (list, tuple, set)):
                    if all(item in args for item in cond):
                        matched.append(opt_name)
                else:
                    # Unsupported condition type; ignore.
                    continue
            except Exception:
                # If evaluating the condition raises an exception, skip it.
                # Logging of the exception can be added if a logger is available.
                continue

        return matched

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    Return a list of argument names that have a ``required_when`` condition satisfied.

    Parameters
    ----------
    command_name : str
        The name of the command being parsed.
    options_spec : Iterable[Mapping] or Iterable[object]
        A collection of option specifications. Each spec may contain a
        ``required_when`` key whose value can be:

        * a callable that receives the ``args`` mapping and returns a bool.
        * a sequence of conditions.  Each condition can be:

          * a two‑tuple ``(key, value)`` meaning ``args[key] == value``.
          * a single key name meaning ``bool(args[key])``.
        * a boolean value (``True`` for always required).

    args : Mapping
        The parsed arguments, typically a dict mapping argument names to values.

    Returns
    -------
    list
        A list of argument names whose ``required_when`` condition evaluated to
        ``True``.
    """
    # Ensure args is a mapping; if not, try to cast
    if not isinstance(args, (dict,)):
        try:
            args = dict(args)
        except Exception:
            args = {}

    condition_args = []

    for opt in options_spec:
        # Retrieve option name flexibly
        name = None
        if isinstance(opt, dict):
            name = opt.get("name") or opt.get("arg") or opt.get("option")
            cond = opt.get("required_when")
        else:
            # Attempt attribute access for objects
            name = getattr(opt, "name", None) or getattr(opt, "arg", None)
            cond = getattr(opt, "required_when", None)

        if not name or cond is None:
            continue

        try:
            # Evaluate condition
            if callable(cond):
                matched = bool(cond(args))
            elif isinstance(cond, (list, tuple)):
                matched = True
                for c in cond:
                    if isinstance(c, (list, tuple)):
                        if len(c) == 2:
                            key, val = c
                            if args.get(key) != val:
                                matched = False
                                break
                        else:
                            # Treat single key within tuple/list
                            key = c[0] if c else None
                            if not args.get(key, False):
                                matched = False
                                break
                    else:
                        # Single key string or value
                        if not args.get(c, False):
                            matched = False
                            break
            else:
                # Boolean or other truthy values
                matched = bool(cond)
        except Exception:
            matched = False

        if matched:
            condition_args.append(name)

    return condition_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :raises TypeError: If args is not a mapping.
    :raises ValueError: If an argument value exceeds its specified maximum length.
    """
    # Ensure args is a mapping (dict-like)
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

    # Attempt to retrieve length specifications from the instance.
    # Convention: subclass may define self.arg_lengths as a dict mapping argument names
    # to maximum allowed length (int), or provide a method get_arg_length(name).
    length_spec = None
    if hasattr(self, 'arg_lengths'):
        length_spec = getattr(self, 'arg_lengths')
    elif hasattr(self, 'get_arg_length') and callable(getattr(self, 'get_arg_length')):
        def get_spec(name):
            try:
                return self.get_arg_length(name)
            except Exception:
                return None
        length_spec = get_spec
    else:
        length_spec = None

    for key, value in args.items():
        # Determine expected maximum length
        # If length_spec is dict
        if isinstance(length_spec, dict):
            max_len = length_spec.get(key)
        # If length_spec is a callable that returns length
        elif callable(length_spec):
            try:
                max_len = length_spec(key)
            except Exception:
                max_len = None
        else:
            max_len = None

        # If no length specified, skip validation
        if max_len is None:
            continue

        # Only strings or collections have length
        try:
            actual_len = len(value)
        except Exception:
            # If value has no length, we cannot validate; skip
            continue

        if actual_len > max_len:
            raise ValueError(
                f"Argument '{key}' length {actual_len} exceeds allowed maximum of {max_len}"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Expect args to be a mapping of argument names to values.
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    # Retrieve argument specifications if available
    arg_specs = getattr(self, 'args_specs', {})

    for name, value in args.items():
        spec = arg_specs.get(name, {})
        max_len = spec.get('max_length')
        if max_len is None:
            continue  # No length restriction specified for this argument

        # Only enforce on string or list/tuple types; skip others
        if isinstance(value, (str, list, tuple)):
            if len(value) > max_len:
                raise ValueError(
                    f"Length of argument '{name}' ({len(value)}) exceeds "
                    f"maximum allowed length of {max_len}."
                )
        else:
            # For non-iterable types, convert to string to check length
            try:
                value_len = len(str(value))
                if value_len > max_len:
                    raise ValueError(
                        f"Length of argument '{name}' ({value_len}) exceeds "
                        f"maximum allowed length of {max_len}."
                    )
            except Exception:
                # If length cannot be determined, skip validation
                continue

def validate_length_args(self, args):
        """
        Check if value of arguments is not longer than length specified.

        :param args: The received arguments. Expected to be a mapping of argument names to values.
        :raises TypeError: If args is not a mapping or if no length specification is provided.
        :raises ValueError: If any argument's length exceeds the specified maximum.
        """
        # Validate input type
        if not isinstance(args, dict):
            raise TypeError("args must be a dict mapping argument names to values")

        # Retrieve length specifications if available
        # The attribute `_arg_lengths` should contain a mapping: name -> max_length
        length_specs = getattr(self, "_arg_lengths", None)
        if length_specs is None:
            # No length requirements defined; nothing to validate
            return
        if not isinstance(length_specs, dict):
            raise TypeError("Attribute `_arg_lengths` must be a dict of name -> max_length")

        # Track any violations
        violations = []

        for name, value in args.items():
            # Skip if no max length defined for this argument
            if name not in length_specs:
                continue
            # Skip None values (they are not considered as exceeding length)
            if value is None:
                continue
            max_len = length_specs[name]
            try:
                val_len = len(value)
            except Exception:
                # If value has no length property, skip validation
                continue

            if val_len > max_len:
                violations.append(
                    f"'{name}' length {val_len} exceeds maximum {max_len}"
                )

        if violations:
            raise ValueError("; ".join(violations))

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # It is assumed that the instance has an attribute `choices`
    # which is a mapping from argument names to an iterable of
    # allowed values (e.g. a list or a set).
    # If no such attribute exists, nothing to validate.
    try:
        expected_choices = getattr(self, 'choices', {})
        if not isinstance(expected_choices, dict):
            # If the attribute is not a dict, fall back to empty mapping.
            expected_choices = {}
    except Exception:
        expected_choices = {}

    for arg_name, value in args.items():
        # Skip arguments that are not defined as choice arguments
        if arg_name not in expected_choices:
            continue

        valid = expected_choices[arg_name]
        # Ensure valid is iterable
        try:
            valid_iter = iter(valid)
        except TypeError:
            raise TypeError(f"Choices for argument '{arg_name}' must be an iterable, got {type(valid).__name__}")

        # Convert to a set for efficient containment checks
        choices_set = set(valid_iter)
        if value not in choices_set:
            # Provide a clear error message
            raise ValueError(
                f"Invalid value for argument '{arg_name}': {value!r} "
                f"is not among the allowed choices: {sorted(choices_set)}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # args must be a mapping of argument names to values
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary mapping argument names to values")

    # If the class has no defined choices, nothing to validate
    if not hasattr(self, "choices") or not isinstance(self.choices, dict):
        return

    for arg_name, allowed_vals in self.choices.items():
        # Skip validation if the argument was not provided in args
        if arg_name not in args:
            continue

        val = args[arg_name]

        # Normalize allowed_vals to an iterable of allowed values
        if isinstance(allowed_vals, (list, tuple, set)):
            allowed = allowed_vals
        else:
            allowed = [allowed_vals]

        if val not in allowed:
            raise ValueError(
                f"Invalid value for choice argument '{arg_name}': {val!r}. "
                f"Allowed values are: {sorted(allowed)}"
            )

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments (dict or argparse.Namespace).
    :raises ValueError: If a provided choice value is not in the allowed set.
    :raises AttributeError: If the instance does not provide a 'choices' mapping.
    :returns: True if all choice arguments are valid.
    """
    if not hasattr(self, "choices"):
        raise AttributeError("Instance has no 'choices' attribute to validate against.")
    # Convert to dict if Namespace or similar
    if isinstance(args, dict):
        args_dict = args
    else:
        try:
            args_dict = vars(args)
        except TypeError:
            raise TypeError("Argument 'args' must be a dict or have a __dict__ attribute.")

    for arg_name, value in args_dict.items():
        if arg_name in self.choices:
            allowed = self.choices[arg_name]
            # Skip None values typically meaning 'not provided'
            if value is None:
                continue
            # Accept iterable values (e.g., ['a', 'b'])
            if isinstance(value, (list, tuple, set)):
                for v in value:
                    if v not in allowed:
                        raise ValueError(
                            f"Invalid value {v!r} for option '{arg_name}'. "
                            f"Allowed: {allowed}"
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid value {value!r} for option '{arg_name}'. "
                        f"Allowed: {allowed}"
                    )
    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if args is None:
        return
    if not isinstance(args, dict):
        raise TypeError("args must be a dict of argument names to values")
    # Retrieve the specification that may contain min/max bounds
    spec = getattr(self, "input_spec", None)
    if spec is None or not isinstance(spec, dict):
        # No specification provided; nothing to validate
        return
    for key, value in args.items():
        if key not in spec:
            # Argument not defined in the spec; skip validation
            continue
        arg_spec = spec[key]
        if not isinstance(arg_spec, dict):
            continue
        min_val = arg_spec.get("min")
        max_val = arg_spec.get("max")
        if min_val is None or max_val is None:
            # If one of the bounds is missing, skip validation for this argument
            continue
        try:
            if not (min_val <= value <= max_val):
                raise ValueError(
                    f"Argument '{key}'={value} out of range [{min_val}, {max_val}]"
                )
        except TypeError as exc:
            # Value cannot be compared to the bounds (e.g., different types)
            raise TypeError(
                f"Argument '{key}'={value} cannot be compared to bounds [{min_val}, {max_val}]"
            ) from exc

def validate_min_max_args(self, args):
    """
    Check if the value of each argument falls between its defined minimum and maximum values.

    Parameters
    ----------
    args : dict
        A dictionary where each key is the argument name and its value is
        another dictionary that must contain the key 'value' and may
        optionally contain the keys 'min' and 'max'. Example::

            {
                "temperature": {"value": 37, "min": 35, "max": 42},
                "pressure":   {"value": 5, "min": 1, "max": 10}
            }

    Returns
    -------
    bool
        True if all arguments satisfy their min/max constraints.

    Raises
    ------
    TypeError
        If `args` is not a dict or the inner structures are not dicts or the
        values cannot be interpreted as numbers.
    ValueError
        If a required 'value' key is missing or if any value is outside the
        specified bounds, or if `min` > `max`.
    """
    if not isinstance(args, dict):
        raise TypeError("Expected 'args' to be a dictionary of argument definitions.")

    def _to_number(v, name):
        if isinstance(v, (int, float)):
            return v
        try:
            return float(v)
        except Exception:
            raise TypeError(f"Value for argument '{name}' must be numeric; got {type(v).__name__}")

    for arg_name, arg_info in args.items():
        if not isinstance(arg_info, dict):
            raise TypeError(f"Argument definition for '{arg_name}' must be a dict.")

        if "value" not in arg_info:
            raise ValueError(f"Missing 'value' key for argument '{arg_name}'.")

        value = _to_number(arg_info["value"], arg_name)

        min_val = arg_info.get("min")
        max_val = arg_info.get("max")

        if min_val is not None:
            min_num = _to_number(min_val, arg_name)
            if max_val is not None and min_num > _to_number(max_val, arg_name):
                raise ValueError(f"Invalid range for argument '{arg_name}': min ({min_num}) > max ({max_val}).")
            if value < min_num:
                raise ValueError(f"Argument '{arg_name}' = {value} is less than minimum {min_num}.")

        if max_val is not None:
            max_num = _to_number(max_val, arg_name)
            if value > max_num:
                raise ValueError(f"Argument '{arg_name}' = {value} is greater than maximum {max_num}.")

    return True

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        Parameters
        ----------
        args : dict, list or tuple
            Expected to contain arguments with associated minimum and maximum
            values. For a dictionary, keys are argument names and values can
            be either a mapping with keys 'value', 'min', 'max' or a tuple/list
            of the form (value, min, max). For a list/tuple, each element can
            be a dict as above or a tuple/list of (value, min, max). 

        Raises
        ------
        ValueError
            If any argument's value is outside its bounds.
        TypeError
            If `args` is not a supported structure, or the argument format
            cannot be interpreted.
        """
        def _check_bounds(name, value, min_, max_):
            if min_ is None or max_ is None:
                return
            try:
                if value < min_ or value > max_:
                    raise ValueError(
                        f"Argument {name!r} with value {value} is outside bounds "
                        f"[{min_}, {max_}]"
                    )
            except TypeError as exc:
                raise TypeError(
                    f"Unable to compare value {value!r} with bounds "
                    f"{min_!r} and {max_!r} for argument {name!r}"
                ) from exc

        if args is None:
            return

        # Handle dict input
        if isinstance(args, dict):
            for key, val in args.items():
                if isinstance(val, dict):
                    value = val.get('value')
                    min_ = val.get('min')
                    max_ = val.get('max')
                else:
                    try:
                        value, min_, max_ = val
                    except Exception:
                        raise TypeError(
                            f"Unsupported argument format for key {key!r}"
                        )
                _check_bounds(key, value, min_, max_)

        # Handle list/tuple input
        elif isinstance(args, (list, tuple)):
            for idx, item in enumerate(args):
                if isinstance(item, dict):
                    value = item.get('value')
                    min_ = item.get('min')
                    max_ = item.get('max')
                else:
                    try:
                        value, min_, max_ = item
                    except Exception:
                        raise TypeError(
                            f"Unsupported argument format at index {idx}"
                        )
                _check_bounds(idx, value, min_, max_)

        else:
            raise TypeError("args must be a dict or list/tuple of argument values")

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str):
        raise TypeError(f"subcommand must be a string, got {type(subcommand).__name__}")
    if not isinstance(type_name, str):
        raise TypeError(f"type_name must be a string, got {type(type_name).__name__}")
    if not isinstance(option_name, str):
        raise TypeError(f"option_name must be a string, got {type(option_name).__name__}")
    if not isinstance(spec_option, dict):
        raise TypeError(f"spec_option must be a dict, got {type(spec_option).__name__}")

    # Inner class representing the complex argument type
    class ComplexArgumentType:
        def __init__(self, subcommand, type_name, option_name, spec_option):
            self.subcommand = subcommand
            self.type_name = type_name
            self.option_name = option_name
            self.spec_option = spec_option

        def __repr__(self):
            return (f"<ComplexArgumentType subcommand={self.subcommand!r} "
                    f"type_name={self.type_name!r} option_name={self.option_name!r}>")

        def parse(self, value):
            """
            Parse a string value into the desired complex type.  The spec_option
            may contain a 'type' key mapping to a callable responsible for
            performing the conversion.
            """
            type_func = self.spec_option.get('type', str)
            try:
                return type_func(value)
            except Exception as exc:
                raise ValueError(
                    f"Failed to parse value '{value}' for option '{self.option_name}' "
                    f"using type {type_func!r}: {exc}"
                ) from exc

    # Return an instance of the inner class
    return ComplexArgumentType(subcommand, type_name, option_name, spec_option)

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}
        # Accept dict or list/tuple of key/value pairs
        try:
            if isinstance(args, dict):
                args_dict = args
            else:
                # Try to convert to dict
                args_dict = dict(args)
        except Exception:
            # If unable to interpret, return empty dicts
            return ({}, {})
        for k, v in args_dict.items():
            # Treat keys beginning with '_' as control arguments
            if isinstance(k, str) and k.startswith("_"):
                control_args[k] = v
            # Treat keys beginning with 'custom_' as custom arguments
            elif isinstance(k, str) and k.startswith("custom_"):
                # custom args are kept separate but not returned per signature
                # we simply skip adding them to nested, as they are not standard
                # behaviour. They could be merged into nested if needed.
                continue
            else:
                nested_args[k] = v
        return (control_args, nested_args)

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # Helper to flatten potentially nested dictionaries
        def _flatten(d, parent_key="", sep="_"):
            items = {}
            if not isinstance(d, dict):
                return {parent_key: d} if parent_key else {}
            for k, v in d.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                if isinstance(v, dict):
                    items.update(_flatten(v, new_key, sep))
                else:
                    items[new_key] = v
            return items

        control_args = {}
        nested_args = {}

        try:
            if not isinstance(args, dict):
                # If args is not a dict we cannot process – return empty
                return control_args, nested_args

            # Flatten args so that nested structures become dot‑style keys
            flat_args = _flatten(args)

            for key, value in flat_args.items():
                # Control args are identified by a leading underscore
                if key.startswith("_"):
                    control_args[key] = value
                else:
                    nested_args[key] = value

        except Exception as exc:
            # Log exception if logging is set up, otherwise swallow and return empty dicts
            # (Depends on the environment – optional logging)
            # import logging
            # logging.getLogger(__name__).error("Error processing args: %s", exc)
            return control_args, nested_args

        return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into.
        :param extra_vars: Iterable of extra-vars; each item may be a ``dict`` or a string
            of the form ``key=value`` or ``key1=value1,key2=value2``.  If ``None`` no action
            is taken.  The function returns the updated dictionary.

        :raises TypeError: if ``vars_dict`` is not a dictionary or ``extra_vars`` contains
            unsupported types.
        :raises ValueError: if an entry in ``extra_vars`` cannot be parsed.
        """
        if not isinstance(vars_dict, dict):
            raise TypeError('vars_dict must be a dictionary')
        if extra_vars is None:
            return vars_dict

        # Ensure we can iterate over extra_vars
        try:
            extras = list(extra_vars)
        except TypeError:
            raise TypeError('extra_vars must be an iterable')

        for item in extras:
            if isinstance(item, dict):
                # Merge dictionary entries directly
                vars_dict.update(item)
            elif isinstance(item, str):
                # Split on commas to allow bulk assignments like 'a=1,b=2'
                parts = [p.strip() for p in item.split(',') if p.strip()]
                for part in parts:
                    if '=' not in part:
                        raise ValueError(f'Invalid extra var format "{part}". Expected "key=value".')
                    key, value = part.split('=', 1)
                    vars_dict[key] = value
            else:
                raise TypeError(f'Unsupported type {type(item).__name__} in extra_vars')

        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        if extra_vars is None:
            return vars_dict

        # Allow a single string or dict as extra_vars
        if isinstance(extra_vars, str):
            try:
                import json
                extra_vars = json.loads(extra_vars)
            except Exception:
                # Treat as a single var definition
                extra_vars = [extra_vars]
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict
        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError("extra_vars must be a list, tuple, dict, or string")

        def _convert_value(val_str):
            """Try to convert string to a Python literal."""
            # Handle quoted strings
            if (val_str.startswith('"') and val_str.endswith('"')) or \
               (val_str.startswith("'") and val_str.endswith("'")):
                return val_str[1:-1]
            # Handle null/None
            lower = val_str.lower()
            if lower in ("none", "null"):
                return None
            if lower == "true":
                return True
            if lower == "false":
                return False
            # Numbers
            try:
                if '.' in val_str:
                    return float(val_str)
                return int(val_str)
            except ValueError:
                pass
            # Fallback to original string
            return val_str

        for item in extra_vars:
            if not isinstance(item, str):
                # skip unsupported types quietly
                continue
            if '=' not in item:
                # Skip items without assignment
                continue
            key, val_str = item.split('=', 1)
            key = key.strip()
            val_str = val_str.strip()
            if not key:
                # Skip empty keys
                continue
            try:
                value = _convert_value(val_str)
            except Exception:
                # If conversion fails, keep the string as-is
                value = val_str
            vars_dict[key] = value

        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict

    def _merge_dict(d):
        for k, v in d.items():
            vars_dict[k] = v

    if isinstance(extra_vars, dict):
        _merge_dict(extra_vars)

    elif isinstance(extra_vars, str):
        # Treat a single string of key=value pairs separated by commas
        for pair in extra_vars.split(','):
            if '=' in pair:
                k, v = pair.split('=', 1)
                vars_dict[k.strip()] = v.strip()

    elif isinstance(extra_vars, (list, tuple)):
        for item in extra_vars:
            if isinstance(item, dict):
                _merge_dict(item)
            elif isinstance(item, str):
                for pair in item.split(','):
                    if '=' in pair:
                        k, v = pair.split('=', 1)
                        vars_dict[k.strip()] = v.strip()
            else:
                # Unsupported type within the list; silently ignore
                continue
    else:
        raise TypeError(
            "extra_vars must be None, a dict, a string, or a list/tuple of dicts and strings"
        )

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    from pathlib import Path
    import json

    # Validate playbook path
    playbook = Path(playbook_path)
    if not playbook.is_file():
        raise FileNotFoundError(f"Playbook file not found: {playbook_path}")

    # Build command list
    cmd = ["ansible-playbook", str(playbook)]

    # Verbosity
    if verbose:
        if not isinstance(verbose, int) or verbose < 0:
            raise ValueError(f"verbose must be a non‑negative integer, got {verbose}")
        # Add '-v', '-vv', '-vvv', etc.
        cmd.append("-" + "v" * verbose)

    # Extra vars
    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise TypeError(f"extra_vars must be a dict, got {type(extra_vars).__name__}")
        # Convert to JSON string; Ansible accepts JSON
        try:
            vars_json = json.dumps(extra_vars)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Failed to serialize extra_vars to JSON: {exc}") from exc
        cmd.extend(["--extra-vars", vars_json])

    # Additional ansible_args
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise TypeError(f"ansible_args must be a dict, got {type(ansible_args).__name__}")
        for key, val in ansible_args.items():
            # key should be a string that can be a flag
            if not isinstance(key, str):
                raise TypeError(f"ansible_args keys must be strings, got {type(key).__name__}")
            if not key.startswith("-"):
                key = "--" + key
            if val is None:
                cmd.append(key)
            else:
                # For bool values, only add flag if True
                if isinstance(val, bool):
                    if val:
                        cmd.append(key)
                else:
                    cmd.extend([key, str(val)])

    # Execute command
    try:
        import subprocess
        result = subprocess.run(cmd, capture_output=True, text=True, check=False)
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    # Prepare output
    output = {
        "stdout": result.stdout,
        "stderr": result.stderr,
        "returncode": result.returncode,
        "cmd": cmd
    }

    # If Ansible failed, raise an exception with the error details
    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook exited with return code {result.returncode}\n"
            f"Command: {' '.join(cmd)}\n"
            f"stdout:\n{result.stdout}\n"
            f"stderr:\n{result.stderr}"
        )

    return output

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """
    Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
        workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results as a dictionary containing stdout, stderr, and returncode
    """
    import json
    import subprocess
    import os

    # Validate input types
    if cli_args is None:
        cli_args = []
    if not isinstance(cli_args, list):
        # Attempt to split a single string into arguments
        if isinstance(cli_args, str):
            cli_args = cli_args.split()
        else:
            raise ValueError("cli_args must be a list or string")

    if vars_dict is None:
        vars_dict = {}
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    # Determine the working directory from the workspace object
    workspace_path = None
    if ir_workspace is not None:
        # Try common attribute/method names
        if hasattr(ir_workspace, "get_path") and callable(ir_workspace.get_path):
            try:
                workspace_path = ir_workspace.get_path()
            except Exception:
                workspace_path = None
        if workspace_path is None and hasattr(ir_workspace, "path"):
            workspace_path = ir_workspace.path
        if workspace_path is None and hasattr(ir_workspace, "root"):
            workspace_path = ir_workspace.root

    if workspace_path is None:
        workspace_path = os.getcwd()

    # Prepare the command
    cmd = list(cli_args)  # copy to avoid side effects
    try:
        # Ensure we pass extra-vars as a JSON string
        extra_vars_json = json.dumps(vars_dict)
    except (TypeError, ValueError) as e:
        raise ValueError(f"Failed to serialize vars_dict to JSON: {e}") from e

    cmd.extend(["--extra-vars", extra_vars_json])

    # Run the command
    try:
        completed = subprocess.run(
            cmd,
            cwd=workspace_path,
            capture_output=True,
            text=True,
            check=False  # we handle non-zero stubs ourselves
        )
    except OSError as e:
        # Unable to execute the command
        return {
            "stdout": "",
            "stderr": f"Execution failed: {e}",
            "returncode": -1
        }
    except Exception as e:
        return {
            "stdout": "",
            "stderr": f"Unexpected error: {e}",
            "returncode": -1
        }

    return {
        "stdout": completed.stdout,
        "stderr": completed.stderr,
        "returncode": completed.returncode
    }

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to the correct types by modifying the supplied values_dict in-place.

        Args:
            parser_name (str): The command name, e.g. 'main', 'virsh', 'ospd', etc.
            values_dict (dict): Dictionary of argument names to values (typically all strings).

        This method looks up a mapping of argument names to target types for the given
        parser_name. If a mapping entry exists, the value is converted to that type.
        Supported target types are ``int``, ``float``, ``bool``, ``list`` and ``dict``.
        Conversion failures raise a ``ValueError`` with a helpful message.

        The method returns ``None`` but mutates *values_dict*.
        """
        # Retrieve type mapping for this parser, if any.
        # Derived classes may define _ARG_TYPES = {parser_name: {arg_name: type, ...}}
        type_map = getattr(self, "_ARG_TYPES", {}).get(parser_name, {})

        if not type_map:
            # Nothing to convert; return early.
            return

        for key, target_type in type_map.items():
            if key not in values_dict:
                continue  # Skip missing keys.

            raw_value = values_dict[key]
            # Skip conversion if already of correct type.
            if isinstance(raw_value, target_type):
                continue

            try:
                if target_type is int:
                    values_dict[key] = int(raw_value)
                elif target_type is float:
                    values_dict[key] = float(raw_value)
                elif target_type is bool:
                    # Accept common string representations of booleans.
                    if isinstance(raw_value, str):
                        lowered = raw_value.lower()
                        if lowered in {"true", "1", "yes", "on"}:
                            values_dict[key] = True
                        elif lowered in {"false", "0", "no", "off"}:
                            values_dict[key] = False
                        else:
                            raise ValueError(f"Cannot convert {raw_value!r} to bool")
                    else:
                        values_dict[key] = bool(raw_value)
                elif target_type is list:
                    # Assume comma separated values for strings; preserve existing list.
                    if isinstance(raw_value, str):
                        values_dict[key] = [item.strip() for item in raw_value.split(",") if item.strip()]
                    elif isinstance(raw_value, (list, tuple)):
                        values_dict[key] = list(raw_value)
                    else:
                        # Wrap single value in a list.
                        values_dict[key] = [raw_value]
                elif target_type is dict:
                    # Attempt to parse JSON string if necessary.
                    import json
                    if isinstance(raw_value, str):
                        values_dict[key] = json.loads(raw_value)
                    elif isinstance(raw_value, dict):
                        values_dict[key] = raw_value
                    else:
                        raise ValueError(f"Cannot convert {raw_value!r} to dict")
                else:
                    # Unknown target type: attempt to cast directly.
                    values_dict[key] = target_type(raw_value)

            except (TypeError, ValueError) as exc:
                msg = (
                    f"Error converting argument '{key}' (value={raw_value!r}) "
                    f"to type {target_type.__name__} for parser '{parser_name}': {exc}"
                )
                # If a logger is available on the instance, use it; otherwise raise.
                logger = getattr(self, "_logger", None)
                if logger and hasattr(logger, "error"):
                    logger.error(msg)
                raise ValueError(msg) from exc

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Helper function to safely convert string to int, float or bool.
        def _to_bool(s):
            if s.lower() == 'true':
                return True
            if s.lower() == 'false':
                return False
            return None

        def _to_numeric(s):
            try:
                return int(s)
            except ValueError:
                try:
                    return float(s)
                except ValueError:
                    return None

        def _to_list(s):
            parts = [p.strip() for p in s.split(',')]
            # Try to convert each part to int or float, keep as string otherwise
            converted_parts = []
            for p in parts:
                if p == '':
                    continue
                num = _to_numeric(p)
                if num is not None:
                    converted_parts.append(num)
                else:
                    b = _to_bool(p)
                    if b is not None:
                        converted_parts.append(b)
                    else:
                        converted_parts.append(p)
            return converted_parts

        for key, val in list(values_dict.items()):
            if not isinstance(val, str):
                continue
            s = val.strip()
            if s == '':
                continue

            # First handle list separator
            if ',' in s:
                values_dict[key] = _to_list(s)
                continue

            # Try boolean
            b = _to_bool(s)
            if b is not None:
                values_dict[key] = b
                continue

            # Try numeric (int or float)
            num = _to_numeric(s)
            if num is not None:
                values_dict[key] = num
                continue

            # If parser_name has known type overrides, add here if needed
            # (Example placeholders, can be extended by the caller)
            # if parser_name == 'virsh' and key in {'num_cpus'}:
            #     try:
            #         values_dict[key] = int(s)
            #     except ValueError:
            #         pass

            # Default: keep trimmed string
            values_dict[key] = s

        # Function mutates values_dict in place; return for convenience
        return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Cast arguments to correct types by modifying values_dict parameter.
    All input values are initially strings.  This method attempts to
    guess the intended type for each value and casts it accordingly.
    Validated input types are also applied when a parser specific
    type mapping is defined.  The method mutates values_dict in place
    and returns the updated dictionary for convenience.

    :param parser_name: The command name, e.g. 'main', 'virsh', 'ospd', etc.
    :param values_dict: Dictionary of argument names to string values.
    :return: The mutated values_dict with casted values.
    :raises TypeError: If parser_name is not a string or values_dict is not a dict.
    """

    # Basic input validation
    if not isinstance(parser_name, str):
        raise TypeError("parser_name must be a string")
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    # Optional parser-specific type mapping.  Add entries as needed.  The
    # mapping provides a callable that casts the string value to the
    # desired type.  Unknown keys fall back to generic guessing logic.
    parser_type_map = {
        "main": {
            "workers": int,
            "verbose": lambda v: str(v).lower() in ("true", "1"),
            "timeout": float,
        },
        "virsh": {
            "name": str,
            "timeout": int,
            "debug": lambda v: str(v).lower() in ("true", "1"),
            "nocache": lambda v: str(v).lower() in ("true", "1"),
        },
        "ospd": {
            "port": int,
            "use_ssl": lambda v: str(v).lower() in ("true", "1"),
            "cert_path": str,
            "workers": int,
        },
    }

    def _guess_cast(value):
        """Return a guessed cast of the given value."""
        if isinstance(value, str):
            s = value.strip()
            if s == "":
                return None
            low = s.lower()

            # None value
            if low == "none":
                return None

            # Boolean
            if low in ("true", "false"):
                return low == "true"
            if low in ("1", "0"):
                return low == "1"

            # Integer
            if s.lstrip("-").isdigit():
                try:
                    return int(s)
                except Exception:
                    pass

            # Float
            try:
                f = float(s)
                return f
            except Exception:
                pass

            # List (comma separated)
            if "," in s:
                parts = [p.strip() for p in s.split(",")]
                return [_guess_cast(p) for p in parts]

        # Fallback – return the original value
        return value

    # Process each key/value pair
    for key, raw_value in values_dict.items():
        try:
            # Use parser-specific cast if defined
            cast_fn = parser_type_map.get(parser_name, {}).get(key)
            if cast_fn is not None:
                try:
                    values_dict[key] = cast_fn(raw_value)
                except Exception:
                    # Silently ignore if cast fails – keep original string
                    pass
            else:
                # Generic guessing logic
                values_dict[key] = _guess_cast(raw_value)
        except Exception:
            # Ensure the dictionary is left at least in a usable state
            pass

    return values_dict

