def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary containing the plugin's properties
    """
    import os
    import json

    # Support YAML if available
    try:
        import yaml
    except Exception:
        yaml = None

    # Validate input
    if not plugin_dir:
        raise ValueError("plugin_dir must not be empty")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory not found: {plugin_dir}")

    # Determine spec file
    candidates = ["plugin.yml", "plugin.yaml", "plugin.json"]
    spec_path = None
    for name in candidates:
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_path = path
            break
    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Read and parse spec
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            content = f.read()
    except Exception as e:
        raise IOError(f"Could not read spec file {spec_path}: {e}")

    try:
        if spec_path.lower().endswith(".json"):
            spec_dict = json.loads(content)
        elif yaml and spec_path.lower().endswith((".yml", ".yaml")):
            spec_dict = yaml.safe_load(content)
        else:
            # Fallback: try JSON
            spec_dict = json.loads(content)
    except Exception as e:
        raise ValueError(f"Failed to parse spec file {spec_path}: {e}")

    if not isinstance(spec_dict, dict):
        raise ValueError("Spec file must contain a JSON/YAML object")

    # Flatten nested dictionary
    def flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return flatten(spec_dict)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        # Use standard json; optionally support yaml if available
        try:
            import yaml
            yaml_loaded = True
        except Exception:
            yaml_loaded = False

        if not isinstance(plugin_dir, str):
            raise TypeError("plugin_dir must be a string path")
        if not os.path.isdir(plugin_dir):
            raise FileNotFoundError(f"Directory does not exist: {plugin_dir}")

        # Determine spec file path
        spec_file = None
        for fname in ("plugin.json", "plugin.yml", "plugin.yaml"):
            candidate = os.path.join(plugin_dir, fname)
            if os.path.isfile(candidate):
                spec_file = candidate
                break

        if spec_file is None:
            raise FileNotFoundError("No plugin spec file (plugin.json, plugin.yml, or plugin.yaml) found.")

        # Load spec file
        try:
            with open(spec_file, 'r', encoding='utf-8') as f:
                if spec_file.lower().endswith('.json'):
                    spec = json.load(f)
                else:
                    if not yaml_loaded:
                        raise ImportError("PyYAML is required for loading .yml/.yaml plugin specs.")
                    spec = yaml.safe_load(f)
        except Exception as exc:
            raise ValueError(f"Failed to parse plugin spec: {exc}") from exc

        if not isinstance(spec, dict):
            raise ValueError(f"Plugin spec must be a dict, got {type(spec).__name__}")

        # Recursive flattening
        def _flatten(current, parent_key='', out=None):
            if out is None:
                out = {}
            if isinstance(current, dict):
                for k, v in current.items():
                    new_key = f"{parent_key}.{k}" if parent_key else k
                    _flatten(v, new_key, out)
            else:
                out[parent_key] = current
            return out

        flat_dict = _flatten(spec)
        return flat_dict

    except Exception as e:
        # If any unexpected error occurs, re-raise with a consistent type
        raise RuntimeError(f"Error generating plugin spec flatten dict: {e}") from e

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    The function looks for a plugin specification file in the
    supplied ``plugin_dir``. It supports the following file names,
    in order: ``plugin.yaml``, ``plugin.yml``, ``plugin.json``. The
    file is loaded using the appropriate parser, and then every
    nested dictionary is flattened by separating keys with a dot
    (`). Lists are left untouched.

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper to flatten a nested dictionary
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # List of possible spec files in order of preference
    candidates = (os.path.join(plugin_dir, "plugin.yaml"),
                  os.path.join(plugin_dir, "plugin.yml"),
                  os.path.join(plugin_dir, "plugin.json"))

    data = None
    for path in candidates:
        if os.path.isfile(path):
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    if path.lower().endswith(('.yaml', '.yml')):
                        try:
                            import yaml
                        except ImportError:
                            raise RuntimeError(
                                "PyYAML is required to load YAML plugin specifications."
                            )
                        data = yaml.safe_load(f)
                    else:
                        data = json.load(f)
                break
            except (OSError, json.JSONDecodeError, AttributeError) as e:
                # If the file can't be read or parsed, continue to next candidate
                data = None
                continue

    if data is None:
        raise FileNotFoundError(
            f"No plugin specification found in {plugin_dir}. "
            f"Expected one of: {', '.join(os.path.basename(c) for c in candidates)}"
        )

    if not isinstance(data, dict):
        raise ValueError(f"Plugin specification at {path} does not contain a dictionary.")

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = "CONFIG_PATH"
    try:
        if env_var not in os.environ:
            # Determine a default configuration file path.
            # Prefer relative to this file's directory, fallback to current working directory.
            if "__file__" in globals():
                default_path = os.path.join(os.path.dirname(__file__), "config.yaml")
            else:
                default_path = os.path.join(os.getcwd(), "config.yaml")
            os.environ[env_var] = default_path
    except Exception:
        # Silently ignore any error (e.g., missing __file__ or permission issues)
        pass

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    try:
        # Determine the environment variable name
        env_var = "CONFIG_PATH"
        # If the variable is already set, do nothing
        if os.getenv(env_var):
            return
        # Attempt to form a sensible default path
        try:
            script_dir = os.path.dirname(__file__)
        except NameError:
            script_dir = os.getcwd()
        default_config = os.path.join(script_dir, "config.yaml")
        # Set the environment variable
        os.environ[env_var] = default_config
    except Exception as exc:
        raise RuntimeError(f"Failed to inject config path: {exc}") from exc

def inject_config(self):
