def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param root_subparsers: the subparser object to extend.
    """
    try:
        # Validate input
        if root_subparsers is None:
            raise ValueError("root_subparsers cannot be None")

        # The subparsers object should provide an `add_parser` method.
        if not hasattr(root_subparsers, "add_parser"):
            raise AttributeError("root_subparsers must have an 'add_parser' method")

        # Add a top-level 'spec' command if it doesn't already exist
        # We attempt to add it; if it already exists argparse will raise a ValueError.
        try:
            parser_spec = root_subparsers.add_parser(
                "spec",
                help="Spec command options",
            )
        except ValueError:
            # `spec` parser already exists; retrieve it
            parser_spec = None
            for action in root_subparsers._actions:
                if isinstance(action, type(root_subparsers._subparsers._action)):
                    if action.dest == "spec":
                        parser_spec = action
                        break
            if parser_spec is None:
                raise

        # If we got the parser, attach common arguments
        if parser_spec:
            # Add optional argument for specifying the spec file
            parser_spec.add_argument(
                "--spec-file",
                type=str,
                default=None,
                help="Path to the spec file to operate on.",
            )
            # Add an optional output directory
            parser_spec.add_argument(
                "-o",
                "--output",
                type=str,
                default=None,
                help="Directory where output should be written.",
            )
            # Attach a simple placeholder function so the command can be executed
            def _handle_spec_command(args):
                # Minimal handler; real implementation will be provided elsewhere
                print(
                    f"Spec command invoked with spec-file={args.spec_file!r} and output={args.output!r}"
                )

            parser_spec.set_defaults(func=_handle_spec_command)

    except Exception as exc:
        # Re-raise with additional context for easier debugging
        raise RuntimeError(
            "Failed to extend the CLI with spec options. "
            + str(exc)
        ) from exc

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Normalize root by stripping any trailing path separators
    root_norm = root.rstrip('/\\')
    if not path.startswith(root_norm):
        raise ValueError(f"Root '{root}' not found at the start of path '{path}'.")
    # Ensure that the root is a distinct component (not a prefix of a longer name)
    if len(path) > len(root_norm):
        sep = path[len(root_norm)]
        if sep not in ('/', '\\'):
            raise ValueError(f"Root '{root}' does not match a directory component in path '{path}'.")
    # Strip root and return the remaining part
    return path[len(root_norm):]

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings.")
    if not root:
        raise ValueError("Root cannot be empty.")
    # Normalize both paths to absolute form
    abs_path = os.path.abspath(path)
    abs_root = os.path.abspath(root)
    try:
        # Ensure that root is a prefix of path
        if os.path.commonpath([abs_path, abs_root]) != abs_root:
            raise ValueError(f"Root '{root}' is not a parent of path '{path}'.")
        # Compute the relative path
        relative = os.path.relpath(abs_path, abs_root)
        # If the path is exactly the root, return empty string
        return "" if relative == "." else relative
    except ValueError as e:
        # os.path.commonpath can raise ValueError on different drives (Windows)
        raise ValueError(f"Failed to strip root: {e}") from e
    except Exception as e:
        raise ValueError(f"Unexpected error while stripping root: {e}") from e

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    if root == "":
        return path
    # Strip trailing separators from root to avoid double separators
    root = root.rstrip("/\\")
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    rest = path[len(root):]
    # Remove a leading separator, if present
    if rest.startswith(("/", "\\")):
        rest = rest[1:]
    return rest
